-- The schema a new Tico database starts from: backend/migrations/__init__.py loads it into an empty file, then runs
-- each migration file it does not record. Generated by scripts/schema_baseline.py; never edit it by hand.

CREATE TABLE humans (
  id TEXT PRIMARY KEY, name TEXT, email TEXT, slack_id TEXT, teams TEXT, time_zone TEXT, work_starts TEXT, work_ends TEXT, work_days TEXT, record_on_join INTEGER CHECK (record_on_join IN (0, 1)), idp_issuer TEXT, idp_sub TEXT);
CREATE TABLE conversations (
  id TEXT PRIMARY KEY, kind TEXT, subject TEXT, task_id TEXT, participants TEXT,
  created_at TEXT, last_message_at TEXT, closed_at TEXT, scope TEXT NOT NULL DEFAULT 'direct', owner_id TEXT, room_key TEXT, audience TEXT, audience_group_id TEXT, parent_id TEXT, parent_message_id TEXT, root_id TEXT, path TEXT, last_seq INTEGER NOT NULL DEFAULT 0, last_unread_seq INTEGER NOT NULL DEFAULT 0, archived_at TEXT, updated_at TEXT, retention_days INTEGER, pinned_for_everyone_at TEXT, deleted_at TEXT);
CREATE TABLE messages (
  id TEXT PRIMARY KEY, conversation_id TEXT REFERENCES conversations(id),
  sender_id TEXT, recipient_id TEXT, kind TEXT, body TEXT, refs TEXT, in_reply_to TEXT,
  created_at TEXT, delivered_at TEXT, read_at TEXT, expires_at TEXT, wait_s INTEGER, answered_by_id TEXT, seq INTEGER, origin_id TEXT, revision INTEGER NOT NULL DEFAULT 0, restricted INTEGER NOT NULL DEFAULT 0, legacy_audience TEXT, edited_at TEXT, deleted_at TEXT, wake_key TEXT, superseded_at TEXT, public INTEGER NOT NULL DEFAULT 0, hidden_at TEXT);
CREATE TABLE bot_status_history (
  id TEXT PRIMARY KEY, bot TEXT, state TEXT, focus TEXT, task_id TEXT,
  started_at TEXT, ended_at TEXT, reason TEXT, by TEXT);
CREATE TABLE schedules (
  id TEXT PRIMARY KEY, bot TEXT, cron TEXT, title TEXT, playbook TEXT,
  last_fired_at TEXT, next_due_at TEXT, source TEXT, routine_key TEXT, definition TEXT NOT NULL DEFAULT '{}', source_repo TEXT NOT NULL DEFAULT '', source_revision TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 0, deleted_at TEXT, updated_at TEXT, event_name TEXT);
CREATE TABLE deltas (
  id TEXT PRIMARY KEY, attempt_id TEXT, seq INTEGER, kind TEXT, text TEXT, created_at TEXT);
CREATE TABLE rate_limits (
  runtime TEXT PRIMARY KEY, used_percent REAL, window_minutes INTEGER,
  resets_at TEXT, updated_at TEXT);
CREATE TABLE refusals (
  id TEXT PRIMARY KEY, created_at TEXT, actor TEXT, rule TEXT, detail TEXT, severity TEXT);
CREATE TABLE events (
  id TEXT PRIMARY KEY, created_at TEXT, actor TEXT, action TEXT, target TEXT, detail TEXT);
CREATE TABLE meetings (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, owner TEXT NOT NULL,
 recorded_by TEXT, uploaded_by TEXT, metadata TEXT NOT NULL,
 transcript_original TEXT NOT NULL DEFAULT '', transcript_readable TEXT NOT NULL DEFAULT '',
 notes TEXT NOT NULL DEFAULT '', content_hash TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
, review_state TEXT NOT NULL DEFAULT 'live'
 CHECK (review_state IN ('pending','live','dismissed')));
CREATE TABLE meeting_versions (
 id INTEGER PRIMARY KEY AUTOINCREMENT, meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
 content_hash TEXT NOT NULL, metadata TEXT NOT NULL, transcript_original TEXT NOT NULL,
 transcript_readable TEXT NOT NULL, notes TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(meeting_id, content_hash)
);
CREATE TABLE meeting_deliveries (
 meeting_id TEXT PRIMARY KEY REFERENCES meetings(id) ON DELETE CASCADE,
 requested_by TEXT NOT NULL, sender_name TEXT NOT NULL, destination TEXT NOT NULL,
 instructions TEXT NOT NULL, attachments TEXT NOT NULL DEFAULT '[]',
 status TEXT NOT NULL DEFAULT 'pending', task_id TEXT, error TEXT, attempts INTEGER NOT NULL DEFAULT 0,
 requested_at TEXT NOT NULL, delivered_at TEXT
);
CREATE TABLE task_delegations (
 task_id TEXT NOT NULL REFERENCES tasks(id), delegate TEXT NOT NULL, requested_by TEXT NOT NULL,
 message_id TEXT PRIMARY KEY REFERENCES messages(id), expires_at TEXT NOT NULL
);
CREATE TABLE meeting_items (
 id TEXT PRIMARY KEY,
 meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
 section TEXT NOT NULL CHECK (section IN ('doc','task','feature','decision','question')),  -- the last two: legacy rows, never listed
 text TEXT NOT NULL,
 detail TEXT NOT NULL DEFAULT '{}',
 quote TEXT NOT NULL DEFAULT '',
 at_ms INTEGER,
 status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','pushed','dismissed')),
 created_by TEXT NOT NULL,
 updated_by TEXT,
 pushed_at TEXT,
 result_ref TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL
, version INTEGER NOT NULL DEFAULT 1, proposed_task_id TEXT REFERENCES tasks(id) ON DELETE SET NULL);
CREATE TABLE meeting_brain (
 meeting_id TEXT PRIMARY KEY REFERENCES meetings(id) ON DELETE CASCADE,
 last_think_at TEXT,
 last_turn_index INTEGER NOT NULL DEFAULT 0,
 runs INTEGER NOT NULL DEFAULT 0,
 last_error TEXT,
 error_at TEXT,
 final_at TEXT,
 updated_at TEXT NOT NULL
);
CREATE TABLE meeting_comments (
 id TEXT PRIMARY KEY,
 meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
 author TEXT NOT NULL,
 text TEXT NOT NULL,
 at_ms INTEGER,
 created_at TEXT NOT NULL
);
CREATE TABLE kpis (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, unit TEXT NOT NULL DEFAULT '',
  target REAL, created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, slug TEXT, definition TEXT NOT NULL DEFAULT '', direction TEXT NOT NULL DEFAULT 'up', cadence TEXT NOT NULL DEFAULT 'weekly', owner_id TEXT, source_note TEXT NOT NULL DEFAULT '', definition_version INTEGER NOT NULL DEFAULT 1, updated_at TEXT, archived_at TEXT, archived_by_id TEXT, parent_kpi_id TEXT, growth_role TEXT, stage TEXT, loop_name TEXT, loop_step INTEGER);
CREATE TABLE kpi_readings (
  id TEXT PRIMARY KEY, kpi_id TEXT NOT NULL, measured_at TEXT NOT NULL, value REAL NOT NULL,
  actor_id TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'measured', note TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL, period_start TEXT, period_end TEXT, collected_at TEXT, evidence TEXT NOT NULL DEFAULT '', quality TEXT NOT NULL DEFAULT 'measured', definition_version INTEGER NOT NULL DEFAULT 1, supersedes TEXT);
CREATE TABLE recording_source_refs (
 source TEXT NOT NULL, resource_type TEXT NOT NULL, external_id TEXT NOT NULL,
 meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL,
 PRIMARY KEY(source,resource_type,external_id)
);
CREATE TABLE recording_transcripts (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
 source TEXT NOT NULL, resource_type TEXT NOT NULL, external_id TEXT NOT NULL,
 transcript_index INTEGER NOT NULL DEFAULT 0,
 content_hash TEXT NOT NULL, source_updated_at TEXT NOT NULL,
 turns TEXT NOT NULL, transcript_text TEXT NOT NULL, summary_text TEXT NOT NULL DEFAULT '',
 imported_at TEXT NOT NULL
);
CREATE TABLE market_evidence (
  id TEXT PRIMARY KEY,
  source_url TEXT NOT NULL DEFAULT '',
  source_kind TEXT NOT NULL DEFAULT 'other',
  captured_at TEXT,
  captured_by TEXT NOT NULL,
  quote TEXT NOT NULL DEFAULT '',
  our_read TEXT NOT NULL DEFAULT '',
  blob_id TEXT, fts_rowid INTEGER);
CREATE TABLE market_citations (
  claim_kind TEXT NOT NULL,
  claim_id TEXT NOT NULL,
  evidence_id TEXT NOT NULL,
  PRIMARY KEY (claim_kind, claim_id, evidence_id));
CREATE TABLE market_insights (
  id TEXT PRIMARY KEY,
  reported_by TEXT NOT NULL,
  reported_at TEXT NOT NULL,
  kind TEXT NOT NULL,
  about TEXT NOT NULL DEFAULT '',
  claim TEXT NOT NULL DEFAULT '',
  source_url TEXT NOT NULL DEFAULT '',
  quote TEXT NOT NULL DEFAULT '',
  confidence TEXT NOT NULL DEFAULT 'medium',
  urgent INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'new',
  resolution TEXT NOT NULL DEFAULT '',
  applied_events TEXT NOT NULL DEFAULT '[]',
  resolved_at TEXT,
  resolved_by TEXT,
  filed_task TEXT, source_ref TEXT);
CREATE TABLE goal_kpis (
  id TEXT PRIMARY KEY, goal_id TEXT NOT NULL, kpi_id TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'none',
  baseline REAL, baseline_at TEXT, target REAL, deadline TEXT, min REAL, max REAL,
  created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by_id TEXT NOT NULL,
  UNIQUE (goal_id, kpi_id));
CREATE TABLE kpi_definitions (
  id TEXT PRIMARY KEY, kpi_id TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, actor TEXT NOT NULL,
  name TEXT NOT NULL, definition TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL DEFAULT '',
  direction TEXT NOT NULL, cadence TEXT NOT NULL, source_note TEXT NOT NULL DEFAULT '',
  UNIQUE (kpi_id, version));
CREATE TABLE goal_checkins (
  id TEXT PRIMARY KEY, goal_id TEXT NOT NULL, kpi_id TEXT, created_at TEXT NOT NULL, author TEXT NOT NULL,
  sender_id TEXT NOT NULL, body TEXT NOT NULL, signal TEXT);
CREATE TABLE usage_alerts (
  bot TEXT NOT NULL, period TEXT NOT NULL, level INTEGER NOT NULL, sent TEXT NOT NULL,
  PRIMARY KEY (bot, period, level));
CREATE TABLE tags (
  id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, label TEXT NOT NULL,
  metadata TEXT NOT NULL DEFAULT '{}', markdown TEXT NOT NULL DEFAULT '',
  is_template INTEGER NOT NULL DEFAULT 0, template_id TEXT REFERENCES tags(id),
  owner TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, bot_writers TEXT NOT NULL DEFAULT '[]');
CREATE TABLE task_tags (
  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  tag_id TEXT NOT NULL REFERENCES tags(id), PRIMARY KEY(task_id, tag_id));
CREATE TABLE repositories(
 id TEXT PRIMARY KEY, full_name TEXT UNIQUE COLLATE NOCASE,
 enabled INTEGER DEFAULT 0, bot_repo INTEGER DEFAULT 0,
 default_branch TEXT, setup_command TEXT, setup_source TEXT,
 reachable INTEGER DEFAULT 1, last_seen_at TEXT, added_by TEXT, updated_at TEXT);
CREATE TABLE bot_repo_access(
 bot TEXT, full_name TEXT COLLATE NOCASE,
 access TEXT CHECK(access IN ('read','write')), PRIMARY KEY(bot,full_name));
CREATE TABLE task_links(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id),
  kind TEXT NOT NULL, url TEXT NOT NULL, title TEXT, state TEXT, added_by TEXT, created_at TEXT NOT NULL,
  pr_sha TEXT, pr_merged_at TEXT, repo TEXT, number INTEGER, branch TEXT, computer_id TEXT, path TEXT, checks TEXT, mergeable TEXT, review_state TEXT, pending_comments INTEGER, detail TEXT, updated_at TEXT, activity_at TEXT, source TEXT, item_type TEXT, item_key TEXT COLLATE NOCASE);
CREATE TABLE subscription_assignments(
    scope TEXT NOT NULL CHECK(scope IN ('group','bot')),
    target TEXT NOT NULL, profile TEXT NOT NULL, updated_at TEXT, updated_by TEXT,
    PRIMARY KEY(scope,target)
);
CREATE TABLE computer_profiles(
    runner_id TEXT NOT NULL, profile TEXT NOT NULL, runtimes TEXT, updated_at TEXT,
    PRIMARY KEY(runner_id,profile)
);
CREATE TABLE bot_file_versions(
 file_id TEXT NOT NULL REFERENCES bot_files(id), version INTEGER NOT NULL,
 blob_id TEXT NOT NULL REFERENCES blobs(id), digest TEXT NOT NULL, source_digest TEXT,
 size INTEGER NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, commit_sha TEXT, repo_path TEXT,
 attempt_id TEXT, actor TEXT NOT NULL, created_at TEXT NOT NULL, width INTEGER, height INTEGER, duration_ms INTEGER, poster_blob_id TEXT REFERENCES blobs(id), thumb_blob_id TEXT REFERENCES blobs(id), media_state TEXT NOT NULL DEFAULT 'none'
 CHECK(media_state IN ('ready','pending','none')), PRIMARY KEY(file_id, version));
CREATE TABLE blob_locations(
 digest TEXT NOT NULL, bucket TEXT NOT NULL, verified_at TEXT NOT NULL,
 PRIMARY KEY(digest,bucket));
CREATE TABLE blob_media(
 blob_id TEXT PRIMARY KEY REFERENCES blobs(id), width INTEGER, height INTEGER, duration_ms INTEGER,
 poster_blob_id TEXT REFERENCES blobs(id), thumb_blob_id TEXT REFERENCES blobs(id),
 media_state TEXT NOT NULL DEFAULT 'pending' CHECK(media_state IN ('ready','pending','none')));
CREATE TABLE blob_media_retries(
 blob_id TEXT PRIMARY KEY REFERENCES blobs(id), attempts INTEGER NOT NULL DEFAULT 0,
 retry_at REAL NOT NULL DEFAULT 0);
CREATE TABLE task_file_reviews(
 file_id TEXT NOT NULL, version INTEGER NOT NULL, note TEXT,
 ask_message_id TEXT REFERENCES messages(id), comment_id TEXT REFERENCES messages(id),
 PRIMARY KEY(file_id,version));
CREATE TABLE live_meetings (
 id TEXT PRIMARY KEY,
 owner_actor TEXT NOT NULL,
 title TEXT NOT NULL,
 state TEXT NOT NULL CHECK (state IN ('live','paused','ended')),
 client_id TEXT,
 seq INTEGER NOT NULL DEFAULT 0,
 next_event_id INTEGER NOT NULL DEFAULT 0,
 window_ms INTEGER NOT NULL CHECK (window_ms BETWEEN 15000 AND 45000),
 cooldown_ms INTEGER NOT NULL DEFAULT 60000,
 threshold REAL NOT NULL DEFAULT 0.7,
 imported_meeting_id TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 started_at TEXT NOT NULL,
 ended_at TEXT, reply_cap INTEGER NOT NULL DEFAULT 3 CHECK (reply_cap BETWEEN 1 AND 20), visibility TEXT NOT NULL DEFAULT 'team' CHECK (visibility IN ('private','team')), meeting_model TEXT, thread_id TEXT, discarded_at TEXT,
 UNIQUE(owner_actor,client_id)
);
CREATE TABLE live_meeting_humans (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 actor TEXT NOT NULL,
 joined_at TEXT NOT NULL,
 PRIMARY KEY(meeting_id,actor)
);
CREATE TABLE live_meeting_bots (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 bot TEXT NOT NULL,
 joined_by TEXT NOT NULL,
 joined_at TEXT NOT NULL,
 last_reply_ms INTEGER, conversation_id TEXT,
 PRIMARY KEY(meeting_id,bot)
);
CREATE TABLE live_meeting_chunks (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 seq INTEGER NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1,
 speaker TEXT NOT NULL,
 start_ms INTEGER NOT NULL,
 end_ms INTEGER NOT NULL,
 text TEXT NOT NULL,
 created_at TEXT NOT NULL,
 PRIMARY KEY(meeting_id,seq)
);
CREATE TABLE live_meeting_chunk_versions (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 seq INTEGER NOT NULL,
 revision INTEGER NOT NULL,
 speaker TEXT NOT NULL,
 start_ms INTEGER NOT NULL,
 end_ms INTEGER NOT NULL,
 text TEXT NOT NULL,
 authored_by TEXT NOT NULL,
 created_at TEXT NOT NULL,
 PRIMARY KEY(meeting_id,seq,revision)
);
CREATE TABLE live_meeting_chat (
 id TEXT PRIMARY KEY,
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 actor TEXT NOT NULL,
 role TEXT NOT NULL CHECK (role IN ('human','bot')),
 text TEXT NOT NULL,
 at_ms INTEGER,
 transcript_seq INTEGER,
 turn_id TEXT,
 created_at TEXT NOT NULL
);
CREATE TABLE live_meeting_events (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 event_id INTEGER NOT NULL,
 type TEXT NOT NULL,
 payload TEXT NOT NULL,
 created_at TEXT NOT NULL,
 PRIMARY KEY(meeting_id,event_id)
);
CREATE TABLE live_meeting_windows (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 window_index INTEGER NOT NULL,
 start_ms INTEGER NOT NULL,
 end_ms INTEGER NOT NULL,
 status TEXT NOT NULL CHECK (status IN ('deciding','complete','interrupted')),
 outcome TEXT NOT NULL DEFAULT '',
 trace TEXT NOT NULL DEFAULT '{}',
 started_at TEXT NOT NULL,
 finished_at TEXT,
 PRIMARY KEY(meeting_id,window_index)
);
CREATE TABLE live_meeting_turns (
 id TEXT PRIMARY KEY,
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 bot TEXT NOT NULL,
 window_index INTEGER,
 source_key TEXT NOT NULL,
 transcript_seq INTEGER,
 status TEXT NOT NULL CHECK (status IN ('pending','claimed','replied','skipped')),
 skip_reason TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL,
 claimed_at TEXT,
 replied_at TEXT, retries INTEGER NOT NULL DEFAULT 0, ran_model TEXT, claim_owner TEXT,
 UNIQUE(meeting_id,source_key,bot)
);
CREATE TABLE live_meeting_chat_routes (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 chat_id TEXT NOT NULL REFERENCES live_meeting_chat(id) ON DELETE CASCADE,
 status TEXT NOT NULL CHECK (status IN ('deciding','complete')),
 outcome TEXT NOT NULL DEFAULT '',
 trace TEXT NOT NULL DEFAULT '{}',
 started_at TEXT NOT NULL,
 finished_at TEXT,
 PRIMARY KEY(meeting_id,chat_id)
);
CREATE TABLE task_relations(
  from_task TEXT NOT NULL REFERENCES tasks(id), to_task TEXT NOT NULL REFERENCES tasks(id),
  kind TEXT NOT NULL CHECK (kind IN ('parent','related','duplicate_of','follow_up','after','depends_on')),
  created_by TEXT, created_at TEXT NOT NULL,
  until TEXT CHECK (until IS NULL OR (kind = 'depends_on' AND until = 'released')),
  PRIMARY KEY(from_task, to_task, kind),
  CHECK (from_task <> to_task), CHECK (kind <> 'related' OR from_task < to_task));
CREATE TABLE triggers (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'webhook',
  secret_hash TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, deleted_at TEXT, signing_secret TEXT, preset TEXT NOT NULL DEFAULT 'none', type_from TEXT NOT NULL DEFAULT '', hourly INTEGER, keep_days INTEGER NOT NULL DEFAULT 7, unheard TEXT NOT NULL DEFAULT 'log', unheard_noted TEXT, consumer TEXT NOT NULL DEFAULT 'automations');
CREATE TABLE trigger_deliveries (
  trigger_id TEXT NOT NULL, delivery TEXT NOT NULL, received_at TEXT NOT NULL,
  bytes INTEGER NOT NULL DEFAULT 0, tasks INTEGER NOT NULL DEFAULT 0, outcome TEXT NOT NULL DEFAULT 'accepted', reason TEXT NOT NULL DEFAULT '', sent_id TEXT NOT NULL DEFAULT '', type TEXT NOT NULL DEFAULT '', via TEXT NOT NULL DEFAULT 'direct', rules INTEGER NOT NULL DEFAULT 0, rule_results TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(trigger_id, delivery));
CREATE TABLE task_check_models (
  task_id TEXT PRIMARY KEY REFERENCES tasks(id), runtime TEXT NOT NULL, model TEXT NOT NULL,
  harness TEXT NOT NULL, effort TEXT NOT NULL DEFAULT '', role TEXT NOT NULL, created_by TEXT, created_at TEXT);
CREATE TABLE goal_asks (
  kind TEXT NOT NULL, ref TEXT NOT NULL, owner TEXT NOT NULL, task_id TEXT NOT NULL, created_at TEXT NOT NULL,
  PRIMARY KEY (kind, ref, owner));
CREATE TABLE live_meeting_access (
 meeting_id TEXT NOT NULL REFERENCES live_meetings(id) ON DELETE CASCADE,
 actor TEXT NOT NULL,
 added_by TEXT NOT NULL,
 added_at TEXT NOT NULL,
 PRIMARY KEY(meeting_id,actor)
);
CREATE TABLE market_sizes (
  id TEXT PRIMARY KEY,
  segment_id TEXT NOT NULL,
  dimension TEXT NOT NULL DEFAULT 'offering',
  basis TEXT NOT NULL DEFAULT 'product',
  year INTEGER NOT NULL,
  spend_usd REAL NOT NULL,
  low_usd REAL NOT NULL,
  high_usd REAL NOT NULL,
  growth_pct REAL,
  method TEXT NOT NULL,
  arithmetic TEXT NOT NULL DEFAULT '',
  formula TEXT,
  params TEXT NOT NULL DEFAULT '{}',
  evidence_ids TEXT NOT NULL DEFAULT '[]',
  confidence TEXT NOT NULL DEFAULT 'medium',
  overlaps TEXT NOT NULL DEFAULT '',
  spread TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'proposed',
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL);
CREATE TABLE market_figures (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL,
  segment_id TEXT NOT NULL,
  metric TEXT NOT NULL,
  value REAL,
  text TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL,
  as_of TEXT NOT NULL,
  evidence_id TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL);
CREATE TABLE market_sources (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  kind TEXT NOT NULL,
  covers TEXT NOT NULL DEFAULT '[]',
  access TEXT NOT NULL,
  reliability TEXT NOT NULL,
  how TEXT NOT NULL DEFAULT '',
  url TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL);
CREATE TABLE rule_events_seen (
  event TEXT NOT NULL, trigger TEXT NOT NULL, delivery TEXT NOT NULL, seen_at TEXT NOT NULL,
  PRIMARY KEY(event, trigger, delivery));
CREATE TABLE rule_task_runs (
  rule_id TEXT NOT NULL, task_id TEXT NOT NULL, event TEXT NOT NULL, revision TEXT NOT NULL,
  ran_at TEXT NOT NULL, fired INTEGER NOT NULL DEFAULT 0, webhook_event_id TEXT,
  PRIMARY KEY(rule_id,task_id,event,revision));
CREATE TABLE rule_task_state (
  rule_id TEXT PRIMARY KEY, paused_at TEXT, pause_reason TEXT,
  last_error TEXT, last_error_at TEXT);
CREATE TABLE trigger_bodies (
  trigger_id TEXT NOT NULL, delivery TEXT NOT NULL, received_at TEXT NOT NULL, expires_at TEXT NOT NULL,
  type TEXT NOT NULL DEFAULT '', via TEXT NOT NULL DEFAULT 'direct',
  headers TEXT NOT NULL DEFAULT '{}', body BLOB NOT NULL, outcome TEXT NOT NULL DEFAULT 'accepted',
  PRIMARY KEY(trigger_id, delivery));
CREATE TABLE trigger_seen (
  trigger_id TEXT NOT NULL, delivery TEXT NOT NULL, seen_at TEXT NOT NULL, replay INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(trigger_id, delivery));
CREATE TABLE trigger_relays (
  relay_id TEXT PRIMARY KEY, trigger_id TEXT NOT NULL, address_prefix TEXT NOT NULL,
  created_by TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT, hq_gone INTEGER NOT NULL DEFAULT 0, wake INTEGER);
CREATE TABLE hook_relay_state (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1), cursor INTEGER NOT NULL DEFAULT 0,
  acked INTEGER NOT NULL DEFAULT 0, last_pull_at REAL, failing_since REAL,
  last_error TEXT NOT NULL DEFAULT '', stopped_for TEXT NOT NULL DEFAULT '',
  pending INTEGER, oldest TEXT, pending_at REAL, wake_url TEXT, wake_url_set_at TEXT, wake_url_set_by TEXT);
CREATE TABLE webhooks (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, host TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1, events TEXT NOT NULL DEFAULT '[]',
  secret TEXT NOT NULL DEFAULT '', secret_prev TEXT NOT NULL DEFAULT '', secret_prev_until TEXT,
  rate_per_hour INTEGER NOT NULL DEFAULT 600, allow_http INTEGER NOT NULL DEFAULT 0,
  created_by TEXT NOT NULL, requested_by TEXT NOT NULL DEFAULT '', paused_reason TEXT NOT NULL DEFAULT '',
  notified_at TEXT, notify_task TEXT, window_start TEXT, window_count INTEGER NOT NULL DEFAULT 0,
  revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, filter TEXT NOT NULL DEFAULT '{}', headers TEXT NOT NULL DEFAULT '[]', disabled_at TEXT, disabled_reason TEXT NOT NULL DEFAULT '', failing_since TEXT);
CREATE TABLE webhook_events (
  id TEXT PRIMARY KEY, type TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1,
  payload TEXT NOT NULL DEFAULT '{}', actor TEXT NOT NULL DEFAULT '', skipped INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL, only_id TEXT NOT NULL DEFAULT '');
CREATE TABLE webhook_sends (
  id TEXT PRIMARY KEY, event_id TEXT NOT NULL, webhook_id TEXT NOT NULL, type TEXT NOT NULL,
  subject TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'ready',
  attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, claimed_at TEXT, claim_token TEXT,
  last_status INTEGER, last_error TEXT NOT NULL DEFAULT '', delivered_at TEXT, created_at TEXT NOT NULL,
  UNIQUE(webhook_id, event_id));
CREATE TABLE webhook_attempts (
  send_id TEXT NOT NULL, webhook_id TEXT NOT NULL, n INTEGER NOT NULL, created_at TEXT NOT NULL,
  timestamp_sent INTEGER NOT NULL, status INTEGER, ms INTEGER NOT NULL DEFAULT 0,
  response_head TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(send_id, n));
CREATE TABLE sleep_idle_state (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1), hours INTEGER NOT NULL DEFAULT 0,
  runners INTEGER NOT NULL DEFAULT 1, changed_by TEXT NOT NULL DEFAULT '', changed_at TEXT,
  hosted INTEGER, layout TEXT NOT NULL DEFAULT '', checked_at REAL,
  last_request_at REAL, last_result TEXT NOT NULL DEFAULT '', last_wake_at TEXT,
  last_error TEXT NOT NULL DEFAULT '', failures INTEGER NOT NULL DEFAULT 0, next_ask REAL);
CREATE TABLE tico_notices (
  notice_id TEXT PRIMARY KEY, kind TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, url TEXT NOT NULL DEFAULT '',
  sent_at TEXT NOT NULL DEFAULT '', received_at TEXT NOT NULL, delivery TEXT NOT NULL DEFAULT '');
CREATE TABLE compact_first(
  bot TEXT NOT NULL, conversation_id TEXT NOT NULL, marked_at TEXT NOT NULL, taken_by TEXT,
  PRIMARY KEY(bot, conversation_id));
CREATE TABLE task_caps(sender TEXT, receiver TEXT, per_day INTEGER, updated_at TEXT, updated_by TEXT,
  PRIMARY KEY(sender, receiver));
CREATE TABLE task_cap_log(task_id TEXT NOT NULL, sender TEXT NOT NULL, receiver TEXT NOT NULL,
  sent_at TEXT NOT NULL, PRIMARY KEY(task_id, sender, receiver, sent_at));
CREATE TABLE task_run_models (
  task_id TEXT PRIMARY KEY REFERENCES tasks(id), runtime TEXT NOT NULL, model TEXT NOT NULL,
  harness TEXT NOT NULL, effort TEXT NOT NULL DEFAULT '', set_by TEXT, set_at TEXT, compact_at INTEGER);
CREATE TABLE mail_items (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL, external_id TEXT NOT NULL,
  address TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT '', received_at TEXT NOT NULL,
  num_pages INTEGER, contains_checks INTEGER NOT NULL DEFAULT 0, file_id TEXT, blob_id TEXT, kind TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '',
  sender TEXT NOT NULL DEFAULT '', deadline TEXT, status TEXT NOT NULL DEFAULT 'new',
  task_id TEXT, delivery TEXT NOT NULL DEFAULT '', raw TEXT NOT NULL DEFAULT '{}',
  attempts INTEGER NOT NULL DEFAULT 0, next_try_at TEXT, error TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL, read_at TEXT,
  UNIQUE(provider, external_id));
CREATE TABLE mail_intake (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1), inbox_id TEXT NOT NULL, set_by TEXT NOT NULL, set_at TEXT NOT NULL, senders TEXT NOT NULL DEFAULT '[]');
CREATE TABLE mail_reads (item_id TEXT NOT NULL, read_at TEXT NOT NULL);
CREATE TABLE brand_drafts (
  id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 0,
  updated_by TEXT, updated_at TEXT);
CREATE TABLE brand_versions (
  id TEXT PRIMARY KEY, n INTEGER NOT NULL UNIQUE, body TEXT NOT NULL DEFAULT '{}', note TEXT NOT NULL DEFAULT '',
  published_by TEXT, published_at TEXT NOT NULL);
CREATE TABLE gtm_sources (
  id TEXT PRIMARY KEY, truth_for TEXT NOT NULL, system TEXT NOT NULL,
  reach_kind TEXT NOT NULL CHECK(reach_kind IN ('mcp','credential','url','person')), reach_ref TEXT NOT NULL DEFAULT '',
  may TEXT NOT NULL DEFAULT '', owner_ref TEXT, created_at TEXT NOT NULL, retired_at TEXT, sync_kind TEXT CHECK (sync_kind IS NULL OR sync_kind IN ('file','db_query','finance_ad_spend','bot_cost')), sync_map TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(sync_map)), refresh_hours INTEGER, last_run_at TEXT, last_good_run_at TEXT, last_error TEXT, failing_since TEXT, last_payload TEXT);
CREATE TABLE growth_channels (
  id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
  track TEXT NOT NULL DEFAULT 'performance' CHECK(track IN ('performance','brand')),
  stage TEXT NOT NULL DEFAULT 'idea' CHECK(stage IN ('idea','testing','scaling','paused')),
  owner_ref TEXT, budget_month REAL, source_id TEXT, why TEXT NOT NULL DEFAULT '', guardrail_kpi_id TEXT,
  guardrail_max REAL, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, retired_at TEXT, input_kpi_id TEXT);
CREATE TABLE growth_cohorts (
  id TEXT PRIMARY KEY, channel_id TEXT, month TEXT NOT NULL, spend REAL, bot_cost REAL, new_customers INTEGER,
  kept_d30 REAL, kept_d90 REAL, kept_d180 REAL, revenue_month REAL, margin_pct REAL,
  quality TEXT NOT NULL DEFAULT 'actual' CHECK(quality IN ('actual','estimate')), sources TEXT NOT NULL DEFAULT '{}',
  updated_by TEXT, updated_at TEXT NOT NULL);
CREATE TABLE growth_settings (
  id INTEGER PRIMARY KEY CHECK(id=1), unit TEXT NOT NULL DEFAULT 'customers', revenue_month REAL, margin_pct REAL, min_cohort INTEGER, time_zone TEXT, key_readers TEXT);
CREATE TABLE browser_exits (
  runner_id TEXT PRIMARY KEY, sharing INTEGER NOT NULL DEFAULT 0, bots TEXT NOT NULL DEFAULT '[]',
  daily_cap_bytes INTEGER NOT NULL DEFAULT 5000000000, generation INTEGER NOT NULL DEFAULT 1,
  changed_by TEXT, changed_at TEXT);
CREATE TABLE bot_browser_exits (
  bot TEXT PRIMARY KEY, runner_id TEXT, generation INTEGER NOT NULL DEFAULT 1, set_by TEXT, set_at TEXT);
CREATE TABLE browser_exit_usage (
  runner_id TEXT NOT NULL, day TEXT NOT NULL, bot TEXT NOT NULL, host TEXT NOT NULL,
  bytes INTEGER NOT NULL DEFAULT 0, tunnels INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(runner_id, day, bot, host));
CREATE TABLE browser_exit_marks (boot TEXT PRIMARY KEY, seq INTEGER NOT NULL);
CREATE TABLE schema_migrations(version TEXT PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE audit_log(
 id TEXT PRIMARY KEY, "created_at" TEXT NOT NULL, actor TEXT NOT NULL, object TEXT NOT NULL,
 "before" TEXT, "after" TEXT, via TEXT);
CREATE TABLE bots (
  id TEXT PRIMARY KEY NOT NULL, slug TEXT NOT NULL UNIQUE, display_name TEXT, effort TEXT,
  state TEXT DEFAULT 'active', created_at TEXT, last_turn_at TEXT,
 CONSTRAINT status_values_state CHECK (state IN ('active', 'paused', 'planned', 'quarantined', 'archived'))
);
CREATE TABLE bot_status (
  bot TEXT PRIMARY KEY, state TEXT, focus TEXT, task_id TEXT, changed_at TEXT, last_turn_at TEXT,
  last_result TEXT, next_due_at TEXT, open_tasks INTEGER DEFAULT 0, needs_human INTEGER DEFAULT 0,
  updated_at TEXT,
 CONSTRAINT status_values_state CHECK (state IN ('idle', 'running', 'waiting_human', 'waiting_bot', 'blocked', 'limited', 'crashed', 'paused', 'quarantined'))
);
CREATE TABLE goals (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, owner_id TEXT NOT NULL, parent_id TEXT,
  body TEXT NOT NULL DEFAULT '', status TEXT, status_note TEXT NOT NULL DEFAULT '',
  status_by_id TEXT, status_at TEXT, rank INTEGER,
  last_read_at TEXT, last_read_by_id TEXT,
  created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, updated_at TEXT NOT NULL, status_source TEXT, suggest_status TEXT, suggest_note TEXT, suggest_at TEXT, why TEXT NOT NULL DEFAULT '', why_by_id TEXT, why_at TEXT, bet_id TEXT,
 CONSTRAINT status_values_status CHECK (status IN ('red', 'yellow', 'green', 'gray', 'done', 'dropped')),
 CONSTRAINT status_values_status_source CHECK (status_source IN ('person', 'auto')),
 CONSTRAINT status_values_suggest_status CHECK (suggest_status IN ('red', 'yellow', 'green'))
);
CREATE TABLE goal_proposals (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, goal_id TEXT, kpi_id TEXT, payload TEXT NOT NULL DEFAULT '{}',
  reason TEXT NOT NULL DEFAULT '', proposed_by TEXT NOT NULL, proposed_at TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending', decided_by TEXT, decided_at TEXT, decision_note TEXT NOT NULL DEFAULT '',
  result TEXT,
 CONSTRAINT status_values_status CHECK (status IN ('pending', 'confirmed', 'rejected'))
);
CREATE TABLE strategy_actions (
  id TEXT PRIMARY KEY, created_at TEXT NOT NULL, actor TEXT NOT NULL, kind TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '',
  goal_id TEXT, state TEXT NOT NULL, proposal_task TEXT, note TEXT NOT NULL DEFAULT '',
  changes TEXT NOT NULL DEFAULT '{}', undone_at TEXT, undone_by TEXT, undo TEXT,
 CONSTRAINT status_values_state CHECK (state IN ('proposed', 'done', 'undone'))
);
CREATE TABLE market_pages (id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, body TEXT NOT NULL, seeded INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE "chat_goals" (
 id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id),
 bot TEXT NOT NULL REFERENCES bots(id), objective TEXT NOT NULL CHECK(length(objective) BETWEEN 1 AND 4000),
 status TEXT NOT NULL CHECK(status IN ('active','paused','met','stopped','cleared')),
 note TEXT NOT NULL DEFAULT '', set_by TEXT NOT NULL, set_at TEXT NOT NULL,
 updated_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE principals (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('human','bot','agent','service','system')), deleted_at TEXT);
CREATE TABLE company_page_settings (
  id TEXT PRIMARY KEY CHECK (id = 'company'), transparency TEXT NOT NULL DEFAULT 'closed'
    CHECK (transparency IN ('closed','private','open')),
  slug TEXT, accent TEXT, logo_file_id TEXT, updated_at TEXT, updated_by TEXT);
CREATE TABLE audiences (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('board','investors','public','custom')),
  cadence TEXT NOT NULL DEFAULT 'monthly', due_rule TEXT NOT NULL DEFAULT '{}', lag_days INTEGER NOT NULL DEFAULT 0,
  approver TEXT, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE audience_sources (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id) ON DELETE CASCADE, author TEXT NOT NULL,
  created_at TEXT NOT NULL, UNIQUE(audience_id, author));
CREATE TABLE disclosure_revisions (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id) ON DELETE CASCADE, created_by TEXT NOT NULL,
  created_at TEXT NOT NULL);
CREATE TABLE disclosure_rules (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id) ON DELETE CASCADE, data_class TEXT NOT NULL,
  ref_id TEXT NOT NULL DEFAULT '', mode TEXT NOT NULL CHECK (mode IN ('show','rounded','range','delayed','hidden')),
  lag_days INTEGER NOT NULL DEFAULT 0, rounding TEXT, updated_at TEXT NOT NULL,
  UNIQUE(audience_id, data_class, ref_id));
CREATE TABLE editions (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id), author TEXT NOT NULL,
  period_start TEXT NOT NULL, period_end TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, supersedes_id TEXT,
  status TEXT NOT NULL CHECK (status IN ('drafting','held','ready','awaiting_approval','published','superseded','retracted')),
  title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '{}', payload_hash TEXT, approval_id TEXT,
  disclosure_revision_id TEXT, approved_by TEXT, published_at TEXT, retracted_at TEXT, retracted_by TEXT,
  retraction_note TEXT, correction_note TEXT, override_note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE edition_sources (
  id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id) ON DELETE CASCADE, update_id TEXT NOT NULL,
  body_sha256 TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE edition_checks (
  id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id) ON DELETE CASCADE, version INTEGER NOT NULL,
  kind TEXT NOT NULL, outcome TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE readers (
  id TEXT PRIMARY KEY, email TEXT NOT NULL, idp_issuer TEXT, idp_sub TEXT, name TEXT, added_by TEXT NOT NULL,
  notify INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, removed_at TEXT);
CREATE TABLE audience_readers (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id) ON DELETE CASCADE,
  reader_id TEXT NOT NULL REFERENCES readers(id) ON DELETE CASCADE, created_at TEXT NOT NULL,
  UNIQUE(audience_id, reader_id));
CREATE TABLE reader_sessions (
  id TEXT PRIMARY KEY, reader_id TEXT NOT NULL REFERENCES readers(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT);
CREATE TABLE reader_invites (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL,
  used_at TEXT, used_by TEXT, revoked_at TEXT);
CREATE TABLE edition_views (
  id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id) ON DELETE CASCADE,
  reader_id TEXT NOT NULL REFERENCES readers(id) ON DELETE CASCADE, viewed_at TEXT NOT NULL,
  UNIQUE(edition_id, reader_id));
CREATE TABLE reader_messages (
  id TEXT PRIMARY KEY, reader_id TEXT NOT NULL REFERENCES readers(id) ON DELETE CASCADE,
  edition_id TEXT NOT NULL REFERENCES editions(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('reply','can_help')), ask_id TEXT, body TEXT NOT NULL, task_id TEXT,
  created_at TEXT NOT NULL);
CREATE TABLE reader_notices (
  id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id) ON DELETE CASCADE,
  reader_id TEXT NOT NULL REFERENCES readers(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','sent','failed','unavailable','canceled')),
  attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  UNIQUE(edition_id, reader_id));
CREATE TABLE page_stats (
  id TEXT PRIMARY KEY, source_kind TEXT NOT NULL CHECK (source_kind IN ('kpi','finance_line','finance_metric')),
  ref_id TEXT NOT NULL, data_class TEXT NOT NULL, label TEXT, definition TEXT,
  chart TEXT NOT NULL DEFAULT 'number' CHECK (chart IN ('number','line','bars')), position INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL, UNIQUE(source_kind, ref_id));
CREATE TABLE stat_board_approvals (
  id TEXT PRIMARY KEY, audience_id TEXT NOT NULL REFERENCES audiences(id) ON DELETE CASCADE, config_hash TEXT NOT NULL,
  disclosure_revision_id TEXT, approval_id TEXT NOT NULL, approved_by TEXT, created_at TEXT NOT NULL);
CREATE TABLE page_releases (
  id TEXT PRIMARY KEY, path TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE memory_tidy_passes(
 id TEXT PRIMARY KEY, night TEXT NOT NULL, bot TEXT NOT NULL, model TEXT NOT NULL,
 started_at TEXT NOT NULL, deadline TEXT NOT NULL, status TEXT NOT NULL,
 reason TEXT NOT NULL DEFAULT '', parent_task_id TEXT, check_task_id TEXT,
 baseline TEXT NOT NULL DEFAULT '', cost_usd REAL NOT NULL DEFAULT 0,
 UNIQUE(night,bot));
CREATE TABLE memory_tidy_packets(
 attempt_id TEXT PRIMARY KEY, pass_id TEXT NOT NULL UNIQUE, memory_commit TEXT NOT NULL,
 snapshot TEXT NOT NULL, before_digest TEXT NOT NULL, after_digest TEXT,
 since TEXT, previous_learnings TEXT, proposal TEXT, conflicts INTEGER,
 flags TEXT NOT NULL DEFAULT '[]', stage TEXT NOT NULL DEFAULT 'prepared');
CREATE TABLE thread_rankings(
 thread_id TEXT PRIMARY KEY, score INTEGER, ranked_seq INTEGER NOT NULL DEFAULT 0, tried_at TEXT NOT NULL,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE reach_lines(id TEXT PRIMARY KEY, sender_id TEXT NOT NULL, receiver_id TEXT NOT NULL,
 per_day INTEGER, org_rule_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 created_by_id TEXT NOT NULL, updated_by_id TEXT NOT NULL);
CREATE TABLE "reach_settings"(id TEXT PRIMARY KEY, party_id TEXT NOT NULL,
 mode TEXT CHECK (mode IS NULL OR mode IN ('open','nearby','closed')), chats_per_day INTEGER, tasks_per_day INTEGER,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by_id TEXT NOT NULL, book TEXT);
CREATE TABLE registry_metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE thread_members (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, actor TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('owner','member')), added_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (thread_id, actor));
CREATE TABLE thread_followers (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, actor TEXT NOT NULL, following INTEGER NOT NULL DEFAULT 1 CHECK (following IN (0,1)), notify TEXT NOT NULL DEFAULT 'live' CHECK (notify IN ('live','mentions','digest','muted')), reason TEXT NOT NULL DEFAULT 'manual', last_read_seq INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (thread_id, actor));
CREATE TABLE message_deliveries (id TEXT PRIMARY KEY, message_id TEXT NOT NULL, recipient TEXT NOT NULL, thread_id TEXT, root_id TEXT, mode TEXT NOT NULL CHECK (mode IN ('steer','queue','defer','digest','none')), reason TEXT NOT NULL, cause TEXT NOT NULL DEFAULT 'human', state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','delivered','read','capped','held','failed','moot')), revision INTEGER NOT NULL DEFAULT 0, carrier_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT, error TEXT, delivered_at TEXT, read_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, unsolicited INTEGER NOT NULL DEFAULT 0, UNIQUE (message_id, recipient));
CREATE TABLE message_mentions (id TEXT PRIMARY KEY, message_id TEXT NOT NULL, actor TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('mention','ask','assign')), in_audience INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE (message_id, actor));
CREATE TABLE message_reactions (id TEXT PRIMARY KEY, message_id TEXT NOT NULL, actor TEXT NOT NULL, emoji TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (message_id, actor, emoji));
CREATE TABLE message_revisions (id TEXT PRIMARY KEY, message_id TEXT NOT NULL, origin_id TEXT NOT NULL, revision INTEGER NOT NULL, body TEXT, deleted INTEGER NOT NULL DEFAULT 0, actor TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (origin_id, revision));
CREATE TABLE sequences (name TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE thread_followups (message_id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL, to_actor TEXT NOT NULL, nudge_message_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE thread_earlier_notices (bot TEXT NOT NULL, actor TEXT NOT NULL, message_id TEXT, created_at TEXT NOT NULL, PRIMARY KEY (bot, actor));
CREATE TABLE thread_digests (thread_id TEXT NOT NULL, actor TEXT NOT NULL, emailed_seq INTEGER NOT NULL DEFAULT 0, emailed_at TEXT, PRIMARY KEY (thread_id, actor));
CREATE TABLE teammate_accesses (id TEXT PRIMARY KEY, target_type TEXT NOT NULL CHECK (target_type IN ('human','group')), target_id TEXT NOT NULL, access TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE message_search_keys(id INTEGER PRIMARY KEY AUTOINCREMENT, message_id TEXT NOT NULL UNIQUE);
CREATE VIRTUAL TABLE message_search USING fts5(body, message_id UNINDEXED, tokenize='porter unicode61');
CREATE TABLE slack_thread_links (
  id TEXT PRIMARY KEY,
  thread_id TEXT NOT NULL,
  channel_ref TEXT NOT NULL,
  channel_id TEXT NOT NULL DEFAULT '',
  channel_name TEXT NOT NULL DEFAULT '',
  channel_private INTEGER NOT NULL DEFAULT 0,
  audience TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL CHECK (state IN ('requested','active','suspended','refused','unlinked')),
  reason TEXT NOT NULL DEFAULT '',
  history_state TEXT NOT NULL DEFAULT 'off' CHECK (history_state IN ('off','pending','running','done','failed')),
  history_count INTEGER NOT NULL DEFAULT 0,
  linked_by TEXT NOT NULL,
  needs_task_id TEXT,
  failure_task_id TEXT,
  checked_at TEXT,
  activated_at TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, read_only INTEGER NOT NULL DEFAULT 0, read_ts TEXT NOT NULL DEFAULT '');
CREATE TABLE slack_link_members (
  link_id TEXT NOT NULL REFERENCES slack_thread_links(id),
  slack_user_id TEXT NOT NULL,
  person_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (link_id, slack_user_id));
CREATE TABLE slack_message_links (
  id TEXT PRIMARY KEY,
  link_id TEXT NOT NULL REFERENCES slack_thread_links(id),
  channel_id TEXT NOT NULL,
  direction TEXT NOT NULL CHECK (direction IN ('in','out')),
  ts TEXT NOT NULL DEFAULT '',
  thread_ts TEXT NOT NULL DEFAULT '',
  message_id TEXT,
  delivery_id TEXT,
  origin_id TEXT,
  actor TEXT NOT NULL DEFAULT '',
  revision INTEGER NOT NULL DEFAULT 0,
  attempts INTEGER NOT NULL DEFAULT 0,
  state TEXT NOT NULL CHECK (state IN ('sent','held','deleted','sending','uncertain','ready','failed')),
  edit_ts TEXT NOT NULL DEFAULT '',
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL);
CREATE TABLE slack_inbound_events (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  link_id TEXT NOT NULL REFERENCES slack_thread_links(id),
  event_key TEXT NOT NULL UNIQUE,
  event TEXT NOT NULL,
  created_at TEXT NOT NULL);
CREATE TABLE calls(
 id TEXT PRIMARY KEY,
 thread_id TEXT NOT NULL,
 live_meeting_id TEXT NOT NULL UNIQUE REFERENCES live_meetings(id) ON DELETE CASCADE,
 connector_actor TEXT NOT NULL,
 title TEXT NOT NULL,
 state TEXT NOT NULL CHECK (state IN ('live','ended')),
 room_name TEXT NOT NULL UNIQUE,
 end_reason TEXT,
 started_at TEXT NOT NULL,
 ended_at TEXT,
 media_seen_at TEXT,
 transcript_posted_at TEXT,
 action_items_posted_at TEXT,
 finalized_at TEXT,
 wrapped_up_at TEXT,
 action_items_failed_at TEXT,
 action_items_attempts INTEGER NOT NULL DEFAULT 0,
 action_items_retry_at TEXT,
 action_items_given_up_at TEXT,
 speak_replies INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'tico' CHECK (provider IN ('tico','google_meet')), meet_space TEXT, meet_uri TEXT, meet_code TEXT, meet_conference TEXT, meet_seen_at TEXT, meet_active_at TEXT, meet_polled_at TEXT, live_count INTEGER NOT NULL DEFAULT 0, status_source TEXT CHECK (status_source IN ('google','recorder')), ring TEXT, card_message_id TEXT, recorder_actor TEXT, recorder_claimed_at TEXT, transcript_message_id TEXT, meet_empty_at TEXT);
CREATE TABLE call_holds(
 id TEXT PRIMARY KEY,
 call_id TEXT NOT NULL REFERENCES calls(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK (kind IN ('transcript','action_items')),
 reason TEXT NOT NULL,
 detail TEXT NOT NULL,
 created_at TEXT NOT NULL);
CREATE TABLE call_participants(
 call_id TEXT NOT NULL REFERENCES calls(id) ON DELETE CASCADE,
 actor TEXT NOT NULL,
 joined_at TEXT NOT NULL,
 left_at TEXT,
 removed_at TEXT,
 media_removed_at TEXT, in_call INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(call_id, actor));
CREATE TABLE idempotency(
 actor TEXT NOT NULL, operation TEXT NOT NULL, key TEXT NOT NULL,
 request_hash TEXT NOT NULL, response TEXT, created_at TEXT NOT NULL, updated_at TEXT,
 binding TEXT CHECK(binding IS NULL OR binding IN ('invites','github_product_repo','github_review')),
 subject TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'completed' CHECK(state IN ('pending','completed','refused')),
 error_code TEXT, error_detail TEXT, error_status INTEGER,
 PRIMARY KEY(actor,operation,key));
CREATE TABLE usage_facts (
  id INTEGER PRIMARY KEY,
  source TEXT NOT NULL CHECK (source IN ('estimate', 'meter')),
  run_id TEXT,
  position INTEGER NOT NULL DEFAULT 0,
  bot_id TEXT,
  task_id TEXT,
  provider TEXT,
  model TEXT,
  family TEXT,
  runtime TEXT,
  harness TEXT,
  effort TEXT,
  profile TEXT,
  billing TEXT,
  input_tokens INTEGER NOT NULL DEFAULT 0,
  cached_tokens INTEGER NOT NULL DEFAULT 0,
  output_tokens INTEGER NOT NULL DEFAULT 0,
  cost_nano INTEGER,
  low_estimate INTEGER CHECK (low_estimate IN (0, 1)),
  meter_key TEXT,
  gateway_key_id TEXT,
  install_id TEXT,
  started_at TEXT NOT NULL,
  metered_at TEXT NOT NULL,
  created_at TEXT NOT NULL, cache_write_tokens INTEGER,
  CHECK (source = 'meter' OR run_id IS NOT NULL),
  CHECK (source = 'estimate' OR meter_key IS NOT NULL));
CREATE TABLE usage_meter_reads (
  id INTEGER PRIMARY KEY,
  month TEXT NOT NULL UNIQUE,
  as_of TEXT NOT NULL,
  total_nano INTEGER NOT NULL,
  read_at TEXT NOT NULL);
CREATE TABLE budget_nodes (
  id TEXT PRIMARY KEY,
  scope TEXT NOT NULL CHECK (scope IN ('company', 'team', 'bot')),
  team_id TEXT,
  bot_id TEXT,
  per_bot INTEGER NOT NULL DEFAULT 0 CHECK (per_bot IN (0, 1)),
  period TEXT NOT NULL CHECK (period IN ('per_30m', 'hourly', 'daily', 'weekly', 'monthly')),
  amount_nano INTEGER NOT NULL CHECK (amount_nano >= 0 AND (per_bot = 0 OR amount_nano > 0)),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  updated_by_id TEXT,
  CHECK ((scope = 'company' AND team_id IS NULL AND bot_id IS NULL)
      OR (scope = 'team' AND team_id IS NOT NULL AND bot_id IS NULL AND per_bot = 0)
      OR (scope = 'bot' AND bot_id IS NOT NULL AND team_id IS NULL AND per_bot = 0)));
CREATE TABLE runners(
 id TEXT PRIMARY KEY, label TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES humans(id),
 token_hash TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, revoked_at TEXT, platform TEXT,
 restart_requested_at TEXT, accepts_member_bots INTEGER NOT NULL DEFAULT 0, screen TEXT NOT NULL DEFAULT 'off',
 screen_default_pending INTEGER NOT NULL DEFAULT 0, performance TEXT NOT NULL DEFAULT 'on', turns_at_once INTEGER, device_id TEXT, gateway_fallback INTEGER NOT NULL DEFAULT 0 CHECK (gateway_fallback IN (0, 1)));
CREATE TABLE runner_states(
 runner_id TEXT PRIMARY KEY REFERENCES runners(id) ON DELETE CASCADE,
 last_seen_at TEXT,
 awake_since TEXT,
 version TEXT,
 capacity INTEGER NOT NULL DEFAULT 4,
 readiness TEXT NOT NULL DEFAULT '{}',
 readiness_at TEXT,
 capabilities TEXT NOT NULL DEFAULT '[]',
 checkout TEXT,
 restart_since TEXT,
 memory_hold INTEGER NOT NULL DEFAULT 0,
 last_sampled_at INTEGER);
CREATE TABLE thread_pins (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, actor TEXT NOT NULL, pinned INTEGER NOT NULL DEFAULT 1 CHECK (pinned IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (thread_id, actor));
CREATE TABLE org_rule_holds(id TEXT PRIMARY KEY, operation TEXT NOT NULL, payload TEXT NOT NULL, author TEXT NOT NULL, destinations TEXT NOT NULL DEFAULT '[]', rule_ids TEXT NOT NULL DEFAULT '[]', verdict TEXT NOT NULL DEFAULT '{}', why TEXT NOT NULL DEFAULT '', nonce TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('held','sent','kept')), reviewer TEXT, task_id TEXT, created_at TEXT NOT NULL, decided_at TEXT, decided_by TEXT, check_kind TEXT NOT NULL DEFAULT 'judged');
CREATE TABLE history_events(
 id TEXT PRIMARY KEY,
 subject_type TEXT NOT NULL CHECK (subject_type IN ('task', 'goal', 'company', 'strategy', 'market_entity', 'market_edge', 'market_evidence', 'market_document')),
 subject_id TEXT NOT NULL, actor_id TEXT, kind TEXT, old TEXT, new TEXT, note TEXT,
 action_id TEXT, via TEXT, data TEXT, created_at TEXT);
CREATE TABLE home_merges(
  conversation_id TEXT PRIMARY KEY,
  home_id TEXT NOT NULL,
  bot_id TEXT NOT NULL,
  owner_id TEXT,
  room_key TEXT,
  messages_count INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL);
CREATE TABLE home_merge_messages(
  message_id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL);
CREATE TABLE message_routes (message_id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, bot_ids TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE changes(seq INTEGER PRIMARY KEY AUTOINCREMENT, topic TEXT NOT NULL, kind TEXT, subject_id TEXT, ref TEXT, conversation_id TEXT, bot TEXT, actor TEXT, created_at TEXT NOT NULL);
CREATE TABLE bot_settings(
 bot_id TEXT PRIMARY KEY REFERENCES bots(id),
 harness TEXT,
 runtime TEXT,
 model TEXT,
 reasoning_effort TEXT,
 host TEXT,
 template TEXT,
 profile TEXT,
 session TEXT,
 wake_preset TEXT,
 shared_from TEXT,
 bot_contact TEXT,
 repo_access_mode TEXT,
 folder TEXT,
 github_login TEXT,
 compact_at INTEGER,
 turns_per_hour INTEGER,
 turns_per_day INTEGER,
 max_run_minutes INTEGER,
 stateless INTEGER CHECK (stateless IN (0,1)),
 fallback TEXT,
 app_delivery TEXT,
 extra TEXT NOT NULL DEFAULT '{}',
 updated_at TEXT);
CREATE TABLE attempts(
 id TEXT PRIMARY KEY, job_id TEXT REFERENCES jobs(id), bot_id TEXT NOT NULL,
 runner_id TEXT REFERENCES runners(id), generation INTEGER,
 token_hash TEXT UNIQUE, state TEXT, lease_until TEXT,
 created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, thread_id TEXT,
 result TEXT, final_text TEXT, last_seq INTEGER NOT NULL DEFAULT 0,
 stop_requested_at TEXT, gateway_key_id TEXT, handed_runtime TEXT, handed_model TEXT,
 lane TEXT NOT NULL DEFAULT 'main', wake TEXT, model TEXT,
 settled_at TEXT, trigger TEXT, message_id TEXT, task_id TEXT, exit TEXT, summary TEXT,
 trigger_kind TEXT, trigger_source TEXT, purpose TEXT, rule_id TEXT, writes INTEGER, outcome TEXT,
 did_nothing INTEGER, rotated TEXT, session_kind TEXT, session_why TEXT,
 input_tokens INTEGER, cached_tokens INTEGER, output_tokens INTEGER, prompt_tokens INTEGER,
 usage_model TEXT, provider TEXT, est_cost_usd REAL, billing TEXT, usage_reason TEXT, acting_person TEXT, cache_write_tokens INTEGER,
 CHECK (job_id IS NULL OR (runner_id IS NOT NULL AND generation IS NOT NULL AND token_hash IS NOT NULL
        AND state IS NOT NULL AND lease_until IS NOT NULL)));
CREATE TABLE google_setup_codes(code_hash TEXT PRIMARY KEY, domain TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, generation INTEGER NOT NULL);
CREATE TABLE google_oauth_clients(singleton INTEGER PRIMARY KEY CHECK (singleton = 1), client_id TEXT NOT NULL, secret_sealed TEXT NOT NULL, revision INTEGER NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE google_setup_generations(singleton INTEGER PRIMARY KEY CHECK (singleton = 1), issued INTEGER NOT NULL);
CREATE TABLE automation_runs(id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, version INTEGER NOT NULL, trigger_ref TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, finished_at TEXT, status TEXT NOT NULL, cost REAL NOT NULL DEFAULT 0, saved_state TEXT, claimed_at TEXT, wake_at TEXT, chain TEXT NOT NULL DEFAULT '[]', claim_token TEXT);
CREATE TABLE maintenance_steps(
 key TEXT PRIMARY KEY CHECK (key IN ('collect', 'clean_up', 'check_health', 'find_stuck', 'learn', 'suggest', 'update', 'dream')),
 enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
 frequency TEXT NOT NULL DEFAULT 'run' CHECK (frequency IN ('run','day','week','custom')),
 custom_every INTEGER CHECK (custom_every IS NULL OR custom_every BETWEEN 1 AND 999),
 custom_unit TEXT CHECK (custom_unit IS NULL OR custom_unit IN ('hours','days')),
 max_bots INTEGER CHECK (max_bots IS NULL OR max_bots BETWEEN 0 AND 500),
 cursor_at TEXT, last_started_at TEXT, last_ran_at TEXT, updated_at TEXT, updated_by_id TEXT,
 CHECK (frequency <> 'custom' OR (custom_every IS NOT NULL AND custom_unit IS NOT NULL)));
CREATE TABLE maintenance_runs(
 id TEXT PRIMARY KEY,
 occurrence_key TEXT NOT NULL UNIQUE,
 trigger TEXT NOT NULL CHECK (trigger IN ('schedule','run_now')),
 step TEXT CHECK (step IS NULL OR step IN ('collect', 'clean_up', 'check_health', 'find_stuck', 'learn', 'suggest', 'update', 'dream')),
 started_at TEXT NOT NULL, heartbeat_at TEXT NOT NULL, finished_at TEXT,
 ok INTEGER CHECK (ok IS NULL OR ok IN (0,1)),
 result TEXT NOT NULL DEFAULT '',
 cost_usd REAL NOT NULL DEFAULT 0);
CREATE TABLE maintenance_run_steps(
 id TEXT PRIMARY KEY,
 maintenance_run_id TEXT NOT NULL REFERENCES maintenance_runs(id) ON DELETE CASCADE,
 step TEXT NOT NULL REFERENCES maintenance_steps(key),
 status TEXT NOT NULL CHECK (status IN ('ran','skipped','failed','off','pending')),
 reason TEXT NOT NULL DEFAULT '',
 checked INTEGER NOT NULL DEFAULT 0, found INTEGER NOT NULL DEFAULT 0, woke INTEGER NOT NULL DEFAULT 0,
 cost_usd REAL NOT NULL DEFAULT 0,
 started_at TEXT NOT NULL, finished_at TEXT,
 window_end TEXT,
 details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE maintenance_listings(
 task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK (kind IN ('blocked_by_bot','missed_start','quiet','due_follow_up','stale_review')),
 appointment TEXT NOT NULL,
 bot_id TEXT NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
 listed_at TEXT NOT NULL,
 PRIMARY KEY (task_id, kind, appointment));
CREATE TABLE maintenance_handoffs(
 id TEXT PRIMARY KEY,
 bot_id TEXT NOT NULL REFERENCES bots(id) ON DELETE CASCADE,
 task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK (kind IN ('quiet')),
 created_at TEXT NOT NULL,
 delivered_at TEXT);
CREATE TABLE maintenance_requests(
 actor TEXT NOT NULL,
 request_key TEXT NOT NULL,
 maintenance_run_id TEXT NOT NULL REFERENCES maintenance_runs(id) ON DELETE CASCADE,
 created_at TEXT NOT NULL,
 PRIMARY KEY (actor, request_key));
CREATE TABLE mailboxes(id TEXT PRIMARY KEY, address TEXT NOT NULL UNIQUE, provider TEXT NOT NULL DEFAULT 'google_workspace', person_id TEXT, kind TEXT NOT NULL DEFAULT 'personal' CHECK(kind IN ('personal','shared')), connection TEXT NOT NULL DEFAULT 'workspace' CHECK(connection IN ('workspace','personal')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','stopped')), shared_by TEXT, shared_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, feeds_directory INTEGER NOT NULL DEFAULT 1 CHECK (feeds_directory IN (0, 1)), history_id TEXT, checked_at TEXT, check_error TEXT, catch_up TEXT, watching_since_at TEXT, CHECK(address = lower(address)), CHECK(kind = 'personal' OR person_id IS NULL));
CREATE TABLE mailbox_accesses(id TEXT PRIMARY KEY, mailbox_id TEXT NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE, grantee_type TEXT NOT NULL CHECK(grantee_type IN ('person','bot')), grantee_id TEXT NOT NULL, level TEXT NOT NULL CHECK(level IN ('read','read_write')), granted_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE meeting_task_links (
 id TEXT PRIMARY KEY,
 meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,
 task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK (kind IN ('linked','sent','proposal')),
 created_by TEXT NOT NULL,
 created_at TEXT NOT NULL,
 UNIQUE(meeting_id,task_id)
);
CREATE TABLE presences (
 id TEXT PRIMARY KEY, place TEXT NOT NULL, actor TEXT NOT NULL, session_id TEXT NOT NULL,
 seen_at TEXT NOT NULL, UNIQUE(place, session_id)
);
CREATE TABLE media_control(
        meeting_id TEXT PRIMARY KEY REFERENCES meetings(id), version INTEGER NOT NULL DEFAULT 1,
        deleted_at TEXT, next_seq INTEGER NOT NULL DEFAULT 0, received_bytes INTEGER NOT NULL DEFAULT 0,
        last_chunk_at TEXT);
CREATE TABLE learning_runs(id TEXT PRIMARY KEY, night TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT, read_count INTEGER NOT NULL DEFAULT 0, routed_count INTEGER NOT NULL DEFAULT 0, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE learning_items(run_id TEXT NOT NULL, item_key TEXT NOT NULL, source TEXT NOT NULL, ref TEXT NOT NULL, author TEXT NOT NULL DEFAULT '', label TEXT NOT NULL, text TEXT NOT NULL, created_at TEXT NOT NULL, learnable REAL, scores TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(run_id,item_key));
CREATE TABLE learning_deliveries(run_id TEXT NOT NULL, recipient TEXT NOT NULL, task_id TEXT, item_keys TEXT NOT NULL, created_at TEXT NOT NULL, update_batch_id TEXT, message_id TEXT, feedback_message_id TEXT, sent_item_keys TEXT, sent_at TEXT, learnings_saved INTEGER CHECK(learnings_saved BETWEEN 0 AND 15), settled_at TEXT, expired_at TEXT, PRIMARY KEY(run_id,recipient));
CREATE TABLE learning_cursors(source TEXT PRIMARY KEY,last_ts TEXT NOT NULL);
CREATE TABLE suggestions(id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, owner_role TEXT NOT NULL, owner_bot_id TEXT, title TEXT NOT NULL, body TEXT NOT NULL, condition TEXT NOT NULL, cooldown_days INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','sent','acted','dismissed','expired','condition_false')), update_batch_id TEXT, message_id TEXT, delivered_at TEXT, cooldown_until TEXT, outcome TEXT CHECK(outcome IN ('delivered','acted','dismissed','expired','condition_false')), outcome_reported_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE email_sending_policies(scope TEXT PRIMARY KEY, settings TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE email_sends(id TEXT PRIMARY KEY, mailbox TEXT NOT NULL, actor TEXT NOT NULL, bot TEXT NOT NULL, via TEXT NOT NULL, automation_action_id TEXT, content_sha256 TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, recipients TEXT NOT NULL, attachments TEXT NOT NULL, subject TEXT NOT NULL, body_sha256 TEXT NOT NULL, raw TEXT NOT NULL, draft_id TEXT NOT NULL, thread_id TEXT NOT NULL, reply_to_id TEXT NOT NULL, approval_id TEXT NOT NULL, classification TEXT NOT NULL, decision TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, send_after TEXT NOT NULL, claimed_at TEXT, provider_attempted_at TEXT, runner_id TEXT, finished_at TEXT, provider_message_id TEXT, detail TEXT NOT NULL DEFAULT '', operation_key TEXT NOT NULL DEFAULT '', lease_id TEXT NOT NULL DEFAULT '', checked_at TEXT NOT NULL DEFAULT '', calendar_action_id TEXT);
CREATE TABLE email_suppressed_recipients(mailbox TEXT NOT NULL, address TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(mailbox,address));
CREATE TABLE email_legacy_automations(automation_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE postal_mail_grants (
  id TEXT PRIMARY KEY,
  address_id TEXT NOT NULL,
  grantee_type TEXT NOT NULL CHECK (grantee_type IN ('person','bot')),
  grantee_id TEXT NOT NULL,
  level TEXT NOT NULL DEFAULT 'read' CHECK (level='read'),
  granted_by_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(address_id,grantee_type,grantee_id)
);
CREATE TABLE postal_mail_settings (
  id INTEGER PRIMARY KEY CHECK (id=1),
  legal_bot_id TEXT,
  updated_by_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE alert_preferences (
 person_id TEXT PRIMARY KEY REFERENCES humans(id),
 phone TEXT,
 phone_version TEXT NOT NULL DEFAULT '',
 verified_at TEXT,
 revocation_pending INTEGER NOT NULL DEFAULT 0,
 call_consent INTEGER NOT NULL DEFAULT 0,
 legal_mail INTEGER NOT NULL DEFAULT 0,
 urgent_calls INTEGER NOT NULL DEFAULT 0,
 timezone TEXT NOT NULL DEFAULT 'UTC',
 quiet_start TEXT NOT NULL DEFAULT '22:00',
 quiet_end TEXT NOT NULL DEFAULT '07:00',
 emergency_exception INTEGER NOT NULL DEFAULT 0,
 monthly_cap INTEGER NOT NULL DEFAULT 10 CHECK(monthly_cap BETWEEN 0 AND 10000),
 updated_at TEXT NOT NULL
);
CREATE TABLE alert_company_settings (
 id INTEGER PRIMARY KEY CHECK(id=1),
 monthly_cap INTEGER NOT NULL DEFAULT 50 CHECK(monthly_cap BETWEEN 0 AND 100000)
);
CREATE TABLE personal_alerts (
 id TEXT PRIMARY KEY,
 person_id TEXT NOT NULL REFERENCES humans(id),
 incident_key TEXT NOT NULL,
 kind TEXT NOT NULL,
 subject_id TEXT NOT NULL,
 emergency INTEGER NOT NULL DEFAULT 0,
 phone_version TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending',
 month TEXT,
 reserved INTEGER NOT NULL DEFAULT 0,
 send_id TEXT,
 channel TEXT,
 error TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL,
 attempted_at TEXT,
 next_attempt_at TEXT,
 UNIQUE(person_id,incident_key)
);
CREATE TABLE letter_outboxes (
  id TEXT PRIMARY KEY, mode TEXT NOT NULL DEFAULT 'ask_first', return_address TEXT,
  monthly_cap_micros INTEGER, availability TEXT NOT NULL DEFAULT 'unknown',
  checked_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE letter_outbox_grants (
  id TEXT PRIMARY KEY, outbox_id TEXT NOT NULL REFERENCES letter_outboxes(id), grantee_type TEXT NOT NULL,
  grantee_id TEXT NOT NULL, level TEXT NOT NULL CHECK(level='send'),
  granted_by_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  UNIQUE(outbox_id,grantee_type,grantee_id)
);
CREATE TABLE letter_bot_settings (
  bot_id TEXT PRIMARY KEY REFERENCES bots(id), mode TEXT, monthly_cap_micros INTEGER,
  updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE letters (
  id TEXT PRIMARY KEY, outbox_id TEXT NOT NULL REFERENCES letter_outboxes(id),
  requested_by TEXT NOT NULL, acting_bot_id TEXT, automation_id TEXT, task_id TEXT, thread_id TEXT, attempt_id TEXT,
  recipient TEXT NOT NULL, recipient_hash TEXT NOT NULL, return_address TEXT NOT NULL,
  mail_class TEXT NOT NULL, color INTEGER NOT NULL, duplex INTEGER NOT NULL,
  source_blob_id TEXT NOT NULL REFERENCES blobs(id), original_blob_id TEXT REFERENCES blobs(id), proof_blob_id TEXT REFERENCES blobs(id),
  source_provenance TEXT NOT NULL DEFAULT '{}',
  page_count INTEGER, quote_id TEXT, quote_expires_at TEXT, approval_hash TEXT,
  approval_id TEXT, approved_hash TEXT, submission_quote_id TEXT, hq_letter_id TEXT,
  total_micros INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'USD',
  status TEXT NOT NULL DEFAULT 'quoted', tracking TEXT NOT NULL DEFAULT '[]',
  cancel_possible INTEGER NOT NULL DEFAULT 0, always_ask INTEGER NOT NULL DEFAULT 1, approval_reason TEXT NOT NULL DEFAULT '',
  error TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, next_sync_at TEXT,
  submitted_at TEXT, accepted_at TEXT, charged_micros INTEGER, spend_released INTEGER NOT NULL DEFAULT 0,
  billing TEXT NOT NULL DEFAULT 'unknown', created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE letter_proofs (
  letter_id TEXT NOT NULL REFERENCES letters(id), blob_id TEXT NOT NULL REFERENCES blobs(id),
  approval_hash TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(letter_id,blob_id)
);
CREATE TABLE page_identities(identity TEXT NOT NULL,file_id TEXT NOT NULL REFERENCES pages(file_id),PRIMARY KEY(identity,file_id));
CREATE TABLE email_send_previews(send_id TEXT NOT NULL, actor TEXT NOT NULL, content_sha256 TEXT NOT NULL, shown_at TEXT NOT NULL, PRIMARY KEY(send_id,actor));
CREATE TABLE email_send_operations(actor TEXT NOT NULL, operation_key TEXT NOT NULL, send_id TEXT NOT NULL, PRIMARY KEY(actor,operation_key));
CREATE TABLE letter_sources (letter_id TEXT NOT NULL REFERENCES letters(id) ON DELETE CASCADE, source_type TEXT NOT NULL CHECK(source_type IN ('task','thread')), source_id TEXT NOT NULL);
CREATE TABLE cloud_machine_deletions(machine_id TEXT PRIMARY KEY, bot TEXT NOT NULL, runner_id TEXT, reason TEXT NOT NULL DEFAULT 'manual', next_try_at REAL, failures INTEGER NOT NULL DEFAULT 0, created_at REAL);
CREATE TABLE cloud_machine_enrollment_failures(machine_id TEXT PRIMARY KEY, bot TEXT NOT NULL);
CREATE TABLE tools( id TEXT PRIMARY KEY, name TEXT NOT NULL, service TEXT NOT NULL DEFAULT '', base_url TEXT NOT NULL DEFAULT '', auth_scheme TEXT NOT NULL DEFAULT 'bearer', check_path TEXT NOT NULL DEFAULT '', delivery TEXT NOT NULL DEFAULT 'proxy', created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, audience TEXT, kind TEXT NOT NULL DEFAULT 'api', sites TEXT, central_only INTEGER NOT NULL DEFAULT 0, mcp_url TEXT NOT NULL DEFAULT '', mcp_transport TEXT NOT NULL DEFAULT '', mcp_tools TEXT, mcp_oauth TEXT, mcp_client_secret TEXT, everyone_reads INTEGER NOT NULL DEFAULT 1 CHECK (everyone_reads IN (0, 1)), auth_template TEXT NOT NULL DEFAULT '');
CREATE TABLE tool_checks( id TEXT PRIMARY KEY, tool_id TEXT NOT NULL REFERENCES tools(id), credential_id TEXT, ok INTEGER NOT NULL, status_code INTEGER, detail TEXT NOT NULL DEFAULT '', checked_at TEXT NOT NULL);
CREATE TABLE tool_calls( id TEXT PRIMARY KEY, tool_id TEXT NOT NULL REFERENCES tools(id), credential_id TEXT, actor TEXT NOT NULL, bot TEXT NOT NULL DEFAULT '', access_level TEXT NOT NULL, method TEXT NOT NULL, path TEXT NOT NULL, status_code INTEGER, result TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', duration_ms INTEGER, created_at TEXT NOT NULL);
CREATE TABLE skills (
  id TEXT PRIMARY KEY,                       -- 'sk_' + random
  name TEXT NOT NULL UNIQUE,                 -- ^[a-z0-9][a-z0-9._-]{0,79}$
  description TEXT NOT NULL DEFAULT '',
  latest_version_id TEXT,                    -- skill_versions.id; NULL until the first approval
  created_by_type TEXT NOT NULL,
  created_by_id TEXT NOT NULL,
  deleted_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE skill_versions (
  id TEXT PRIMARY KEY,                       -- 'skv_' + random
  skill_id TEXT NOT NULL REFERENCES skills(id),
  number INTEGER NOT NULL,                   -- 1, 2, 3 ...
  sha256 TEXT NOT NULL,                      -- of the canonical bundle (sorted [{path, content}] JSON)
  files TEXT NOT NULL,                       -- JSON [{path, content}], immutable
  description TEXT NOT NULL DEFAULT '',
  proposal_id TEXT NOT NULL,
  approved_by_id TEXT NOT NULL REFERENCES humans(id),
  approved_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(skill_id, number),
  UNIQUE(skill_id, sha256)
);
CREATE TABLE skill_proposals (
  id TEXT PRIMARY KEY,                       -- 'skp_' + random
  name TEXT NOT NULL,
  skill_id TEXT REFERENCES skills(id),       -- NULL: a new skill
  base_version_id TEXT REFERENCES skill_versions(id),   -- the version an update was made from
  sha256 TEXT NOT NULL,
  files TEXT NOT NULL,                       -- JSON [{path, content}]
  description TEXT NOT NULL DEFAULT '',      -- from SKILL.md frontmatter
  source TEXT NOT NULL DEFAULT '{}',         -- JSON {kind: bot|person|url, bot_id?, repo_path?, url?}
  note TEXT NOT NULL DEFAULT '',             -- the proposer's one line
  status TEXT NOT NULL DEFAULT 'pending',    -- pending | approved | declined | withdrawn
  proposed_by_type TEXT NOT NULL,
  proposed_by_id TEXT NOT NULL,
  task_id TEXT,                              -- where the proposer asked from, for the reply line
  decided_by_id TEXT REFERENCES humans(id),
  decided_at TEXT,
  decline_reason TEXT,
  version_id TEXT REFERENCES skill_versions(id),        -- set on approval
  screen_status TEXT NOT NULL DEFAULT 'pending',        -- pending | screened | not_screened
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE skill_screenings (
  id TEXT PRIMARY KEY,                       -- 'sks_' + random
  proposal_id TEXT NOT NULL REFERENCES skill_proposals(id),
  sha256 TEXT NOT NULL,                      -- the bundle that was screened
  base_version_id TEXT,                      -- the diff base it was screened against
  question_set TEXT NOT NULL,                -- e.g. 'skill-screen@1'
  status TEXT NOT NULL,                      -- screened | not_screened
  reason TEXT,                               -- not_screened: error | cap | timeout | oversize | unavailable
  verdict TEXT,                              -- safe | review | unsafe
  risk TEXT,                                 -- low | medium | high
  summary TEXT,
  findings TEXT NOT NULL DEFAULT '[]',       -- JSON [{file, line, issue, severity}] (model)
  patterns TEXT NOT NULL DEFAULT '[]',       -- JSON [{file, line, pattern}] (code checks)
  judge_call_id TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE skill_installs (
  id TEXT PRIMARY KEY,                       -- 'ski_' + random
  skill_id TEXT NOT NULL REFERENCES skills(id),
  target_type TEXT NOT NULL,                 -- 'Bot' | 'Human'
  target_id TEXT NOT NULL,
  version_policy TEXT NOT NULL DEFAULT 'latest',        -- latest | pinned
  pinned_version_id TEXT REFERENCES skill_versions(id),
  installed_by_type TEXT NOT NULL,
  installed_by_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(skill_id, target_type, target_id)
);
CREATE TABLE skill_receipts (
  target_type TEXT NOT NULL,                 -- 'Bot' | 'Human'
  target_id TEXT NOT NULL,
  skill_id TEXT NOT NULL REFERENCES skills(id),
  sha256 TEXT NOT NULL,                      -- what the runner or helper actually staged
  source TEXT NOT NULL,                      -- runner | helper
  staged_at TEXT NOT NULL,
  PRIMARY KEY(target_type, target_id, skill_id)
);
CREATE TABLE skill_usages (
  id INTEGER PRIMARY KEY,
  skill_id TEXT NOT NULL REFERENCES skills(id),
  sha256 TEXT,
  actor_type TEXT NOT NULL,                  -- 'Bot' | 'Human': who ran it
  actor_id TEXT NOT NULL,
  requested_by_id TEXT REFERENCES humans(id),          -- the person who typed /name for a bot, if any
  trigger TEXT NOT NULL,                     -- model | person | nested
  source TEXT NOT NULL,                      -- runner | helper | thread
  session_key TEXT NOT NULL,                 -- attempt id, or the helper's hashed session id
  tool_use_id TEXT NOT NULL,                 -- tool_use id, or a message id for a typed /name
  task_id TEXT,
  thread_id TEXT,
  used_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(session_key, tool_use_id)
);
CREATE TABLE skill_usage_dailies (
  used_on TEXT NOT NULL,                     -- YYYY-MM-DD, UTC
  skill_id TEXT NOT NULL REFERENCES skills(id),
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  trigger TEXT NOT NULL,
  uses_count INTEGER NOT NULL,
  PRIMARY KEY(used_on, skill_id, actor_type, actor_id, trigger)
);
CREATE TABLE skill_devices (
  id TEXT PRIMARY KEY,                       -- 'skd_' + random
  person_id TEXT NOT NULL REFERENCES humans(id) ON DELETE CASCADE,
  label TEXT NOT NULL DEFAULT '',
  token_hash TEXT NOT NULL UNIQUE,           -- sha256 of the 'tico_sd_' token, shown once
  reporting_enabled INTEGER NOT NULL DEFAULT 0,          -- the person's opt-in to usage reporting
  claude_version TEXT,
  last_seen_at TEXT,
  revoked_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE skill_device_codes (
  device_code_hash TEXT PRIMARY KEY,         -- sha256 of the helper's secret device code
  user_code TEXT NOT NULL UNIQUE,            -- short code the person confirms in the browser
  label TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending',    -- pending | approved | denied | used | expired
  person_id TEXT REFERENCES humans(id),
  reporting_enabled INTEGER NOT NULL DEFAULT 0,
  device_id TEXT REFERENCES skill_devices(id),
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, client_hash TEXT);
CREATE TABLE fin_ad_imports (
 id TEXT PRIMARY KEY,
 tool_id TEXT NOT NULL UNIQUE,
 platform TEXT NOT NULL CHECK (platform IN ('google_ads','meta_ads')),
 enabled INTEGER NOT NULL DEFAULT 0,
 history_from TEXT NOT NULL,
 account_id TEXT NOT NULL DEFAULT '',
 credentials TEXT NOT NULL DEFAULT '{}',
 status TEXT NOT NULL DEFAULT 'never',
 last_import_at TEXT,
 last_error TEXT NOT NULL DEFAULT '',
 run_requested_at TEXT,
 created_by TEXT NOT NULL,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL
);
CREATE TABLE fin_ad_accounts (
 id TEXT PRIMARY KEY,
 tool_id TEXT NOT NULL,
 platform TEXT NOT NULL CHECK (platform IN ('google_ads','meta_ads')),
 external_id TEXT NOT NULL,
 name TEXT NOT NULL DEFAULT '',
 currency TEXT NOT NULL DEFAULT 'USD',
 bot_slug TEXT,
 active INTEGER NOT NULL DEFAULT 1,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE (tool_id, external_id)
);
CREATE TABLE fin_ad_spends (
 id TEXT PRIMARY KEY,
 ad_account_id TEXT NOT NULL REFERENCES fin_ad_accounts(id) ON DELETE CASCADE,
 day TEXT NOT NULL,
 campaign_external_id TEXT NOT NULL,
 campaign_name TEXT NOT NULL DEFAULT '',
 amount_cents BIGINT NOT NULL,
 currency TEXT NOT NULL,
 fetched_at TEXT NOT NULL, clicks INTEGER NOT NULL DEFAULT 0, conversions REAL NOT NULL DEFAULT 0,
 UNIQUE (ad_account_id, day, campaign_external_id)
);
CREATE TABLE fin_ad_warnings (
 budget_id TEXT NOT NULL,
 period_key TEXT NOT NULL,
 level TEXT NOT NULL CHECK (level IN ('warn','limit','pace')),
 bot_slug TEXT NOT NULL,
 created_at TEXT NOT NULL,
 PRIMARY KEY (budget_id, period_key, level)
);
CREATE TABLE unlisted_skill_usage_dailies (
  used_on TEXT NOT NULL,                     -- YYYY-MM-DD, UTC
  name TEXT NOT NULL,                        -- ^[a-z0-9][a-z0-9._-]{0,79}$, as the runner reported it
  bot_id TEXT NOT NULL,
  uses_count INTEGER NOT NULL,
  PRIMARY KEY(used_on, name, bot_id)
);
CREATE TABLE skill_suggestions (
  id TEXT PRIMARY KEY,                       -- 'sks_' + random
  kind TEXT NOT NULL CHECK(kind IN ('remove', 'promote')),
  subject TEXT NOT NULL,                     -- remove: the install's id; promote: the skill's name
  name TEXT NOT NULL,                        -- the skill's name
  target_type TEXT NOT NULL,                 -- remove: the install's target; promote: 'Bot', the bot asked to submit it
  target_id TEXT NOT NULL,
  uses_count INTEGER NOT NULL DEFAULT 0,     -- promote: uses in the 30 days it was judged on
  bots_count INTEGER NOT NULL DEFAULT 0,     -- promote: bots that used it in those 30 days
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open', 'acted', 'dismissed', 'expired')),
  closed_by_id TEXT,                         -- the admin who acted on it or dismissed it
  closed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(kind, subject)
);
CREATE TABLE heartbeat_steps(
 key TEXT PRIMARY KEY,
 last_run_at TEXT,
 last_ms INTEGER,
 last_result TEXT,
 last_did_at TEXT,
 last_did TEXT,
 last_error TEXT,
 last_error_at TEXT,
 window_started_at TEXT,
 runs_count INTEGER NOT NULL DEFAULT 0,
 did_count INTEGER NOT NULL DEFAULT 0,
 failed_count INTEGER NOT NULL DEFAULT 0,
 previous_runs_count INTEGER NOT NULL DEFAULT 0,
 previous_did_count INTEGER NOT NULL DEFAULT 0,
 previous_failed_count INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL);
CREATE TABLE heartbeat_beats(
 id TEXT PRIMARY KEY,
 started_at TEXT NOT NULL,
 total_ms INTEGER NOT NULL DEFAULT 0,
 did_count INTEGER NOT NULL DEFAULT 0,
 failed_count INTEGER NOT NULL DEFAULT 0,
 steps TEXT NOT NULL DEFAULT '[]',
 repeat_count INTEGER NOT NULL DEFAULT 1,
 last_repeated_at TEXT,
 created_at TEXT NOT NULL);
CREATE TABLE heartbeat_states(
 id INTEGER PRIMARY KEY CHECK (id = 1),
 last_beat_at TEXT,
 window_started_at TEXT,
 beats_count INTEGER NOT NULL DEFAULT 0,
 previous_beats_count INTEGER NOT NULL DEFAULT 0,
 quiet_beats_count INTEGER NOT NULL DEFAULT 0,
 quiet_since_at TEXT,
 last_pruned_at TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL);
CREATE TABLE fin_attributions (
 id TEXT PRIMARY KEY,
 book_id TEXT NOT NULL,
 line_id TEXT NOT NULL,
 splits TEXT NOT NULL DEFAULT '[]',
 source TEXT NOT NULL CHECK (source IN ('rule','person','bot','platform')),
 rule_id TEXT,
 set_by TEXT NOT NULL,
 created_at TEXT NOT NULL,
 superseded_at TEXT,
 superseded_by TEXT
);
CREATE TABLE fin_attribution_rules (
 id TEXT PRIMARY KEY,
 book_id TEXT NOT NULL,
 name TEXT NOT NULL,
 match_kind TEXT NOT NULL CHECK (match_kind IN ('vendor','account','money_account','class','location','project')),
 match_id TEXT NOT NULL,
 splits TEXT NOT NULL DEFAULT '[]',
 enabled INTEGER NOT NULL DEFAULT 1,
 apply_from TEXT,
 created_by TEXT NOT NULL,
 created_at TEXT NOT NULL,
 updated_at TEXT,
 deleted_at TEXT
);
CREATE TABLE fin_briefs (
 reader TEXT PRIMARY KEY,
 fingerprint TEXT NOT NULL,
 lines TEXT NOT NULL DEFAULT '[]',
 as_of TEXT NOT NULL,
 changed_since TEXT,
 view_version INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL,
 delivered_fingerprint TEXT NOT NULL DEFAULT ''
);
CREATE TABLE fin_ad_campaigns (
 id TEXT PRIMARY KEY,
 ad_account_id TEXT NOT NULL REFERENCES fin_ad_accounts(id) ON DELETE CASCADE,
 external_id TEXT NOT NULL,
 name TEXT NOT NULL DEFAULT '',
 team_id TEXT,
 teammate TEXT,
 owner_set_at TEXT,
 owner_set_by TEXT,
 prior_team_id TEXT,
 prior_teammate TEXT,
 first_seen_on TEXT NOT NULL,
 last_seen_on TEXT NOT NULL,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE (ad_account_id, external_id)
);
CREATE TABLE ci_runs(
        id INTEGER PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL,
        remote_id TEXT NOT NULL DEFAULT '', github_run_id TEXT NOT NULL DEFAULT '',
        task_id TEXT NOT NULL DEFAULT '', bot TEXT NOT NULL DEFAULT '',
        cpus INTEGER NOT NULL DEFAULT 4, requested_minutes INTEGER NOT NULL DEFAULT 0,
        minutes INTEGER NOT NULL DEFAULT 0, reserve_cents INTEGER NOT NULL DEFAULT 0,
        cost_cents INTEGER NOT NULL DEFAULT 0, hold_id TEXT NOT NULL DEFAULT '',
        entry_id TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL, seen_at TEXT NOT NULL DEFAULT '');
CREATE TABLE ci_run_extensions(
        id INTEGER PRIMARY KEY, task_id TEXT NOT NULL UNIQUE, minutes INTEGER NOT NULL,
        granted_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE factories (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    owner_id TEXT,
    position INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    retired_at TEXT
, goal TEXT, manager_id TEXT);
CREATE TABLE factory_manager_runs (
    id TEXT PRIMARY KEY,
    factory_id TEXT NOT NULL,
    started_at TEXT NOT NULL,
    finished_at TEXT,
    status TEXT NOT NULL CHECK (status IN ('ok','failed')),
    bottleneck_stage_id TEXT,
    judgment_count INTEGER NOT NULL DEFAULT 0,
    wake_key TEXT,
    woke INTEGER NOT NULL DEFAULT 0,
    model_called INTEGER NOT NULL DEFAULT 0,
    error TEXT
);
CREATE TABLE factory_manager_actions (
    id TEXT PRIMARY KEY,
    factory_id TEXT NOT NULL,
    factory_manager_run_id TEXT NOT NULL,
    action TEXT NOT NULL CHECK (action IN ('ask_manager','open_botops','propose_rule','post_note')),
    target_actor TEXT,
    note TEXT,
    created_at TEXT NOT NULL
);
CREATE TABLE github_user_token(
 id TEXT PRIMARY KEY,
 login TEXT NOT NULL,
 github_id INTEGER NOT NULL DEFAULT 0,
 client_id TEXT NOT NULL DEFAULT '',
 ciphertext BLOB NOT NULL,
 nonce BLOB NOT NULL,
 access_expires_at TEXT,
 refresh_expires_at TEXT,
 authorized_by TEXT NOT NULL,
 authorized_at TEXT NOT NULL,
 refreshed_at TEXT
);
CREATE TABLE github_user_states(
 nonce TEXT PRIMARY KEY,
 actor TEXT NOT NULL,
 created_at REAL NOT NULL
);
CREATE TABLE setup_handoffs (
 token_hash TEXT PRIMARY KEY,
 created_at TEXT NOT NULL,
 expires_at TEXT NOT NULL,
 used_at TEXT,
 revoked_at TEXT,
 human_token_id TEXT
);
CREATE TABLE "entities" (
  seq INTEGER PRIMARY KEY,
  id TEXT NOT NULL UNIQUE,
  type TEXT NOT NULL,
  name TEXT NOT NULL,
  name_key TEXT NOT NULL DEFAULT '',
  aliases TEXT NOT NULL DEFAULT '[]',
  external_ids TEXT NOT NULL DEFAULT '{}',
  tier TEXT,
  summary TEXT NOT NULL DEFAULT '',
  properties TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'active',
  merged_into_id TEXT,
  last_verified_at TEXT,
  primary_email TEXT,
  primary_domain TEXT,
  owner_type TEXT,
  owner_id TEXT,
  audience TEXT NOT NULL DEFAULT 'company',
  self_link_keys TEXT NOT NULL DEFAULT '',
  last_activity_at TEXT,
  mentions_count INTEGER NOT NULL DEFAULT 0,
  created_by TEXT NOT NULL,
  created_by_type TEXT NOT NULL DEFAULT 'system',
  created_by_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT, self INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "entity_links" (
  id TEXT PRIMARY KEY,
  from_entity_id TEXT NOT NULL,
  link_key TEXT NOT NULL,
  to_entity_id TEXT NOT NULL,
  valid_from_on TEXT,
  valid_until_on TEXT,
  confidence REAL NOT NULL DEFAULT 0.6,
  source_type TEXT,
  source_id TEXT,
  properties TEXT NOT NULL DEFAULT '{}',
  created_by TEXT NOT NULL,
  created_by_type TEXT NOT NULL DEFAULT 'system',
  created_by_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL, evidence_id TEXT);
CREATE TABLE "entity_identifiers" (
  id INTEGER PRIMARY KEY,
  entity_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  value TEXT NOT NULL,
  normalized_value TEXT NOT NULL,
  scope_type TEXT,
  scope_id TEXT,
  primary_identifier INTEGER NOT NULL DEFAULT 0,
  source_type TEXT,
  source_id TEXT,
  valid_from_on TEXT,
  valid_until_on TEXT, derived INTEGER NOT NULL DEFAULT 0);
CREATE VIRTUAL TABLE market_fts USING fts5(
  kind UNINDEXED,
  ref UNINDEXED,
  name,
  aliases,
  summary,
  quote,
  our_read,
  tokenize = 'unicode61 remove_diacritics 1');
CREATE TABLE entity_types (
  id TEXT PRIMARY KEY,
  key TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  plural_name TEXT NOT NULL DEFAULT '',
  icon TEXT NOT NULL DEFAULT '',
  built_in INTEGER NOT NULL DEFAULT 0,
  mode TEXT NOT NULL DEFAULT 'native' CHECK (mode IN ('native', 'linked')),
  linked_connection_id TEXT,
  description TEXT NOT NULL DEFAULT '',
  created_by_type TEXT NOT NULL DEFAULT 'system',
  created_by_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  archived_at TEXT);
CREATE TABLE link_types (
  id TEXT PRIMARY KEY,
  key TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  inverse_name TEXT NOT NULL DEFAULT '',
  from_entity_type TEXT REFERENCES entity_types(key),
  to_entity_type TEXT REFERENCES entity_types(key),
  inherits_rules INTEGER NOT NULL DEFAULT 0,
  symmetric INTEGER NOT NULL DEFAULT 0,
  description TEXT NOT NULL DEFAULT '',
  built_in INTEGER NOT NULL DEFAULT 0,
  created_by_type TEXT NOT NULL DEFAULT 'system',
  created_by_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  archived_at TEXT);
CREATE TABLE entity_attributes (
  id TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL REFERENCES entity_types(key),
  key TEXT NOT NULL,
  name TEXT NOT NULL,
  value_type TEXT NOT NULL CHECK (value_type IN ('text', 'number', 'currency', 'date', 'timestamp', 'checkbox', 'select', 'status', 'email', 'phone', 'domain', 'url', 'personal_name', 'rating', 'actor')),
  multiple INTEGER NOT NULL DEFAULT 0,
  unique_value INTEGER NOT NULL DEFAULT 0,
  required INTEGER NOT NULL DEFAULT 0,
  options TEXT NOT NULL DEFAULT '[]',
  owner_type TEXT NOT NULL DEFAULT 'tico',
  owner_id TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  sensitive INTEGER NOT NULL DEFAULT 0,
  position INTEGER NOT NULL DEFAULT 0,
  created_by_type TEXT NOT NULL DEFAULT 'system',
  created_by_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  archived_at TEXT,
  UNIQUE (entity_type, key));
CREATE TABLE entity_values (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  entity_attribute_id TEXT NOT NULL REFERENCES entity_attributes(id),
  single_value INTEGER NOT NULL DEFAULT 1,
  text_value TEXT,
  number_value REAL,
  currency TEXT,
  date_value TEXT,
  timestamp_value TEXT,
  option_key TEXT,
  json_value TEXT,
  source_type TEXT,
  source_id TEXT,
  evidence_id TEXT,
  confidence REAL NOT NULL DEFAULT 0.6,
  updated_at TEXT NOT NULL);
CREATE TABLE entity_value_history (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  entity_attribute_id TEXT NOT NULL REFERENCES entity_attributes(id),
  value TEXT NOT NULL,  -- JSON
  source_type TEXT,
  source_id TEXT,
  evidence_id TEXT,
  confidence REAL,
  active_from TEXT NOT NULL,
  active_until TEXT NOT NULL);
CREATE TABLE entity_external_refs (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  connection_id TEXT NOT NULL DEFAULT '',
  system TEXT NOT NULL,
  external_type TEXT NOT NULL,
  external_id TEXT NOT NULL,
  url TEXT NOT NULL DEFAULT '',
  revision TEXT NOT NULL DEFAULT '',
  synced_at TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  UNIQUE (system, external_type, external_id));
CREATE TABLE entity_activities (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  kind TEXT NOT NULL,
  occurred_at TEXT NOT NULL,
  subject_type TEXT,
  subject_id TEXT,
  external_ref TEXT,
  actor_type TEXT,
  actor_id TEXT,
  direction TEXT,
  summary TEXT NOT NULL DEFAULT '');
CREATE TABLE entity_connections (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  actor_type TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  first_interaction_at TEXT,
  last_interaction_at TEXT,
  interactions_count INTEGER NOT NULL DEFAULT 0,
  strength REAL NOT NULL DEFAULT 0,
  UNIQUE (entity_id, actor_type, actor_id));
CREATE TABLE entity_notes (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  author_type TEXT NOT NULL,
  author_id TEXT NOT NULL,
  body TEXT NOT NULL,
  audience TEXT NOT NULL DEFAULT 'company' CHECK (audience IN ('me', 'company')),
  pinned_at TEXT,
  evidence_id TEXT,
  created_at TEXT NOT NULL);
CREATE TABLE entity_views (
  id TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL REFERENCES entity_types(key),
  name TEXT NOT NULL,
  layout TEXT NOT NULL DEFAULT 'list',
  filters TEXT NOT NULL DEFAULT '{}',
  columns TEXT NOT NULL DEFAULT '[]',
  sort TEXT NOT NULL DEFAULT '',
  group_attribute_id TEXT REFERENCES entity_attributes(id),
  owner_type TEXT NOT NULL DEFAULT 'system',
  owner_id TEXT NOT NULL DEFAULT '',
  shared INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL);
CREATE TABLE entity_mentions (
  id TEXT PRIMARY KEY,
  mentionable_type TEXT NOT NULL,
  mentionable_id TEXT NOT NULL,
  mentionable_revision TEXT NOT NULL DEFAULT '',
  entity_id TEXT NOT NULL REFERENCES entities(id),
  role TEXT NOT NULL DEFAULT 'mentioned' CHECK (role IN ('subject', 'mentioned')),
  quote TEXT NOT NULL DEFAULT '',
  occurrence INTEGER NOT NULL DEFAULT 0,
  confidence REAL NOT NULL DEFAULT 0.6,
  method TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'linked',
  created_at TEXT NOT NULL);
CREATE TABLE entity_suppressions (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  value_hash TEXT NOT NULL,
  created_at TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  UNIQUE (kind, value_hash));
CREATE TABLE entity_sources (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  source_type TEXT NOT NULL,
  source_id TEXT NOT NULL,
  visibility TEXT NOT NULL CHECK (visibility IN ('company', 'restricted')),
  created_at TEXT NOT NULL,
  UNIQUE (entity_id, source_type, source_id));
CREATE TABLE entity_merges (
  id TEXT PRIMARY KEY,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  into_entity_id TEXT NOT NULL REFERENCES entities(id),
  moved TEXT NOT NULL DEFAULT '{}',
  prior TEXT NOT NULL DEFAULT '{}',
  actor_type TEXT NOT NULL DEFAULT 'system',
  actor_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  undone_at TEXT);
CREATE TABLE entity_lookups (
  id TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL,
  entity_id TEXT NOT NULL REFERENCES entities(id),
  created_at TEXT NOT NULL,
  UNIQUE (attempt_id, entity_id));
CREATE TABLE fin_receipts (
 id TEXT PRIMARY KEY,
 book_id TEXT NOT NULL REFERENCES fin_books(id),
 file_id TEXT NOT NULL,
 read_amount BIGINT,
 read_date TEXT,
 read_vendor_name TEXT NOT NULL DEFAULT '',
 read_vendor_key TEXT NOT NULL DEFAULT '',
 read_by TEXT NOT NULL DEFAULT '',
 match_feed_id TEXT,
 confidence REAL,
 status TEXT NOT NULL DEFAULT 'unread'
   CHECK (status IN ('unread','unmatched','suggested','attached','rejected')),
 rejected_feed_ids TEXT NOT NULL DEFAULT '[]',
 attachment_id TEXT,
 prior_status TEXT,
 prior_feed_id TEXT,
 prior_confidence REAL,
 created_by TEXT NOT NULL,
 decided_at TEXT,
 decided_by TEXT,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE (book_id, file_id)
);
CREATE TABLE fin_statement_uploads (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id),
  money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id), file_hash TEXT NOT NULL,
  file_name TEXT NOT NULL DEFAULT '', file_format TEXT NOT NULL CHECK (file_format IN ('csv','ofx')),
  start_date TEXT NOT NULL, end_date TEXT NOT NULL, opening_balance BIGINT, closing_balance BIGINT,
  ends_at BIGINT NOT NULL, off_by BIGINT NOT NULL DEFAULT 0,
  row_count INTEGER NOT NULL, new_count INTEGER NOT NULL, duplicate_count INTEGER NOT NULL,
  skipped_count INTEGER NOT NULL DEFAULT 0, statement_id TEXT, action_id TEXT NOT NULL,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, undone_at TEXT, undone_by TEXT);
CREATE TABLE fin_statement_previews (
  token_hash TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id),
  money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id), file_hash TEXT NOT NULL,
  new_digest TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE fin_subscriptions (
 id TEXT PRIMARY KEY,
 book_id TEXT NOT NULL,
 vendor_key TEXT NOT NULL,
 money_account_id TEXT,
 card_id TEXT,
 source_key TEXT NOT NULL DEFAULT '',
 cadence TEXT NOT NULL DEFAULT 'monthly' CHECK (cadence IN ('monthly','annual')),
 amount INTEGER NOT NULL DEFAULT 0,
 seats INTEGER,
 status TEXT NOT NULL DEFAULT 'suggested' CHECK (status IN ('suggested','active','ignored','cancelled')),
 next_charge_on TEXT,
 last_charge_on TEXT,
 last_charge_id TEXT,
 last_amount INTEGER NOT NULL DEFAULT 0,
 first_charge_on TEXT,
 confirmed_at TEXT,
 confirmed_by TEXT,
 prior TEXT,
 created_at TEXT NOT NULL,
 created_by TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE (book_id, vendor_key, source_key)
);
CREATE TABLE assistant_actions (id TEXT PRIMARY KEY, owner TEXT NOT NULL, conversation_id TEXT, summary TEXT NOT NULL, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL, proposed_via TEXT, created_at TEXT NOT NULL, decided_at TEXT, result TEXT, confirm_hash TEXT, running_since TEXT, description TEXT, diff TEXT, proposer TEXT, ask TEXT);
CREATE TABLE pipelines (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, goal TEXT NOT NULL DEFAULT '', prefix TEXT, manager_id TEXT, owner_id TEXT, private INTEGER NOT NULL DEFAULT 0 CHECK (private IN (0, 1)), factory_id TEXT, preset TEXT, settings_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, retired_at TEXT, keep_warm_hours INTEGER NOT NULL DEFAULT 8 CHECK (keep_warm_hours BETWEEN 0 AND 24));
CREATE TABLE stages (id TEXT PRIMARY KEY, pipeline_id TEXT NOT NULL REFERENCES pipelines(id), position INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('work', 'done', 'closed')), name TEXT NOT NULL, purpose TEXT NOT NULL DEFAULT '', owner TEXT, by_hand INTEGER NOT NULL DEFAULT 0 CHECK (by_hand IN (0, 1)), task_limit INTEGER CHECK (task_limit IS NULL OR task_limit > 0), expected_minutes INTEGER CHECK (expected_minutes IS NULL OR expected_minutes > 0), expected_bots_only INTEGER NOT NULL DEFAULT 0 CHECK (expected_bots_only IN (0, 1)), on_enter TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(on_enter)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, retired_at TEXT, requests_move_on INTEGER NOT NULL DEFAULT 0 CHECK (requests_move_on IN (0, 1)), pick TEXT CHECK (pick IS NULL OR json_valid(pick)), side INTEGER NOT NULL DEFAULT 0 CHECK (side IN (0,1)));
CREATE TABLE answers (id TEXT PRIMARY KEY, visit_id TEXT NOT NULL REFERENCES visits(id), requirement_id TEXT NOT NULL REFERENCES requirements(id), by_id TEXT NOT NULL, answer TEXT NOT NULL, notes TEXT, page_version INTEGER, created_at TEXT NOT NULL, undone_at TEXT, name TEXT, value_type TEXT CHECK (value_type IS NULL OR value_type IN ('text', 'number', 'choice')), heads TEXT CHECK (heads IS NULL OR json_valid(heads)));
CREATE TABLE snoozes (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, visit_id TEXT, by_id TEXT NOT NULL, why TEXT, until_at TEXT, created_at TEXT NOT NULL, ended_at TEXT, ended_by_id TEXT, filed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE links (id TEXT PRIMARY KEY, from_task_id TEXT NOT NULL, to_task_id TEXT NOT NULL, visit_id TEXT, kind TEXT NOT NULL CHECK (kind IN ('sub_task', 'handoff')), created_at TEXT NOT NULL, CHECK (from_task_id <> to_task_id));
CREATE TABLE task_move_guards (id INTEGER PRIMARY KEY CHECK (id = 1), open INTEGER NOT NULL DEFAULT 0 CHECK (open IN (0, 1)), task_id TEXT);
CREATE TABLE "feedbacks"(id TEXT PRIMARY KEY, person_id TEXT NOT NULL,
 subject_type TEXT NOT NULL CHECK (subject_type IN ('message','task','approval','ask')), subject_id TEXT NOT NULL,
 bot_id TEXT NOT NULL, conversation_id TEXT, attempt_id TEXT, model TEXT, harness TEXT, subject_revision INTEGER,
 rating TEXT NOT NULL CHECK (rating IN ('up','down')),
 reason TEXT NOT NULL DEFAULT '' CHECK (length(reason) <= 1000),
 outcome TEXT NOT NULL DEFAULT 'none' CHECK (outcome IN ('none','told_bot','rule')), note_id TEXT, org_rule_id TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE ok_grants (
  requirement_id TEXT PRIMARY KEY,
  asked_by_id TEXT NOT NULL,
  subject TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  content TEXT NOT NULL DEFAULT 'null' CHECK (json_valid(content)),
  filed INTEGER NOT NULL DEFAULT 0 CHECK (filed IN (0, 1)),
  created_at TEXT NOT NULL,
  ok_at TEXT,
  ok_by_id TEXT,
  answer_id TEXT,
  used_at TEXT,
  used_by_id TEXT, asked_of_id TEXT, revoked_at TEXT,
  CHECK ((ok_at IS NULL) = (ok_by_id IS NULL)),
  CHECK ((used_at IS NULL) = (used_by_id IS NULL)),
  CHECK (used_at IS NULL OR ok_at IS NOT NULL)
);
CREATE TABLE ok_shown (
  requirement_id TEXT NOT NULL,
  person_id TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  shown_at TEXT NOT NULL,
  PRIMARY KEY (requirement_id, person_id, content_hash)
);
CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT, body TEXT, requester_id TEXT, owner_id TEXT, status TEXT NOT NULL DEFAULT 'open', due_at TEXT, conversation_id TEXT, created_at TEXT, updated_at TEXT, done_at TEXT, closed_at TEXT, closed_by_id TEXT, note TEXT, goal_id TEXT, labels TEXT NOT NULL DEFAULT '[]', number INTEGER, private INTEGER NOT NULL DEFAULT 1 CHECK (private IN (0,1)), live_meeting_id TEXT, readers TEXT, work_revision INTEGER NOT NULL DEFAULT 0, pipeline_id TEXT REFERENCES pipelines(id), stage_id TEXT REFERENCES stages(id), assignee_id TEXT, lane TEXT NOT NULL DEFAULT 'company', rank REAL, occurrence TEXT, occurrence_step TEXT, rule_due_id TEXT, checkpoint TEXT, checkpoint_at TEXT, checkpoint_by_id TEXT, checkpoint_state TEXT, checkpoint_blocked INTEGER NOT NULL DEFAULT 0, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','private')), public_title TEXT NOT NULL DEFAULT '', public_summary TEXT NOT NULL DEFAULT '', size REAL, request_id TEXT, version INTEGER NOT NULL DEFAULT 1, acceptance TEXT NOT NULL DEFAULT '[]', human_id TEXT, prefix TEXT);
CREATE TABLE push_subscriptions (id TEXT PRIMARY KEY, actor TEXT NOT NULL, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TEXT NOT NULL, last_ok_at TEXT, failed_at TEXT, failures INTEGER NOT NULL DEFAULT 0, gone_at TEXT);
CREATE TABLE run_starts(id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id TEXT NOT NULL UNIQUE);
CREATE TABLE "github_releases" (id TEXT PRIMARY KEY, repo TEXT NOT NULL COLLATE NOCASE, tag TEXT NOT NULL, commit_sha TEXT, prerelease INTEGER NOT NULL DEFAULT 0 CHECK (prerelease IN (0, 1)), published_at TEXT NOT NULL, metadata_version INTEGER NOT NULL, read_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE "github_release_reads" (repo TEXT PRIMARY KEY COLLATE NOCASE, read_at TEXT NOT NULL, metadata_version INTEGER NOT NULL);
CREATE TABLE "github_release_commits" (release_id TEXT NOT NULL REFERENCES "github_releases"(id), commit_sha TEXT NOT NULL, included INTEGER NOT NULL CHECK (included IN (0, 1)), checked_at TEXT NOT NULL, PRIMARY KEY (release_id, commit_sha));
CREATE TABLE github_deliveries (id TEXT PRIMARY KEY, event TEXT NOT NULL, received_at TEXT NOT NULL);
CREATE TABLE requirement_pages (id TEXT PRIMARY KEY, visit_id TEXT NOT NULL REFERENCES visits(id), requirement_id TEXT NOT NULL REFERENCES requirements(id), file_id TEXT NOT NULL, version INTEGER NOT NULL, item_versions TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(item_versions)), attached_by_id TEXT NOT NULL, created_at TEXT NOT NULL, replaced_at TEXT, rubric_hash TEXT, judged_against TEXT NOT NULL DEFAULT '{}');
CREATE TABLE page_verdicts (id TEXT PRIMARY KEY, file_id TEXT NOT NULL, version INTEGER NOT NULL, rubric_hash TEXT NOT NULL, verdict TEXT CHECK (verdict IS NULL OR verdict IN ('met', 'not_met', 'unsure', 'failed')), p REAL, reasons TEXT, model TEXT, cost_usd REAL NOT NULL DEFAULT 0, tries INTEGER NOT NULL DEFAULT 0, last_error TEXT, next_try_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE calendars (
  id TEXT PRIMARY KEY,
  owner_type TEXT NOT NULL CHECK (owner_type IN ('human','bot','shared')),
  owner_id TEXT,
  name TEXT NOT NULL,
  home TEXT NOT NULL DEFAULT 'tico' CHECK (home IN ('tico','google')),
  google_calendar_id TEXT,
  time_zone TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE calendar_events (
  id TEXT PRIMARY KEY,
  calendar_id TEXT NOT NULL REFERENCES calendars(id) ON DELETE CASCADE,
  uid TEXT NOT NULL,
  title TEXT NOT NULL,
  notes TEXT,
  location TEXT,
  meeting_url TEXT,
  all_day INTEGER NOT NULL DEFAULT 0 CHECK (all_day IN (0, 1)),
  starts_on TEXT,
  ends_on TEXT,
  starts_at_local TEXT,
  ends_at_local TEXT,
  time_zone TEXT,
  starts_at TEXT NOT NULL,
  ends_at TEXT NOT NULL,
  rrule TEXT,
  until_at TEXT,
  recurring_event_id TEXT REFERENCES calendar_events(id) ON DELETE CASCADE,
  original_starts_at TEXT,
  status TEXT NOT NULL DEFAULT 'confirmed' CHECK (status IN ('confirmed','tentative','cancelled')),
  visibility TEXT NOT NULL DEFAULT 'default' CHECK (visibility IN ('default','private')),
  sequence INTEGER NOT NULL DEFAULT 0,
  created_by TEXT,
  task_id TEXT,
  thread_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK ((all_day = 1) = (starts_on IS NOT NULL AND ends_on IS NOT NULL)),
  CHECK (all_day = 1 OR (starts_at_local IS NOT NULL AND ends_at_local IS NOT NULL AND time_zone IS NOT NULL)),
  CHECK ((recurring_event_id IS NULL) = (original_starts_at IS NULL)),
  CHECK (recurring_event_id IS NULL OR rrule IS NULL)
);
CREATE TABLE calendar_event_attendees (
  id TEXT PRIMARY KEY,
  calendar_event_id TEXT NOT NULL REFERENCES calendar_events(id) ON DELETE CASCADE,
  attendee_type TEXT NOT NULL CHECK (attendee_type IN ('human','bot','external')),
  attendee_id TEXT,
  email TEXT,
  response TEXT NOT NULL DEFAULT 'needs_action'
    CHECK (response IN ('needs_action','accepted','tentative','declined')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK ((attendee_type = 'external') = (attendee_id IS NULL)),
  CHECK (attendee_type <> 'external' OR email IS NOT NULL)
);
CREATE TABLE absences (
  id TEXT PRIMARY KEY,
  human_id TEXT NOT NULL,
  starts_on TEXT NOT NULL,
  ends_on TEXT NOT NULL,
  note TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK (ends_on >= starts_on)
);
CREATE TABLE calendar_accesses (
  id TEXT PRIMARY KEY,
  calendar_id TEXT NOT NULL REFERENCES calendars(id) ON DELETE CASCADE,
  grantee_type TEXT NOT NULL CHECK (grantee_type IN ('human','bot','group')),
  grantee_id TEXT NOT NULL,
  level TEXT NOT NULL CHECK (level IN ('read','read_write')),
  created_by TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (calendar_id, grantee_type, grantee_id)
);
CREATE TABLE calendar_event_links (
  id TEXT PRIMARY KEY,
  google_calendar_id TEXT,
  ical_uid TEXT,
  tico_event_id TEXT,
  original_starts_at TEXT,
  link_type TEXT NOT NULL CHECK (link_type IN ('meeting','thread','task','bot')),
  link_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  CHECK ((tico_event_id IS NULL) <> (ical_uid IS NULL))
);
CREATE TABLE calendar_event_search_keys (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  calendar_event_id TEXT NOT NULL UNIQUE
);
CREATE VIRTUAL TABLE calendar_event_search USING fts5(
  title, notes, location, tokenize = 'porter unicode61 remove_diacritics 1'
);
CREATE TABLE item_metadata (id TEXT PRIMARY KEY, source TEXT NOT NULL, item_type TEXT NOT NULL, item_key TEXT NOT NULL COLLATE NOCASE, title TEXT, fields TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(fields)), metadata_version INTEGER NOT NULL, read_at TEXT, due_at TEXT, read_error TEXT, refused_at TEXT, gone_at TEXT, final_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE effects (id TEXT PRIMARY KEY, visit_id TEXT NOT NULL REFERENCES visits(id), kind TEXT NOT NULL CHECK (kind IN ('act', 'undo')), source TEXT NOT NULL, action TEXT NOT NULL, item_type TEXT NOT NULL, item_key TEXT NOT NULL COLLATE NOCASE, pinned TEXT, key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'owed' CHECK (state IN ('owed', 'done', 'failed', 'moot')), tries INTEGER NOT NULL DEFAULT 0, last_error TEXT, next_try_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE listening_sources (id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, key TEXT NOT NULL, kind TEXT NOT NULL, site TEXT NOT NULL DEFAULT '', target TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'never', last_read_at TEXT, last_ok_at TEXT, last_error TEXT, token_hash TEXT, snapshot TEXT, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (automation_id, key));
CREATE TABLE listening_items (id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, source_id TEXT NOT NULL, native_id TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', author TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', posted_at TEXT, text_key TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new', tag TEXT NOT NULL DEFAULT '', score REAL, copies INTEGER NOT NULL DEFAULT 0, duplicate_of_id TEXT, tries INTEGER NOT NULL DEFAULT 0, claimed_at TEXT, scored_at TEXT, run_id TEXT, sent_at TEXT, cost REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, delivered TEXT, UNIQUE (automation_id, native_id));
CREATE TABLE github_pr_diffs (repo TEXT NOT NULL, sha TEXT NOT NULL, diff_id TEXT, read_at TEXT NOT NULL, commits TEXT, files TEXT, PRIMARY KEY (repo, sha));
CREATE TABLE attempt_events(
 id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id TEXT NOT NULL REFERENCES attempts(id),
 seq INTEGER NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(attempt_id,seq));
CREATE TABLE attempt_event_briefs(attempt_id TEXT NOT NULL, seq INTEGER NOT NULL, brief TEXT NOT NULL, PRIMARY KEY(attempt_id,seq)) WITHOUT ROWID;
CREATE TABLE bot_app_view(
 bot TEXT PRIMARY KEY, turned_on_by TEXT NOT NULL, turned_on_at TEXT NOT NULL);
CREATE TABLE app_views(
 id TEXT PRIMARY KEY, bot TEXT NOT NULL, attempt_id TEXT NOT NULL, opened_at TEXT NOT NULL, expires_at TEXT NOT NULL,
 token_hash TEXT NOT NULL UNIQUE);
CREATE TABLE idea_checks (task_id TEXT PRIMARY KEY, visit_id TEXT, owed_at TEXT NOT NULL, checked_at TEXT, outcome TEXT, same_id TEXT, confidence REAL, call_id TEXT);
CREATE TABLE stage_rules (id TEXT PRIMARY KEY, name TEXT NOT NULL, pipeline_id TEXT NOT NULL DEFAULT '', stages TEXT NOT NULL DEFAULT '[]', event TEXT NOT NULL, timer TEXT NOT NULL DEFAULT '{}', cond TEXT NOT NULL DEFAULT '{}', jev TEXT NOT NULL DEFAULT '', then_do TEXT NOT NULL, then_params TEXT NOT NULL DEFAULT '{}', reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suggested')), suggests TEXT NOT NULL DEFAULT '', builtin TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, retired_at TEXT, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE stage_rule_marks (
  rule_id TEXT NOT NULL,
  task_id TEXT NOT NULL,
  mark TEXT NOT NULL,
  outcome TEXT NOT NULL,
  manager_id TEXT,
  matched_at TEXT NOT NULL,
  told_at TEXT,
  PRIMARY KEY (rule_id, task_id, mark)
);
CREATE TABLE stage_pick_turns (stage_id TEXT PRIMARY KEY, bot_id TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE growth_sync_runs (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, actor TEXT, started_at TEXT NOT NULL, ok INTEGER NOT NULL, error TEXT, written INTEGER NOT NULL DEFAULT 0, held INTEGER NOT NULL DEFAULT 0, not_written TEXT NOT NULL DEFAULT '[]');
CREATE TABLE growth_origins (cohort_id TEXT NOT NULL, field TEXT NOT NULL, origin TEXT NOT NULL CHECK (origin IN ('synced','typed')), quality TEXT NOT NULL DEFAULT 'actual' CHECK (quality IN ('actual','estimate')), source_id TEXT, run_id TEXT, by TEXT, at TEXT NOT NULL, held_value REAL, held_source_id TEXT, held_run_id TEXT, held_at TEXT, declined_value REAL, PRIMARY KEY (cohort_id, field));
CREATE TABLE growth_setup(
 id INTEGER PRIMARY KEY CHECK(id=1),
 first_opened_at TEXT, first_opened_by TEXT,
 settings_at TEXT, channel_at TEXT, source_at TEXT, month_at TEXT, done_at TEXT,
 numbers_seen_at TEXT, numbers_seen_by TEXT,
 set_up_before_first_open INTEGER);
CREATE TABLE assistant_shares (
  owner TEXT NOT NULL, bot TEXT NOT NULL, created_at TEXT NOT NULL, last_read_at TEXT,
  PRIMARY KEY (owner, bot));
CREATE TABLE assistant_share_settings (
  owner TEXT PRIMARY KEY, include_learned INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE growth_customers (source TEXT NOT NULL, customer_key TEXT NOT NULL, became TEXT NOT NULL, signed_up TEXT, channel TEXT, segment TEXT, plan TEXT, churned TEXT, revenue_month REAL, loaded_at TEXT NOT NULL, PRIMARY KEY (source, customer_key, became));
CREATE TABLE growth_customer_loads (id TEXT PRIMARY KEY, source TEXT NOT NULL, customers INTEGER NOT NULL, removed INTEGER NOT NULL DEFAULT 0, loaded_by TEXT, loaded_at TEXT NOT NULL);
CREATE TABLE org_rule_late(
 id TEXT PRIMARY KEY, verdict TEXT NOT NULL, output TEXT NOT NULL, target TEXT NOT NULL DEFAULT '{}',
 tries INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE growth_setup_shown(
