 start_line INTEGER NOT NULL, end_line INTEGER NOT NULL, UNIQUE(version_id,position));
CREATE TABLE doc_source_jobs(
 source_id TEXT PRIMARY KEY REFERENCES doc_sources(source_id), generation INTEGER NOT NULL,
 lease TEXT NOT NULL DEFAULT '', lease_until REAL NOT NULL DEFAULT 0, next_try_at REAL NOT NULL DEFAULT 0,
 snapshot_id TEXT, commit_sha TEXT NOT NULL DEFAULT '', inventory TEXT, skipped INTEGER NOT NULL DEFAULT 0,
 checked_at TEXT, resolved_at REAL NOT NULL DEFAULT 0);
CREATE VIRTUAL TABLE external_sections_fts USING fts5(
 title,path,heading,body,content='external_sections',content_rowid='id',tokenize='porter unicode61');
CREATE TABLE bot_tool_requests(
 id TEXT PRIMARY KEY, bot TEXT NOT NULL REFERENCES bots(id), kind TEXT NOT NULL,
 service TEXT NOT NULL, identity TEXT NOT NULL DEFAULT '', entry TEXT NOT NULL,
 task_id TEXT, requested_by TEXT NOT NULL, created_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE company_storage(
 id TEXT PRIMARY KEY, bucket TEXT NOT NULL, prefix TEXT NOT NULL DEFAULT '', region TEXT NOT NULL,
 access_key_id TEXT NOT NULL, secret TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, created_by TEXT NOT NULL, retired_at TEXT);
CREATE TABLE tico_storage(
 id INTEGER PRIMARY KEY CHECK(id=1), state TEXT NOT NULL CHECK(state IN ('off','on','credits_out','stopped')),
 bucket TEXT NOT NULL DEFAULT '', prefix TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '',
 access_key_id TEXT NOT NULL DEFAULT '', secret TEXT NOT NULL DEFAULT '', expires_at TEXT,
 signing_key_id TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', keep_until TEXT,
 changed_at TEXT, checked_at TEXT, error TEXT NOT NULL DEFAULT '');
CREATE TABLE storage_moves(
 id TEXT PRIMARY KEY, target TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('running','done','failed','stopped')),
 started_at TEXT NOT NULL, started_by TEXT NOT NULL, finished_at TEXT,
 estimate_files INTEGER NOT NULL, estimate_bytes INTEGER NOT NULL,
 moved_files INTEGER NOT NULL DEFAULT 0, moved_bytes INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0,
 error TEXT NOT NULL DEFAULT '');
CREATE TABLE computer_subscriptions(
 runner_id TEXT NOT NULL, runtime TEXT NOT NULL, subscription_id TEXT NOT NULL, set_by TEXT NOT NULL,
 updated_at TEXT NOT NULL, person TEXT NOT NULL DEFAULT '', PRIMARY KEY(runner_id, runtime));
CREATE TABLE attempt_subscriptions(
 attempt_id TEXT NOT NULL, runtime TEXT NOT NULL, subscription_id TEXT NOT NULL, revision INTEGER NOT NULL,
 PRIMARY KEY(attempt_id, runtime));
CREATE TABLE pending_subscription_fallbacks(
 attempt_id TEXT NOT NULL, runtime TEXT NOT NULL, PRIMARY KEY(attempt_id, runtime));
CREATE TABLE subscription_connects(
 login_id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', subscription_id TEXT NOT NULL DEFAULT '',
 owner_id TEXT NOT NULL DEFAULT '');
CREATE TABLE support_tickets(
 id TEXT PRIMARY KEY, actor TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open',
 message TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', sent TEXT NOT NULL DEFAULT '{}',
 hq_id TEXT NOT NULL, hq_secret TEXT NOT NULL, messages TEXT NOT NULL DEFAULT '[]',
 seen_id INTEGER NOT NULL DEFAULT 0, checked_at TEXT, request_key TEXT);
CREATE TABLE inbound_inboxes(
 inbox_id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, address TEXT NOT NULL,
 state TEXT NOT NULL, created_by TEXT NOT NULL, period_end REAL, cancel_pending INTEGER NOT NULL DEFAULT 0,
 used_for TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT 'company', group_id TEXT);
CREATE TABLE inbound_messages(
 seq INTEGER PRIMARY KEY AUTOINCREMENT, message_id TEXT NOT NULL UNIQUE, inbox_id TEXT NOT NULL,
 kind TEXT NOT NULL, received_at REAL NOT NULL, sender TEXT NOT NULL, subject TEXT NOT NULL,
 preview TEXT NOT NULL, body TEXT, code TEXT, spam INTEGER NOT NULL DEFAULT 0, truncated INTEGER NOT NULL DEFAULT 0,
 retention_removed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE inbound_sync(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), cursor INTEGER NOT NULL DEFAULT 0,
 last_synced_at REAL, error TEXT NOT NULL DEFAULT '', gaps TEXT NOT NULL DEFAULT '[]');
CREATE TABLE bills_inbound(
 id TEXT PRIMARY KEY, delivery TEXT NOT NULL, received_at TEXT NOT NULL, sender TEXT NOT NULL DEFAULT '',
 subject TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '', mime TEXT NOT NULL, sha256 TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'waiting', file_id TEXT, action_id TEXT, code TEXT NOT NULL DEFAULT '',
 tries INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE support_access(
 id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL, tier TEXT NOT NULL, computer_id TEXT, started_by TEXT NOT NULL,
 started_at TEXT NOT NULL, expires_at TEXT NOT NULL, ended_at TEXT, ended_by TEXT, end_reason TEXT, token_hash TEXT,
 hq_session TEXT);
CREATE TABLE support_access_log(
 id INTEGER PRIMARY KEY, session_id TEXT NOT NULL, created_at TEXT NOT NULL, by TEXT NOT NULL, method TEXT, path TEXT,
 status INTEGER);
CREATE TABLE credential_requests(
 id TEXT PRIMARY KEY, requester TEXT NOT NULL, conversation_id TEXT NOT NULL, bot TEXT NOT NULL, asker TEXT NOT NULL,
 env TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', format TEXT NOT NULL DEFAULT '', help_url TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL DEFAULT 'api_key', status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL, credential_id TEXT, message_id TEXT);
CREATE TABLE credential_imports(
 id TEXT PRIMARY KEY, requester TEXT NOT NULL, bot TEXT NOT NULL, env TEXT NOT NULL, name TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL DEFAULT 'api_key', state TEXT NOT NULL DEFAULT 'requested', message TEXT NOT NULL DEFAULT '',
 credential_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE watcher_items(
 bot TEXT NOT NULL, key TEXT NOT NULL, task_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(bot, key));
CREATE TABLE watcher_refs(
 bot TEXT NOT NULL, key TEXT NOT NULL, ref TEXT NOT NULL, PRIMARY KEY(bot, key, ref));
CREATE TABLE watcher_runs(
 bot TEXT NOT NULL, name TEXT NOT NULL, runner_id TEXT NOT NULL, started_at TEXT NOT NULL, finished_at TEXT NOT NULL,
 exit_code INTEGER NOT NULL, timed_out INTEGER NOT NULL DEFAULT 0, every INTEGER NOT NULL, output TEXT NOT NULL DEFAULT '',
 events INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(bot, name));
CREATE TABLE watcher_pending(
 bot TEXT NOT NULL, key TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL,
 later TEXT NOT NULL DEFAULT '[]', found TEXT, PRIMARY KEY(bot, key));
CREATE TABLE watcher_triage(
 bot TEXT NOT NULL, key TEXT NOT NULL, label TEXT NOT NULL, held INTEGER NOT NULL, detail TEXT NOT NULL,
 created_at TEXT NOT NULL, PRIMARY KEY(bot, key));
CREATE TABLE cloud_machines(
 bot TEXT PRIMARY KEY, mode TEXT NOT NULL DEFAULT 'cloud', placement TEXT NOT NULL DEFAULT 'shared',
 size TEXT NOT NULL DEFAULT 'default',
 always_on INTEGER NOT NULL DEFAULT 0, pause_minutes INTEGER, machine_id TEXT, runner_id TEXT,
 state TEXT NOT NULL DEFAULT 'none',
 machine_size TEXT, started_at TEXT, stopped_at TEXT, cost_month_usd REAL NOT NULL DEFAULT 0,
 starts_month INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '',
 active_at REAL, heartbeat_at REAL, ttl_s INTEGER, next_try_at REAL, failures INTEGER NOT NULL DEFAULT 0,
 problem TEXT NOT NULL DEFAULT '', problem_at TEXT, wake_key TEXT, woke_at REAL,
 enroll_by REAL, enroll_fails INTEGER NOT NULL DEFAULT 0, changed_by TEXT, updated_at TEXT, stop_until REAL,
 start_asked_at REAL, create_asked_at REAL, grow_storage INTEGER, grow_note TEXT NOT NULL DEFAULT '',
 grow_refused_size TEXT, drain_started_at REAL, grow_blocked_until REAL, move_drain REAL);
CREATE TABLE cloud_machine_codes(
 code_hash TEXT PRIMARY KEY, bot TEXT NOT NULL, created_at TEXT NOT NULL, replacement_for TEXT);
CREATE TABLE screening_verdicts(
 source TEXT NOT NULL, key TEXT NOT NULL, score REAL NOT NULL, kind TEXT NOT NULL DEFAULT '', label TEXT NOT NULL,
 created_at TEXT NOT NULL, PRIMARY KEY(source, key));
CREATE TABLE screening_pending(
 source TEXT NOT NULL, bot TEXT NOT NULL, key TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL,
 text TEXT NOT NULL, cache_key TEXT NOT NULL DEFAULT '', actor TEXT NOT NULL DEFAULT '', person TEXT NOT NULL DEFAULT '',
 incident INTEGER NOT NULL DEFAULT 0, later TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL,
 PRIMARY KEY(source, bot, key));
CREATE TABLE bot_task_tabs (
  bot TEXT NOT NULL, viewer TEXT NOT NULL DEFAULT '', tabs TEXT NOT NULL,
  updated_at TEXT NOT NULL, updated_by TEXT NOT NULL, widgets TEXT, PRIMARY KEY (bot, viewer));
CREATE TABLE learned_entries (
  id TEXT PRIMARY KEY, layer TEXT NOT NULL CHECK (layer IN ('personal','company')),
  person TEXT NOT NULL DEFAULT '', text TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  via TEXT, updated_at TEXT, updated_by TEXT);
CREATE TABLE cards (
  id TEXT PRIMARY KEY, template TEXT NOT NULL, settings TEXT NOT NULL DEFAULT '{}', title TEXT NOT NULL DEFAULT '',
  made_by_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by_id TEXT NOT NULL);
CREATE TABLE pins (
  id TEXT PRIMARY KEY, place TEXT NOT NULL, item TEXT NOT NULL, position INTEGER NOT NULL,
  size TEXT NOT NULL DEFAULT 'medium', made_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(place, item));
CREATE TABLE pin_places (
  place TEXT PRIMARY KEY, audience TEXT, saved_at TEXT NOT NULL, saved_by TEXT NOT NULL);
CREATE TABLE task_manager_seen(
 key TEXT PRIMARY KEY, department TEXT NOT NULL, stamp TEXT NOT NULL DEFAULT '', seen_at TEXT NOT NULL);
CREATE TABLE task_manager_reports(
 department TEXT PRIMARY KEY, name TEXT NOT NULL, items INTEGER NOT NULL DEFAULT 0, task_id TEXT, checked_at TEXT NOT NULL,
 changed_at TEXT NOT NULL DEFAULT '');
CREATE TABLE bookkeeper_seen(
 key TEXT PRIMARY KEY, stamp TEXT NOT NULL, seen_at TEXT NOT NULL);
CREATE TABLE bookkeeper_watch_listed(
 task_id TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY (task_id, key));
CREATE TABLE health_findings(
 key TEXT PRIMARY KEY, signature TEXT NOT NULL, check_id TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL,
 detail TEXT NOT NULL DEFAULT '', fix TEXT NOT NULL DEFAULT '', first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL,
 present INTEGER NOT NULL DEFAULT 1, occurrences INTEGER NOT NULL DEFAULT 1, last_woke_at TEXT NOT NULL DEFAULT '',
 severity TEXT NOT NULL DEFAULT 'warn', pending INTEGER NOT NULL DEFAULT 0);
CREATE TABLE health_reports(
 signature TEXT PRIMARY KEY, ticket_id TEXT, approval_id TEXT, created_at TEXT NOT NULL, reported_occurrences INTEGER NOT NULL DEFAULT 1,
 reported_at TEXT NOT NULL DEFAULT '');
CREATE TABLE invariant_state(
 check_id TEXT PRIMARY KEY, firing INTEGER NOT NULL DEFAULT 0, count INTEGER NOT NULL DEFAULT 0,
 examples TEXT NOT NULL DEFAULT '[]', checked_at TEXT, started_firing_at TEXT, task_id TEXT);
CREATE TABLE slack_channels(
 key TEXT PRIMARY KEY, channel_id TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '',
 post INTEGER NOT NULL DEFAULT 1, note TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL DEFAULT '');
CREATE TABLE flight_requests(created_at INTEGER NOT NULL, span INTEGER NOT NULL, route TEXT NOT NULL,
  caller TEXT NOT NULL, n INTEGER NOT NULL, errors INTEGER NOT NULL, bytes INTEGER NOT NULL, total_ms REAL NOT NULL,
  p50 REAL, p95 REAL, max_ms REAL, hist TEXT, PRIMARY KEY(created_at, span, route, caller)) WITHOUT ROWID;
CREATE TABLE flight_slow(id INTEGER PRIMARY KEY, created_at INTEGER NOT NULL, route TEXT, caller TEXT,
  actor TEXT, ms REAL, bytes INTEGER, status INTEGER, sql_ms REAL, wait_ms REAL, queries INTEGER, top TEXT);
CREATE TABLE flight_process(created_at INTEGER PRIMARY KEY, cpu REAL, rss INTEGER, threads INTEGER,
  fds INTEGER, sockets INTEGER, lag_p95 REAL, lag_max REAL, requests INTEGER, queries INTEGER, sql_ms REAL,
  txns INTEGER, wait_max REAL, hold_max REAL, hold_p95 REAL, locked INTEGER, dropped INTEGER);
CREATE TABLE flight_sql(created_at INTEGER NOT NULL, fingerprint TEXT NOT NULL, n INTEGER NOT NULL,
  total_ms REAL NOT NULL, p95 REAL, max_ms REAL, hist TEXT, PRIMARY KEY(created_at, fingerprint)) WITHOUT ROWID;
CREATE TABLE flight_db(created_at INTEGER PRIMARY KEY, bytes INTEGER, wal_bytes INTEGER, free_bytes INTEGER,
  detail TEXT);
CREATE TABLE flight_events(id INTEGER PRIMARY KEY, created_at INTEGER NOT NULL, kind TEXT NOT NULL,
  detail TEXT NOT NULL);
CREATE TABLE runner_load_samples(runner_id TEXT NOT NULL, created_at INTEGER NOT NULL,
  sampled_at INTEGER NOT NULL, cpu_pct REAL, mem_used INTEGER, mem_total INTEGER, swap_used INTEGER,
  swap_total INTEGER, running_turns INTEGER NOT NULL, PRIMARY KEY(runner_id,created_at)) WITHOUT ROWID;
CREATE TABLE attempt_load_snapshots(attempt_id TEXT PRIMARY KEY REFERENCES attempts(id) ON DELETE CASCADE,
  at_start TEXT, at_end TEXT) WITHOUT ROWID;
CREATE TABLE perf_points(runner_id TEXT NOT NULL, span INTEGER NOT NULL, created_at INTEGER NOT NULL,
  n INTEGER NOT NULL, scope TEXT NOT NULL DEFAULT 'host', cpu REAL NOT NULL, cpu_max REAL NOT NULL, load1 REAL,
  mem_used INTEGER, mem_max INTEGER, mem_total INTEGER, swap_used INTEGER, swap_total INTEGER, disk_free INTEGER,
  disk_total INTEGER, active INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(runner_id, span, created_at)) WITHOUT ROWID;
CREATE TABLE perf_usage(runner_id TEXT NOT NULL, span INTEGER NOT NULL, created_at INTEGER NOT NULL,
  kind TEXT NOT NULL, key TEXT NOT NULL, bot TEXT NOT NULL DEFAULT '', harness TEXT NOT NULL DEFAULT '',
  n INTEGER NOT NULL, cpu REAL NOT NULL, cpu_max REAL NOT NULL, mem INTEGER NOT NULL, mem_max INTEGER NOT NULL,
  PRIMARY KEY(runner_id, span, created_at, kind, key)) WITHOUT ROWID;
CREATE TABLE perf_overloads(id INTEGER PRIMARY KEY, runner_id TEXT NOT NULL, started_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL, ended_at INTEGER, reasons TEXT NOT NULL, cpu_max REAL NOT NULL, mem_max REAL NOT NULL,
  runs_max INTEGER NOT NULL DEFAULT 0, bots TEXT NOT NULL DEFAULT '[]', procs TEXT NOT NULL DEFAULT '[]');
CREATE TABLE idempotency_messages(message_id TEXT NOT NULL, actor TEXT NOT NULL, operation TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(message_id, actor, operation, key)) WITHOUT ROWID;
CREATE TABLE fin_settings (
  key TEXT PRIMARY KEY, value TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE fin_books (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, base_currency TEXT NOT NULL,
  basis TEXT NOT NULL DEFAULT 'cash' CHECK (basis IN ('cash','accrual')),
  fiscal_year_start INTEGER NOT NULL DEFAULT 1 CHECK (fiscal_year_start BETWEEN 1 AND 12),
  mode TEXT NOT NULL DEFAULT 'native' CHECK (mode IN ('native','mirror')), mirror_connection_id TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_accounts (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), code TEXT NOT NULL, name TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('asset','liability','equity','income','expense')),
  subtype TEXT NOT NULL DEFAULT '', parent_id TEXT REFERENCES fin_accounts(id), active INTEGER NOT NULL DEFAULT 1,
  external_ref TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT,
  UNIQUE (book_id, code));
CREATE TABLE fin_periods (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), start_date TEXT NOT NULL,
  end_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  closed_at TEXT, closed_by TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  UNIQUE (book_id, start_date));
CREATE TABLE fin_entries (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), entry_date TEXT NOT NULL,
  memo TEXT NOT NULL DEFAULT '',
  source TEXT NOT NULL CHECK (source IN ('manual','import','bank','card','bill','invoice','payment','usage','sync')),
  source_id TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'posted' CHECK (status IN ('posted','reversed')),
  reverses_id TEXT REFERENCES fin_entries(id), period_id TEXT REFERENCES fin_periods(id), action_id TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, basis TEXT NOT NULL DEFAULT 'both' CHECK (basis IN ('both','accrual')));
CREATE TABLE fin_lines (
  id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES fin_entries(id), book_id TEXT NOT NULL,
  line_no INTEGER NOT NULL, entry_date TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES fin_accounts(id),
  amount BIGINT NOT NULL, currency TEXT NOT NULL, original_amount BIGINT NOT NULL, fx_rate TEXT NOT NULL DEFAULT '1',
  contact_id TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, role TEXT NOT NULL DEFAULT '', external_line TEXT NOT NULL DEFAULT '');
CREATE TABLE fin_dimensions (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('project','custom','class')), value TEXT NOT NULL,
  name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  UNIQUE (kind, value));
CREATE TABLE fin_line_tags (
  line_id TEXT NOT NULL REFERENCES fin_lines(id),
  kind TEXT NOT NULL CHECK (kind IN ('team','teammate','budget','project','custom','location','class')), value TEXT NOT
  NULL,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, PRIMARY KEY (line_id, kind));
CREATE TABLE fin_rollups (
  book_id TEXT NOT NULL, day TEXT NOT NULL, account_id TEXT NOT NULL, tagset TEXT NOT NULL,
  team TEXT NOT NULL DEFAULT '', teammate TEXT NOT NULL DEFAULT '', vendor TEXT NOT NULL DEFAULT '',
  amount BIGINT NOT NULL DEFAULT 0, line_count BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (book_id, day, account_id, tagset));
CREATE TABLE fin_book_entities (
  id TEXT PRIMARY KEY REFERENCES entities(id), book_id TEXT NOT NULL, entity_id TEXT NOT NULL REFERENCES entities(id),
  name TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'vendor' CHECK (kind IN ('vendor','customer','both')), emails TEXT NOT NULL DEFAULT '[]',
  default_account_id TEXT, is_1099 INTEGER NOT NULL DEFAULT 0, tax_id_ref TEXT,
  tax_id_last4 TEXT, payment_ref TEXT, active INTEGER NOT NULL DEFAULT 1, seats INTEGER, renewal_on TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, UNIQUE (entity_id, book_id));
CREATE TABLE fin_vendor_labels (
  book_id TEXT NOT NULL REFERENCES fin_books(id), name_key TEXT NOT NULL, label TEXT NOT NULL,
  seen_on TEXT NOT NULL, PRIMARY KEY (book_id, name_key));
CREATE TABLE fin_bills (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), vendor_id TEXT REFERENCES entities(id),
  number TEXT NOT NULL DEFAULT '', bill_date TEXT NOT NULL, due_date TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','open','scheduled','paid','void')),
  currency TEXT NOT NULL, total BIGINT NOT NULL DEFAULT 0, commitment_id TEXT, entry_id TEXT REFERENCES fin_entries(id),
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, terms_days INTEGER, memo TEXT NOT NULL DEFAULT '', origin TEXT NOT NULL DEFAULT 'manual', approved_by TEXT, approved_at TEXT, schedule TEXT NOT NULL DEFAULT '{}', amount_paid BIGINT NOT NULL DEFAULT 0, voided_at TEXT, pay_on TEXT);
CREATE TABLE fin_bill_lines (
  id TEXT PRIMARY KEY, bill_id TEXT NOT NULL REFERENCES fin_bills(id), account_id TEXT REFERENCES fin_accounts(id),
  amount BIGINT NOT NULL, description TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, external_line TEXT NOT NULL DEFAULT '', line_no INTEGER NOT NULL DEFAULT 0, item_id TEXT, po_line_id TEXT, prepaid_start TEXT, prepaid_months INTEGER);
CREATE TABLE fin_invoices (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), customer_id TEXT REFERENCES entities(id),
  number TEXT NOT NULL DEFAULT '', invoice_date TEXT NOT NULL, due_date TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','partial','paid','void')),
  currency TEXT NOT NULL, total BIGINT NOT NULL DEFAULT 0, amount_paid BIGINT NOT NULL DEFAULT 0, payment_link TEXT,
  entry_id TEXT REFERENCES fin_entries(id), created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT,
  send_approval_id TEXT, send_to TEXT, send_text TEXT, delivered_at TEXT, delivery_reason TEXT, terms_days INTEGER, memo TEXT NOT NULL DEFAULT '', sent_at TEXT, written_off BIGINT NOT NULL DEFAULT 0, voided_at TEXT);
CREATE TABLE fin_invoice_lines (
  id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES fin_invoices(id), account_id TEXT REFERENCES fin_accounts(id),
  amount BIGINT NOT NULL, description TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, external_line TEXT NOT NULL DEFAULT '', line_no INTEGER NOT NULL DEFAULT 0, taxable INTEGER NOT NULL DEFAULT 1, item_id TEXT);
CREATE TABLE fin_attachments (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), subject_kind TEXT NOT NULL,
  subject_id TEXT NOT NULL, file_id TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_money_accounts (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id),
  kind TEXT NOT NULL CHECK (kind IN ('bank','card_program','stripe','gateway_credit')), name TEXT NOT NULL,
  provider TEXT NOT NULL DEFAULT '', connection_id TEXT, account_id TEXT REFERENCES fin_accounts(id), last4 TEXT,
  holds_cash INTEGER NOT NULL DEFAULT 1, balance BIGINT, balance_currency TEXT, balance_as_of TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, provider_account_id TEXT,
  subtype TEXT NOT NULL DEFAULT '', available_balance BIGINT, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE fin_feed_txns (
  id TEXT PRIMARY KEY, money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id), provider_id TEXT NOT NULL,
  txn_date TEXT NOT NULL, amount BIGINT NOT NULL, currency TEXT NOT NULL, counterparty TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','matched','posted','ignored','covered')),
  entry_id TEXT REFERENCES fin_entries(id), commitment_id TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  updated_at TEXT, pending INTEGER NOT NULL DEFAULT 0, provider_status TEXT NOT NULL DEFAULT '', posted_at TEXT,
  kind TEXT NOT NULL DEFAULT '', card_id TEXT, hold_id TEXT, reconciliation_id TEXT, version INTEGER NOT NULL DEFAULT 0,
  request_id TEXT, raw TEXT NOT NULL DEFAULT '{}', entry_line_id TEXT, refund_of TEXT, vendor_key TEXT NOT NULL DEFAULT '', upload_id TEXT, UNIQUE (money_account_id, provider_id));
CREATE TABLE fin_reconciliations (
  id TEXT PRIMARY KEY, money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id), statement_end TEXT NOT NULL,
  statement_balance BIGINT NOT NULL, cleared TEXT NOT NULL DEFAULT '[]', difference BIGINT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','done')), completed_at TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, cleared_total BIGINT NOT NULL DEFAULT 0, statement_id TEXT,
  action_id TEXT, undone_at TEXT, undone_by TEXT);
CREATE TABLE fin_budgets (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), name TEXT NOT NULL, owner TEXT NOT NULL DEFAULT '',
  period TEXT NOT NULL DEFAULT 'month' CHECK (period IN ('month','quarter','year','once')),
  account_id TEXT REFERENCES fin_accounts(id), catch_all INTEGER NOT NULL DEFAULT 0, team TEXT NOT NULL DEFAULT '',
  teammate TEXT NOT NULL DEFAULT '', vendor TEXT NOT NULL DEFAULT '', parent_id TEXT REFERENCES fin_budgets(id),
  warn_pct INTEGER NOT NULL DEFAULT 80,
  at_limit TEXT NOT NULL DEFAULT 'warn' CHECK (at_limit IN ('warn','ask','decline','hold_payment')),
  rollover TEXT NOT NULL DEFAULT 'none' CHECK (rollover IN ('none','unused')), active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT);
CREATE TABLE fin_budget_versions (
  id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES fin_budgets(id), version INTEGER NOT NULL,
  effective_from TEXT NOT NULL, amount BIGINT NOT NULL CHECK (amount >= 0), currency TEXT NOT NULL,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, UNIQUE (budget_id, version));
CREATE TABLE fin_projections (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), account_id TEXT NOT NULL REFERENCES fin_accounts(id),
  month TEXT NOT NULL, team TEXT NOT NULL DEFAULT '', teammate TEXT NOT NULL DEFAULT '', amount BIGINT NOT NULL,
  currency TEXT NOT NULL,
  method TEXT NOT NULL CHECK (method IN ('trend','run_rate','recurring','fixed','manual')), set_by TEXT NOT NULL,
  as_of TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  UNIQUE (book_id, account_id, month, team, teammate));
CREATE TABLE fin_holds (
  id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES fin_budgets(id), amount BIGINT NOT NULL, currency TEXT NOT NULL,
  source TEXT NOT NULL, source_id TEXT NOT NULL DEFAULT '', target TEXT NOT NULL DEFAULT '', commitment_id TEXT,
  held_on TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'held' CHECK (status IN ('held','settled','released')), settled_amount BIGINT,
  entry_id TEXT REFERENCES fin_entries(id), expires_at TEXT, settled_at TEXT, released_at TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_allocations (
  id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES fin_budgets(id),
  target_kind TEXT NOT NULL CHECK (target_kind IN ('card','gateway_key','teammate')), target_id TEXT NOT NULL,
  amount BIGINT NOT NULL CHECK (amount >= 0), currency TEXT NOT NULL, hold_id TEXT REFERENCES fin_holds(id),
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, UNIQUE (budget_id, target_kind, target_id));
CREATE TABLE fin_card_auths (
  id TEXT PRIMARY KEY, card_id TEXT NOT NULL REFERENCES fin_cards(id), provider_auth_id TEXT, amount BIGINT NOT NULL,
  currency TEXT NOT NULL, merchant TEXT NOT NULL DEFAULT '', mode TEXT NOT NULL CHECK (mode IN ('live','synced')),
  decision TEXT NOT NULL, reasons TEXT NOT NULL DEFAULT '[]', hold_id TEXT REFERENCES fin_holds(id),
  commitment_id TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_card_saves (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), card_id TEXT NOT NULL REFERENCES fin_cards(id),
  vendor_key TEXT NOT NULL, vendor_label TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  saved_by TEXT NOT NULL, saved_at TEXT NOT NULL, removed_by TEXT, removed_at TEXT, created_at TEXT NOT NULL,
  created_by TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE (card_id, vendor_key));
CREATE TABLE fin_actions (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, actor TEXT NOT NULL,
  on_behalf_of TEXT NOT NULL DEFAULT '', rule_id TEXT NOT NULL DEFAULT '', idempotency_key TEXT NOT NULL UNIQUE,
  rule_results TEXT NOT NULL DEFAULT '[]',
  status TEXT NOT NULL CHECK (status IN ('committed','needs_approval','denied','failed','expired','withdrawn')),
  approval_id TEXT, approval_hash TEXT, approval_by TEXT, approval_to TEXT, result TEXT NOT NULL DEFAULT '{}', code TEXT NOT NULL DEFAULT '',
  reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE fin_rules (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('gate','posting')), name TEXT NOT NULL,
  words TEXT NOT NULL DEFAULT '', condition TEXT NOT NULL DEFAULT '{}', outcome TEXT NOT NULL DEFAULT '{}',
  examples TEXT NOT NULL DEFAULT '[]', external_rule_id TEXT, owner TEXT NOT NULL DEFAULT '',
  active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, priority INTEGER NOT NULL DEFAULT 100);
CREATE TABLE fin_rule_runs (
  id TEXT PRIMARY KEY, rule_id TEXT NOT NULL, action_id TEXT, subject TEXT NOT NULL DEFAULT '',
  inputs TEXT NOT NULL DEFAULT '{}', outcome TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_connections (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL,
  purpose TEXT NOT NULL CHECK (purpose IN ('bank','cards','books','payments')), credential_ref TEXT,
  status TEXT NOT NULL DEFAULT 'new', cursor TEXT, last_ok_at TEXT, last_error TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, name TEXT NOT NULL DEFAULT '',
  settings TEXT NOT NULL DEFAULT '{}', events_cursor TEXT, last_sync_at TEXT, next_sync_at TEXT);
CREATE TABLE fin_external_refs (
  id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES fin_connections(id), local_table TEXT NOT NULL,
  local_id TEXT NOT NULL, external_id TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT '', revision TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active',
  updated_at TEXT, seen_gen INTEGER, UNIQUE (connection_id, local_table, external_id));
CREATE TABLE fin_restatements (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), period_id TEXT NOT NULL REFERENCES fin_periods(id),
  day TEXT NOT NULL, change TEXT NOT NULL CHECK (change IN ('added','replaced','deleted')),
  entry_id TEXT REFERENCES fin_entries(id), reversal_id TEXT REFERENCES fin_entries(id),
  connection_id TEXT REFERENCES fin_connections(id), external_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_outbox (
  id TEXT PRIMARY KEY, connection_id TEXT REFERENCES fin_connections(id), action_id TEXT, op TEXT NOT NULL,
  payload TEXT NOT NULL DEFAULT '{}', idempotency_key TEXT NOT NULL UNIQUE, attempts INTEGER NOT NULL DEFAULT 0,
  next_try_at TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','failed','withheld')),
  last_error TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, unknown INTEGER NOT NULL DEFAULT 0, claimed_at TEXT);
CREATE TABLE fin_inbox (
  id TEXT PRIMARY KEY, connection_id TEXT REFERENCES fin_connections(id), provider TEXT NOT NULL,
  provider_event_id TEXT NOT NULL, payload TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'new',
  processed_at TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_try_at TEXT, tried TEXT NOT NULL DEFAULT '[]', UNIQUE (provider, provider_event_id));
CREATE TABLE fin_events (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, subject TEXT NOT NULL, period_key TEXT NOT NULL DEFAULT '',
  payload TEXT NOT NULL DEFAULT '{}', drained_at TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  UNIQUE (name, subject, period_key));
CREATE TABLE fin_usage_snapshots (
  id TEXT PRIMARY KEY, month TEXT NOT NULL, as_of TEXT NOT NULL, ai_nano BIGINT NOT NULL DEFAULT 0,
  video_nano BIGINT NOT NULL DEFAULT 0, rows TEXT NOT NULL DEFAULT '[]', posted_at TEXT, ignored_at TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, UNIQUE (month, as_of));
CREATE TABLE fin_rights (
  id TEXT PRIMARY KEY, teammate TEXT NOT NULL, right_name TEXT NOT NULL, granted_by TEXT NOT NULL, expires_at TEXT,
  revoked_at TEXT, revoked_by TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_view_defaults (
  role TEXT PRIMARY KEY, policy TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT);
CREATE TABLE fin_view_versions (
  id INTEGER PRIMARY KEY CHECK (id = 1), version BIGINT NOT NULL DEFAULT 0, reason TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL);
CREATE TABLE fin_settlements (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id),
  from_kind TEXT NOT NULL CHECK (from_kind IN ('payment','feed','credit','account','expected')),
  from_id TEXT NOT NULL DEFAULT '',
  to_kind TEXT NOT NULL CHECK (to_kind IN ('bill','invoice')), to_id TEXT NOT NULL, amount BIGINT NOT NULL,
  settled_on TEXT NOT NULL, entry_id TEXT, action_id TEXT, voided_at TEXT, voided_by TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_cash_rollups (
  book_id TEXT NOT NULL, day TEXT NOT NULL, account_id TEXT NOT NULL, tagset TEXT NOT NULL,
  team TEXT NOT NULL DEFAULT '', teammate TEXT NOT NULL DEFAULT '', vendor TEXT NOT NULL DEFAULT '',
  amount BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (book_id, day, account_id, tagset));
CREATE TABLE fin_credit_refunds (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id),
  credit_entry_id TEXT NOT NULL, refund_entry_id TEXT NOT NULL, amount BIGINT NOT NULL, day TEXT NOT NULL,
  voided_at TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_view_grants (
  id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL CHECK (subject_kind IN ('teammate','team')), subject TEXT NOT NULL,
  new_members INTEGER NOT NULL DEFAULT 0, members TEXT NOT NULL DEFAULT '[]',
  what TEXT NOT NULL CHECK (what IN ('everything','pnl','expenses','pnl_lines','balance_sheet','bs_lines','payables',
                                     'receivables','sources')),
  account_ids TEXT NOT NULL DEFAULT '[]', whose TEXT NOT NULL CHECK (whose IN ('own','team','company')),
  whose_team TEXT NOT NULL DEFAULT '', granted_by TEXT NOT NULL, expires_at TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','expired','revoked')),
  suspended_reason TEXT, revoked_at TEXT, revoked_by TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_recipients (
  id TEXT PRIMARY KEY, connection_id TEXT REFERENCES fin_connections(id), provider_recipient_id TEXT,
  name TEXT NOT NULL, method TEXT NOT NULL CHECK (method IN ('ach','wire','check','rtp')), last4 TEXT,
  details_hash TEXT NOT NULL, details_ref TEXT, version INTEGER NOT NULL DEFAULT 1,
  replaces_id TEXT REFERENCES fin_recipients(id),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','replaced')), contact_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, entity_id TEXT);
CREATE TABLE fin_provider_users (
  connection_id TEXT NOT NULL REFERENCES fin_connections(id), provider_user_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL, PRIMARY KEY (connection_id, provider_user_id));
CREATE TABLE fin_rule_counters (
  rule_id TEXT NOT NULL, period_key TEXT NOT NULL, subject TEXT NOT NULL DEFAULT '', amount BIGINT NOT NULL DEFAULT 0,
  count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY (rule_id, period_key, subject));
CREATE TABLE fin_statements (
  id TEXT PRIMARY KEY, money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id), provider_id TEXT,
  start_date TEXT, end_date TEXT NOT NULL, starting_balance BIGINT, ending_balance BIGINT NOT NULL,
  currency TEXT NOT NULL, source TEXT NOT NULL CHECK (source IN ('api','manual')), created_at TEXT NOT NULL,
  created_by TEXT NOT NULL, UNIQUE (money_account_id, end_date));
CREATE TABLE fin_private_lines (
  account_id TEXT PRIMARY KEY REFERENCES fin_accounts(id),
  others_see TEXT NOT NULL DEFAULT 'totals' CHECK (others_see IN ('totals','hidden')),
  full_detail TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT);
CREATE TABLE fin_raw_imports (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), content_hash TEXT NOT NULL,
  basis TEXT NOT NULL CHECK (basis IN ('cash','accrual')), source_name TEXT NOT NULL DEFAULT '',
  periods INTEGER NOT NULL CHECK (periods > 0), row_count INTEGER NOT NULL, gross BIGINT NOT NULL,
  action_id TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE fin_close_snapshots (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id),
  period_id TEXT NOT NULL UNIQUE REFERENCES fin_periods(id), month TEXT NOT NULL,
  accounts TEXT NOT NULL, pnl TEXT NOT NULL, balances TEXT NOT NULL,
  restated TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  UNIQUE (book_id, month));
CREATE TABLE fin_tax_jurisdictions (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), code TEXT NOT NULL, name TEXT NOT NULL,
  account_id TEXT NOT NULL REFERENCES fin_accounts(id), authority_id TEXT NOT NULL DEFAULT '',
  due_day INTEGER NOT NULL CHECK (due_day BETWEEN 1 AND 28), created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  UNIQUE (book_id, code), UNIQUE (account_id));
CREATE TABLE fin_tax_seeds (
  key TEXT PRIMARY KEY, rule_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE fin_purchase_orders (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), vendor_id TEXT NOT NULL REFERENCES entities(id),
  number TEXT NOT NULL DEFAULT '', po_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','approved','closed','void')),
  closed_by TEXT NOT NULL DEFAULT '' CHECK (closed_by IN ('','bills','hand')),
  currency TEXT NOT NULL, total BIGINT NOT NULL DEFAULT 0, memo TEXT NOT NULL DEFAULT '',
  sent_at TEXT, approved_by TEXT, approved_at TEXT, closed_at TEXT, voided_at TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT);
CREATE TABLE fin_po_lines (
  id TEXT PRIMARY KEY, po_id TEXT NOT NULL REFERENCES fin_purchase_orders(id), line_no INTEGER NOT NULL,
  account_id TEXT REFERENCES fin_accounts(id), item_id TEXT, amount BIGINT NOT NULL CHECK (amount > 0),
  description TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, UNIQUE (po_id, line_no));
CREATE TABLE fin_estimates (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), customer_id TEXT NOT NULL REFERENCES entities(id),
  number TEXT NOT NULL DEFAULT '', estimate_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','accepted','declined')),
  currency TEXT NOT NULL, total BIGINT NOT NULL DEFAULT 0, memo TEXT NOT NULL DEFAULT '',
  invoice_id TEXT REFERENCES fin_invoices(id), sent_at TEXT, decided_at TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT);
CREATE TABLE fin_estimate_lines (
  id TEXT PRIMARY KEY, estimate_id TEXT NOT NULL REFERENCES fin_estimates(id), line_no INTEGER NOT NULL,
  account_id TEXT REFERENCES fin_accounts(id), item_id TEXT, amount BIGINT NOT NULL CHECK (amount > 0),
  description TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '{}', taxable INTEGER,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, UNIQUE (estimate_id, line_no));
CREATE TABLE fin_bill_retained (
  bill_id TEXT NOT NULL REFERENCES fin_bills(id), po_line_id TEXT NOT NULL REFERENCES fin_po_lines(id),
  amount BIGINT NOT NULL CHECK (amount > 0), PRIMARY KEY (bill_id, po_line_id));
CREATE TABLE fin_prepaid_postings (
  bill_line_id TEXT NOT NULL REFERENCES fin_bill_lines(id), month TEXT NOT NULL,
  amount BIGINT NOT NULL CHECK (amount > 0), entry_id TEXT NOT NULL REFERENCES fin_entries(id),
  action_id TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL, PRIMARY KEY (bill_line_id, month));
CREATE TABLE fin_invoice_reminders (
  id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES fin_invoices(id), stage INTEGER NOT NULL CHECK (stage > 0),
  text TEXT NOT NULL, sent_to TEXT NOT NULL, action_id TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  send_approval_id TEXT, delivered_at TEXT, delivery_reason TEXT,
  UNIQUE (invoice_id, stage));
CREATE TABLE locations (
  id TEXT PRIMARY KEY, name TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'other' CHECK (kind IN ('store','office','warehouse','plant','customer_site','vehicle',
                                                       'other')),
  parent_id TEXT REFERENCES locations(id), address TEXT NOT NULL DEFAULT '{}', archived_at TEXT,
  created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, updated_at TEXT, updated_by_id TEXT);
CREATE TABLE items (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, sku TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL CHECK (kind IN ('service','inventory','non_inventory','bundle','category',
    'raw_material','assembly')),
  unit TEXT NOT NULL DEFAULT '', price BIGINT, currency TEXT NOT NULL DEFAULT '',
  income_account_id TEXT REFERENCES fin_accounts(id), expense_account_id TEXT REFERENCES fin_accounts(id),
  asset_account_id TEXT REFERENCES fin_accounts(id), archived_at TEXT,
  created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, updated_at TEXT, updated_by_id TEXT);
CREATE TABLE projects (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, customer_id TEXT REFERENCES entities(id),
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')), archived_at TEXT,
  created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, updated_at TEXT, updated_by_id TEXT);
CREATE TABLE record_aliases (
  table_name TEXT NOT NULL CHECK (table_name IN ('locations','items','projects')), alias_id TEXT NOT NULL,
  record_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (table_name, alias_id));
CREATE TABLE roadmap_actions(day TEXT NOT NULL,ip_hash TEXT NOT NULL,actions INTEGER NOT NULL,PRIMARY KEY(day,ip_hash));
CREATE TABLE worktree_waits(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, owner TEXT NOT NULL, repo TEXT NOT NULL, generation INTEGER NOT NULL, attempt_id TEXT, state TEXT NOT NULL, link_id TEXT, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE automations(id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL, group_id TEXT, trigger_type TEXT NOT NULL, enabled INTEGER NOT NULL, builtin INTEGER NOT NULL DEFAULT 0, flow TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, created_by_id TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, next_due_at TEXT, found_since TEXT);
CREATE TABLE automation_daily(automation_id TEXT NOT NULL, day TEXT NOT NULL, runs INTEGER NOT NULL DEFAULT 0, dropped INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(automation_id, day));
CREATE TABLE automation_mail_actions(id TEXT PRIMARY KEY, automation_id TEXT NOT NULL, run_id TEXT, mailbox TEXT NOT NULL, msg_id TEXT NOT NULL, action TEXT NOT NULL, args TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, claimed_at TEXT, claimed_by TEXT, result TEXT, attempts INTEGER NOT NULL DEFAULT 0, step TEXT, "after" TEXT);
CREATE TABLE automation_inboxes(inbox TEXT PRIMARY KEY, send INTEGER NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE automation_effects(key TEXT PRIMARY KEY, run_id TEXT NOT NULL, created_at TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE automation_turn_answers(run_id TEXT NOT NULL, ref TEXT NOT NULL, text TEXT NOT NULL, cost REAL NOT NULL, ok INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id, ref));
CREATE TABLE automation_holds(ref TEXT PRIMARY KEY, automation_id TEXT NOT NULL, run_id TEXT NOT NULL, amount REAL NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE redesign_migrated(kind TEXT NOT NULL, id TEXT NOT NULL, migration TEXT NOT NULL, automation TEXT, outcome TEXT, why TEXT, title TEXT, migrated_at TEXT, told TEXT, PRIMARY KEY(kind, id));
CREATE TABLE company_profile (id TEXT PRIMARY KEY CHECK (id = 'company'), vision TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', updated_at TEXT, updated_by TEXT);
CREATE TABLE strategy_versions (id TEXT PRIMARY KEY, n INTEGER UNIQUE, status TEXT NOT NULL CHECK (status IN ('draft','published')), guide TEXT NOT NULL DEFAULT 'default', summary TEXT NOT NULL DEFAULT '', vision TEXT NOT NULL DEFAULT '', sections TEXT NOT NULL DEFAULT '{}', bets TEXT NOT NULL DEFAULT '[]', note TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0, updated_at TEXT, updated_by TEXT, published_at TEXT, published_by TEXT);
CREATE TABLE strategy_bets (id TEXT PRIMARY KEY, statement TEXT NOT NULL, why TEXT NOT NULL DEFAULT '', rules_out TEXT NOT NULL DEFAULT '', wrong_if TEXT, cites TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL CHECK (status IN ('proposed','active','retired')), since_n INTEGER, until_n INTEGER, rank INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
CREATE TABLE org_rules(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('internal','external')), text TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source_entity_id TEXT, cite TEXT, who TEXT NOT NULL, with_scope TEXT NOT NULL DEFAULT '{}', where_terms TEXT NOT NULL DEFAULT '[]', if_broken TEXT NOT NULL DEFAULT 'block' CHECK (if_broken IN ('block','escalate','warn')), reviewer TEXT, status TEXT NOT NULL CHECK (status IN ('suggested','active','retired')), suggested_by TEXT NOT NULL, decided_by TEXT, decided_at TEXT, via TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, document_entity_id TEXT, toward_scope TEXT NOT NULL DEFAULT '[]', applies_when TEXT, party_side TEXT CHECK (party_side IN ('our_side', 'their_side')));
CREATE TABLE rule_due_dates(id TEXT PRIMARY KEY, rule_id TEXT NOT NULL, first_due_on TEXT NOT NULL, repeats TEXT NOT NULL CHECK (repeats IN ('once','weekly','monthly','quarterly','yearly')), timezone TEXT NOT NULL, owner TEXT NOT NULL, routine_id TEXT, replaces TEXT, ended_on TEXT, retired_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE rule_due_status(due_date_id TEXT NOT NULL, due_on TEXT NOT NULL, satisfied_by TEXT NOT NULL, via TEXT NOT NULL CHECK (via IN ('routine','person')), task_id TEXT, satisfied_at TEXT NOT NULL, PRIMARY KEY(due_date_id, due_on));
CREATE TABLE org_rule_verdicts(digest TEXT PRIMARY KEY, broken TEXT NOT NULL, call_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE rule_reads(
 task_id TEXT PRIMARY KEY, file_id TEXT NOT NULL, version INTEGER NOT NULL, requested_by TEXT NOT NULL,
 created_at TEXT NOT NULL, truncated INTEGER NOT NULL DEFAULT 0, source_id TEXT);
CREATE TABLE lens_runs (id TEXT PRIMARY KEY, lens TEXT NOT NULL, applies_to TEXT NOT NULL, on_draft INTEGER NOT NULL DEFAULT 0, strategy_n INTEGER, status TEXT NOT NULL, answers TEXT NOT NULL DEFAULT '{}', result TEXT, applied TEXT NOT NULL DEFAULT '[]', sharpen_tasks TEXT NOT NULL DEFAULT '{}', proposal_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, finished_at TEXT, error TEXT, claimed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE entity_watches (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL, url TEXT NOT NULL, kind TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_by TEXT, created_at TEXT, checked_at TEXT, changed_at TEXT, last_hash TEXT, last_text TEXT, last_status TEXT, error TEXT, signal_watch_id TEXT);
CREATE TABLE market_briefings (id TEXT PRIMARY KEY, week TEXT NOT NULL UNIQUE, title TEXT NOT NULL, body TEXT NOT NULL, items TEXT NOT NULL DEFAULT '[]', bets TEXT NOT NULL DEFAULT '[]', created_by TEXT, created_at TEXT, updated_at TEXT, answers TEXT, source TEXT);
CREATE TABLE market_turn_sources (event_id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL, subject_id TEXT NOT NULL, source TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE pages(
 file_id TEXT PRIMARY KEY REFERENCES bot_files(id),
 cadence TEXT NOT NULL DEFAULT 'none' CHECK(cadence IN ('none','daily','weekly','monthly')),
 as_of TEXT, replaced_by_id TEXT, audience TEXT, deleted_at TEXT, archived INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL, spec TEXT);
CREATE TABLE file_text_state(doc INTEGER PRIMARY KEY AUTOINCREMENT, file_id TEXT NOT NULL UNIQUE, version INTEGER NOT NULL, indexed_at TEXT NOT NULL);
CREATE TABLE file_deletions(file_id TEXT PRIMARY KEY, actor TEXT NOT NULL, versions INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE blob_purges(digest TEXT PRIMARY KEY, kind TEXT NOT NULL DEFAULT '', queued_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '');
CREATE VIRTUAL TABLE file_text USING fts5(title, text, tokenize='porter unicode61');
CREATE TABLE provenance_clock(id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
CREATE TABLE roster_clock(id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
CREATE TABLE row_clock(name TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE read_index(key TEXT PRIMARY KEY) WITHOUT ROWID;
CREATE TABLE read_deps(dep TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(dep, key)) WITHOUT ROWID;
CREATE TABLE read_dirty(key TEXT PRIMARY KEY) WITHOUT ROWID;
CREATE TABLE bot_config (
 bot TEXT PRIMARY KEY REFERENCES bots(id), team TEXT,
 owner_id TEXT NOT NULL, owner_ids TEXT, revision INTEGER NOT NULL DEFAULT 1,
 description TEXT NOT NULL DEFAULT '', reports_to TEXT, repo TEXT NOT NULL DEFAULT '',
 thread_mode TEXT, definition_updated_at TEXT,
 definition_updated_by TEXT, goals TEXT NOT NULL DEFAULT '', access TEXT, bot_owners TEXT, created_by TEXT, onboarding_state TEXT,
 CONSTRAINT status_values_onboarding_state CHECK (onboarding_state IN ('needs_setup', 'onboarded'))
);
CREATE TABLE automation_versions (automation_id TEXT NOT NULL, n INTEGER NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL, flow TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', summary TEXT, PRIMARY KEY(automation_id, n),
 CONSTRAINT status_values_status CHECK (status IN ('active', 'pending'))
);
CREATE TABLE bot_files (
 id TEXT PRIMARY KEY, bot_id TEXT NOT NULL REFERENCES bots(id), scope TEXT NOT NULL,
 identity TEXT NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL, mime TEXT NOT NULL DEFAULT '',
 locator TEXT NOT NULL, url TEXT, provider TEXT, current_version INTEGER NOT NULL DEFAULT 0,
 state TEXT NOT NULL DEFAULT 'ready', task_id TEXT, conversation_id TEXT,
 first_activity_at TEXT NOT NULL, last_activity_at TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0,
 UNIQUE(bot_id, scope, identity),
 CONSTRAINT status_values_state CHECK (state IN ('ready', 'deleted', 'not_synced'))
);
CREATE TABLE doc_sources (
 source_id TEXT PRIMARY KEY REFERENCES linked_docs(id), url TEXT NOT NULL,
 generation INTEGER NOT NULL DEFAULT 1, reference_override TEXT NOT NULL DEFAULT '',
 repo TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '',
 path TEXT NOT NULL DEFAULT '', active_snapshot TEXT, status TEXT NOT NULL DEFAULT 'link_only',
 last_checked_at TEXT, next_check_at REAL NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0,
 error_code TEXT NOT NULL DEFAULT '',
 CONSTRAINT status_values_status CHECK (status IN ('link_only', 'queued', 'preparing', 'updating', 'ready', 'empty', 'failed', 'access_needed'))
);
CREATE TABLE model_subscriptions (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, sealed TEXT NOT NULL,
 preview TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'new',
 status_detail TEXT NOT NULL DEFAULT '', status_at TEXT, added_by TEXT NOT NULL, created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL, owner_id TEXT NOT NULL DEFAULT '', credential_at TEXT, credential_id TEXT REFERENCES credentials(id),
 CONSTRAINT status_values_status CHECK (status IN ('new', 'working', 'needs_reconnect'))
);
CREATE TABLE google_workspaces (id TEXT PRIMARY KEY, domain TEXT NOT NULL, project_id TEXT NOT NULL DEFAULT '', client_email TEXT NOT NULL, client_id TEXT NOT NULL, key_id TEXT NOT NULL, key_sealed TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL, checked_at TEXT, connected_at TEXT, last_error TEXT, probe_mailbox TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, replaces_id TEXT, generation INTEGER NOT NULL DEFAULT 0, mint_failing_since TEXT, authorized_scopes TEXT,
 CONSTRAINT status_values_status CHECK (status IN ('pending', 'connected', 'failing'))
);
CREATE TABLE fin_cards (
  id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_card_id TEXT, holder TEXT NOT NULL,
  budget_id TEXT REFERENCES fin_budgets(id), money_account_id TEXT REFERENCES fin_money_accounts(id),
  kind TEXT NOT NULL CHECK (kind IN ('standing','single_use','person')), limit_amount BIGINT, limit_interval TEXT,
  currency TEXT NOT NULL, merchant_locks TEXT NOT NULL DEFAULT '[]', category_locks TEXT NOT NULL DEFAULT '[]',
  expires_at TEXT, status TEXT NOT NULL DEFAULT 'active', last4 TEXT,
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT, nickname TEXT NOT NULL DEFAULT '',
  provider_limit BIGINT, sync_status TEXT NOT NULL DEFAULT '', sync_error TEXT, synced_at TEXT, freeze_by TEXT, freeze_budget_id TEXT, merchant TEXT NOT NULL DEFAULT '', provider_status TEXT, allocation_due INTEGER,
 CONSTRAINT status_values_status CHECK (status IN ('active', 'frozen', 'canceled'))
);
CREATE TABLE fin_payments (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), action_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE, recipient_id TEXT NOT NULL REFERENCES fin_recipients(id),
  recipient_version INTEGER NOT NULL, money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id),
  amount BIGINT NOT NULL CHECK (amount > 0), currency TEXT NOT NULL,
  method TEXT NOT NULL CHECK (method IN ('ach','wire','check','rtp')), memo TEXT NOT NULL DEFAULT '',
  obligation TEXT NOT NULL DEFAULT '', account_id TEXT NOT NULL REFERENCES fin_accounts(id),
  tags TEXT NOT NULL DEFAULT '{}',
  mode TEXT NOT NULL DEFAULT 'approval_queue' CHECK (mode IN ('approval_queue','direct')),
  status TEXT NOT NULL DEFAULT 'queued',     -- the list is backend/status_values.py
  purpose TEXT NOT NULL DEFAULT '{}', counted TEXT NOT NULL DEFAULT '[]', unknown_since TEXT, flagged_at TEXT,
  provider_request_id TEXT, provider_txn_id TEXT, hold_id TEXT REFERENCES fin_holds(id), attempts INTEGER NOT NULL DEFAULT 0,
  next_try_at TEXT, last_error TEXT, settled_at TEXT, created_at TEXT NOT NULL, created_by TEXT NOT NULL,
  updated_at TEXT, cancel_asked_at TEXT, cancel_asked_by TEXT NOT NULL DEFAULT '',
 CONSTRAINT status_values_status CHECK (status IN ('queued', 'sending', 'awaiting_bank_approval', 'submitted', 'settled', 'returned', 'failed', 'canceled', 'unknown'))
);
CREATE TABLE fin_transfers (
  id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES fin_books(id), action_id TEXT NOT NULL,
  from_money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id),
  to_money_account_id TEXT NOT NULL REFERENCES fin_money_accounts(id),
  amount BIGINT NOT NULL CHECK (amount > 0), currency TEXT NOT NULL, memo TEXT NOT NULL DEFAULT '',
  idempotency_key TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'queued',     -- the list is backend/status_values.py
  provider_txn_id TEXT, provider_credit_txn_id TEXT, last_error TEXT, from_feed_id TEXT, to_feed_id TEXT,
  settled_at TEXT, submitted_at TEXT, find_after TEXT,
  counted TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL, created_by TEXT NOT NULL, updated_at TEXT,
  CHECK (from_money_account_id <> to_money_account_id),
 CONSTRAINT status_values_status CHECK (status IN ('queued', 'submitted', 'unknown', 'failed', 'posted', 'canceled'))
);
CREATE TABLE growth_line_uses (day TEXT NOT NULL, actor TEXT NOT NULL, use TEXT NOT NULL CHECK(use IN ('trace','source')), PRIMARY KEY (day, actor, use));
CREATE TABLE growth_alert_state (channel_id TEXT NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL, at TEXT NOT NULL, PRIMARY KEY (channel_id, kind));
CREATE TABLE growth_crossings (id TEXT PRIMARY KEY, channel_id TEXT NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL, value REAL, line TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', task_id TEXT, told TEXT NOT NULL CHECK (told IN ('task','comment','none')), actor TEXT, at TEXT NOT NULL);
CREATE TABLE growth_view_reads (day TEXT NOT NULL, actor TEXT NOT NULL, run_id TEXT NOT NULL DEFAULT '', view TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (day, actor, run_id, view));
CREATE TABLE tool_settings (
  id TEXT PRIMARY KEY,
  tool_id TEXT NOT NULL REFERENCES tools(id),
  name TEXT NOT NULL,
  value TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE calendar_watches (
  calendar_id TEXT PRIMARY KEY,
  mailbox TEXT NOT NULL,
  sync_token TEXT,
  page_token TEXT,
  list_mode TEXT,
  list_run TEXT,
  checked_at TEXT,
  check_error TEXT,
  watching_since_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE calendar_watch_events (
  id INTEGER PRIMARY KEY,
  calendar_id TEXT NOT NULL,
  event_id TEXT NOT NULL,
  series_id TEXT,
  sequence INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'confirmed' CHECK (status IN ('confirmed', 'cancelled')),
  repeats INTEGER NOT NULL DEFAULT 0,
  ends_at TEXT,
  listed_in TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE mail_unsubscribes (
  key TEXT PRIMARY KEY,
  mailbox TEXT NOT NULL,
  host TEXT NOT NULL,
  status TEXT NOT NULL,
  http_status INTEGER,
  actor TEXT NOT NULL,
  created_at TEXT NOT NULL,
  finished_at TEXT
);
CREATE TABLE mail_drafts (
  message_id TEXT PRIMARY KEY,
  mailbox TEXT NOT NULL,
  draft_id TEXT,
  message TEXT,
  thread TEXT,
  claimed_at TEXT NOT NULL
);
CREATE TABLE access_requests (
  id TEXT PRIMARY KEY,
  subject TEXT NOT NULL,
  resource_type TEXT NOT NULL CHECK (resource_type IN ('tool','repository')),
  resource_id TEXT NOT NULL,
  resource_name TEXT NOT NULL DEFAULT '',
  level TEXT NOT NULL CHECK (level IN ('read','read_write')),
  kind TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  requested_by TEXT NOT NULL,
  task_id TEXT,
  state TEXT NOT NULL DEFAULT 'open' CHECK (state IN ('open','granted','declined','withdrawn','revoked')),
  auto_approved INTEGER NOT NULL DEFAULT 0 CHECK (auto_approved IN (0, 1)),
  approvers TEXT NOT NULL DEFAULT '[]',
  cards TEXT NOT NULL DEFAULT '{}',
  repeats INTEGER NOT NULL DEFAULT 0,
  resolved_by TEXT,
  resolved_via TEXT,
  created_at TEXT NOT NULL,
  resolved_at TEXT
);
CREATE TABLE question_marks (
  id TEXT PRIMARY KEY,
  message_id TEXT NOT NULL,
  conversation_id TEXT NOT NULL,
  room_id TEXT NOT NULL,
  task_id TEXT NOT NULL DEFAULT '',
  bot_id TEXT NOT NULL,
  person_id TEXT NOT NULL,
  line TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  given_by_id TEXT,
  given_at TEXT,
  cleared_at TEXT,
  cleared_by_id TEXT,
  cleared_reason TEXT,
  cleared_message_id TEXT,
  cleared_via TEXT
);
CREATE TABLE task_documents (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  file_id TEXT NOT NULL REFERENCES bot_files(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(task_id, name)
);
CREATE TABLE oauth_refresh_claims(
 sign_in TEXT PRIMARY KEY, holder TEXT NOT NULL, claimed_until TEXT NOT NULL);
CREATE TABLE holds (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('paused','failing','runaway','claim_error','cant_start','quarantine','usage_limit')),
  holdable_type TEXT NOT NULL CHECK (holdable_type IN ('company','login','bot','task','conversation','job','automation')),
  holdable_id TEXT NOT NULL,
  bot_id TEXT REFERENCES bots(id),
  reason TEXT NOT NULL DEFAULT '',
  details TEXT NOT NULL DEFAULT '{}',
  streak INTEGER NOT NULL DEFAULT 0,
  until_at TEXT,
  probe_at TEXT, probe_job_id TEXT,
  upkeep_task_id TEXT,
  created_by_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  released_at TEXT, released_by_id TEXT,
  released_how TEXT CHECK (released_how IN ('expired','probe_passed','person','botops','raised','moot','superseded'))
);
CREATE TABLE slack_requests (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('history','file')),
  bot TEXT NOT NULL,
  params TEXT NOT NULL DEFAULT '{}',
  state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','running','done','failed')),
  result TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE old_questions (
    id TEXT PRIMARY KEY,
    visit_id TEXT NOT NULL,
    task_id TEXT NOT NULL,
    added_by_id TEXT,
    line TEXT NOT NULL DEFAULT '',
    choices TEXT,
    created_at TEXT NOT NULL
);
CREATE TABLE "requirements" (id TEXT PRIMARY KEY, stage_id TEXT REFERENCES stages(id), visit_id TEXT REFERENCES visits(id), kind TEXT NOT NULL CHECK (kind IN ('owner_done', 'ok', 'page', 'item', 'linked_done', 'related_input')), source TEXT, condition TEXT, settings TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(settings)), can_push_past INTEGER NOT NULL DEFAULT 1 CHECK (can_push_past IN (0, 1)), who_oks TEXT NOT NULL DEFAULT 'none' CHECK (who_oks IN ('none', 'people_only', 'people_with_exceptions')), person_id TEXT, added_by_id TEXT, by_bot INTEGER NOT NULL DEFAULT 0 CHECK (by_bot IN (0, 1)), line TEXT NOT NULL DEFAULT '', shows TEXT CHECK (shows IS NULL OR json_valid(shows)), position INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, withdrawn_at TEXT, CHECK ((stage_id IS NULL) <> (visit_id IS NULL)), CHECK ((kind = 'item') = (source IS NOT NULL AND condition IS NOT NULL)), CHECK (person_id IS NULL OR kind IN ('ok', 'page')));
CREATE TABLE page_links (
      id TEXT PRIMARY KEY,
      page_id TEXT NOT NULL REFERENCES bot_files(id) ON DELETE CASCADE,
      target TEXT NOT NULL,
      role TEXT NOT NULL,
      created_by TEXT NOT NULL,
      created_at TEXT NOT NULL,
      UNIQUE(page_id, target, role)
    );
CREATE TABLE claude_logins(
  subscription_id TEXT PRIMARY KEY,
  account TEXT NOT NULL DEFAULT '',
  access_expires_at TEXT,
  login_expires_at TEXT,
  refreshed_at TEXT,
  lease_id TEXT NOT NULL DEFAULT '',
  lease_runner TEXT NOT NULL DEFAULT '',
  lease_revision INTEGER NOT NULL DEFAULT 0,
  lease_until TEXT,
  failures INTEGER NOT NULL DEFAULT 0,
  retry_at TEXT,
  done_lease TEXT NOT NULL DEFAULT '',
  done_revision INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);
CREATE TABLE claude_login_leases(
  id TEXT PRIMARY KEY,
  subscription_id TEXT NOT NULL,
  runner_id TEXT NOT NULL,
  revision INTEGER NOT NULL,
  issued_at TEXT NOT NULL
);
CREATE TABLE claude_login_parks(
  job_id TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL,
  subscription_id TEXT NOT NULL,
  revision INTEGER NOT NULL,
  until TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE "visits" (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, stage_id TEXT NOT NULL REFERENCES stages(id), entered_at TEXT NOT NULL, entered_how TEXT NOT NULL CHECK (entered_how IN ('new', 'met', 'pushed_past', 'back', 'closed', 'reopened', 'moved', 'side')), left_at TEXT, how TEXT CHECK (how IS NULL OR how IN ('met', 'pushed_past', 'back', 'closed', 'reopened', 'moved', 'side')), by_id TEXT, why TEXT, tries INTEGER NOT NULL DEFAULT 0, level TEXT NOT NULL DEFAULT 'owner' CHECK (level IN ('owner', 'manager', 'person')), person_id TEXT, next_try_at TEXT, progress_mark TEXT, last_change_at TEXT, late_told_at TEXT, late_person_at TEXT, bot_snoozes INTEGER NOT NULL DEFAULT 0, last_change_attempt INTEGER, last_change_message INTEGER, last_change_start INTEGER, holder_id TEXT, pick_state TEXT CHECK (pick_state IS NULL OR pick_state IN ('full', 'nobody')), pick_why TEXT, CHECK ((left_at IS NULL) = (how IS NULL)));
CREATE TABLE google_connects (person_id TEXT PRIMARY KEY, mailbox TEXT NOT NULL, status TEXT NOT NULL, oauth_state TEXT, verifier TEXT, kind TEXT, message TEXT, hint TEXT, can TEXT, client_id TEXT, started_at REAL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, operation_id TEXT, answered TEXT, grant_scopes TEXT, grant_sealed TEXT, grant_operation_id TEXT,
 CONSTRAINT status_values_status CHECK (status IN ('signing_in', 'finishing', 'connected', 'disconnected', 'failed'))
);
