CREATE VIEW message_refs AS SELECT messages.*,
 CASE WHEN json_valid(refs,6) THEN CASE WHEN json_type(refs,'$.task')='array' THEN json_extract(refs,'$.task[0]')
  ELSE json_extract(refs,'$.task') END END AS ref_task_id,
 CASE WHEN json_valid(refs,6) THEN json_extract(refs,'$.wake') END AS ref_wake,
 CASE WHEN json_valid(refs,6) AND coalesce(json_extract(refs,'$.quiet'),0)<>0 THEN 1 ELSE 0 END AS ref_quiet,
 CASE WHEN json_valid(refs,6) AND coalesce(json_extract(refs,'$.command'),0)<>0 THEN 1 ELSE 0 END AS ref_command,
 CASE WHEN json_valid(refs,6) THEN json_extract(refs,'$.live.kind') END AS ref_live_kind
FROM messages;
CREATE VIEW runners_with_state AS SELECT r.*, s.last_seen_at AS last_seen_at, s.awake_since AS awake_since, s.version AS version, coalesce(s.capacity,4) AS capacity, coalesce(s.readiness,'{}') AS readiness, s.readiness_at AS readiness_at, coalesce(s.capabilities,'[]') AS capabilities, s.checkout AS checkout, s.restart_since AS restart_since, coalesce(s.memory_hold,0) AS memory_hold, s.last_sampled_at AS last_sampled_at FROM runners r LEFT JOIN runner_states s ON s.runner_id=r.id;
CREATE VIEW meeting_participant_readers AS
        SELECT m.id AS meeting_id, h.id AS human_id FROM meetings m CROSS JOIN humans h
        WHERE h.email<>'' AND CASE
          WHEN EXISTS (SELECT 1 FROM media_control mc WHERE mc.meeting_id=m.id AND mc.deleted_at IS NOT NULL) THEN 0
          WHEN lower(h.email)=lower(m.owner) THEN 1
          WHEN m.review_state<>'live' THEN 0
          WHEN coalesce(json_extract(m.metadata,'$.audience'),'')<>'participants' AND
            lower(h.email)=(SELECT lower(json_extract(value,'$.email')) FROM registry_metadata WHERE key='owner') THEN 1
          WHEN coalesce(json_extract(m.metadata,'$.kind'),'')<>'meeting' THEN 0
          WHEN json_extract(m.metadata,'$.audience')='participants' THEN
            EXISTS (SELECT 1 FROM json_each(m.metadata,'$.audience_emails') a WHERE lower(trim(a.value))=lower(h.email))
          WHEN NOT coalesce(json_extract(m.metadata,'$.private'),0) THEN 1
          WHEN EXISTS (SELECT 1 FROM json_each(m.metadata,'$.calendar.attendees') a WHERE lower(trim(a.value))=lower(h.email)) THEN 1
          ELSE EXISTS (SELECT 1 FROM json_each(m.metadata,'$.participants') a
            WHERE lower(trim(json_extract(CASE WHEN a.type='object' THEN a.value ELSE '{}' END,'$.email')))=lower(h.email)) END;
CREATE VIEW fin_contacts AS
SELECT b.id AS id, b.book_id AS book_id, COALESCE(NULLIF(b.name, ''), e.name) AS name, b.kind AS kind,
  b.emails AS emails,
  b.default_account_id AS default_account_id, b.is_1099 AS is_1099, b.tax_id_ref AS tax_id_ref,
  b.payment_ref AS payment_ref, b.active AS active, b.created_at AS created_at, b.created_by AS created_by,
  b.updated_at AS updated_at, b.tax_id_last4 AS tax_id_last4, b.seats AS seats, b.renewal_on AS renewal_on
FROM fin_book_entities b JOIN entities e ON e.id = b.entity_id;
CREATE VIEW fin_vendor_aliases AS
SELECT i.scope_id AS book_id, i.normalized_value AS name_key, i.entity_id AS contact_id, i.valid_from_on AS created_at,
  CASE WHEN i.source_type = 'finance_merge' THEN COALESCE(i.source_id, '') END AS merged_from
FROM entity_identifiers i WHERE i.scope_type = 'finance_book' AND i.kind = 'name';
CREATE TRIGGER status_values_webhook_sends_state_ins BEFORE INSERT ON webhook_sends WHEN NEW.state IS NULL OR NEW.state NOT IN ('ready', 'sending', 'delivered', 'failed', 'canceled', 'withheld') BEGIN SELECT RAISE(ABORT, 'webhook_sends.state: invalid value'); END;
CREATE TRIGGER status_values_webhook_sends_state_upd BEFORE UPDATE OF state ON webhook_sends WHEN NEW.state IS NULL OR NEW.state NOT IN ('ready', 'sending', 'delivered', 'failed', 'canceled', 'withheld') BEGIN SELECT RAISE(ABORT, 'webhook_sends.state: invalid value'); END;
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log
BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
CREATE TRIGGER bots_id_permanent BEFORE UPDATE OF id ON bots BEGIN
  SELECT RAISE(ABORT, 'a bot id never changes; rename the slug instead'); END;
CREATE TRIGGER bots_identity_insert BEFORE INSERT ON bots
WHEN EXISTS (SELECT 1 FROM bots WHERE id=NEW.slug) OR EXISTS (SELECT 1 FROM bots WHERE slug=NEW.id) BEGIN
  SELECT RAISE(ABORT, 'a bot slug cannot name another bot id, and a bot id cannot name another bot slug'); END;
CREATE TRIGGER bots_identity_slug BEFORE UPDATE OF slug ON bots
WHEN EXISTS (SELECT 1 FROM bots WHERE id=NEW.slug AND id<>OLD.id) BEGIN
  SELECT RAISE(ABORT, 'a bot slug cannot name another bot id'); END;
CREATE TRIGGER principals_human_insert AFTER INSERT ON humans BEGIN
  INSERT INTO principals(id, kind, deleted_at) VALUES('human:' || NEW.id, 'human', NULL)
  ON CONFLICT(id) DO UPDATE SET kind='human', deleted_at=NULL; END;
CREATE TRIGGER principals_human_delete AFTER DELETE ON humans BEGIN
  UPDATE principals SET deleted_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='human:' || OLD.id; END;
CREATE TRIGGER principals_bot_insert AFTER INSERT ON bots BEGIN
  INSERT INTO principals(id, kind, deleted_at) VALUES('bot:' || NEW.id, 'bot', NULL)
  ON CONFLICT(id) DO UPDATE SET kind='bot', deleted_at=NULL; END;
CREATE TRIGGER principals_bot_delete AFTER DELETE ON bots BEGIN
  UPDATE principals SET deleted_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='bot:' || OLD.id; END;
CREATE TRIGGER threads_conversations_stamp AFTER INSERT ON conversations WHEN NEW.root_id IS NULL BEGIN UPDATE conversations SET root_id=NEW.id, path='/'||NEW.id||'/', updated_at=COALESCE(NEW.updated_at,NEW.created_at) WHERE id=NEW.id; END;
CREATE TRIGGER threads_delivery_receipts AFTER UPDATE OF delivered_at, read_at ON messages BEGIN UPDATE message_deliveries SET delivered_at=NEW.delivered_at, read_at=NEW.read_at, state=CASE WHEN state IN ('capped','held','failed','moot') THEN state ELSE CASE WHEN NEW.delivered_at IS NOT NULL AND NEW.read_at IS NOT NULL THEN 'read' WHEN NEW.delivered_at IS NOT NULL THEN 'delivered' ELSE 'pending' END END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE message_id=NEW.id AND recipient=NEW.recipient_id;UPDATE message_deliveries SET delivered_at=NEW.delivered_at, state=CASE WHEN state='pending' AND NEW.delivered_at IS NOT NULL THEN 'delivered' ELSE state END, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE carrier_id=NEW.id; END;
CREATE TRIGGER threads_revisions_deleted AFTER UPDATE OF deleted_at ON messages WHEN NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL BEGIN UPDATE message_revisions SET body='' WHERE message_id=NEW.id; END;
CREATE TRIGGER message_search_insert AFTER INSERT ON messages BEGIN INSERT OR IGNORE INTO message_search_keys(message_id) SELECT NEW.id WHERE NEW.body IS NOT NULL AND NEW.body<>'' AND NEW.deleted_at IS NULL AND (CASE WHEN json_valid(NEW.refs) THEN json_extract(NEW.refs,'$.carries') END) IS NULL; INSERT INTO message_search(rowid, body, message_id) SELECT k.id, substr(NEW.body,1,20000), NEW.id FROM message_search_keys k WHERE k.message_id=NEW.id AND NEW.body IS NOT NULL AND NEW.body<>'' AND NEW.deleted_at IS NULL AND (CASE WHEN json_valid(NEW.refs) THEN json_extract(NEW.refs,'$.carries') END) IS NULL; END;
CREATE TRIGGER message_search_update AFTER UPDATE OF body, deleted_at, refs ON messages BEGIN DELETE FROM message_search WHERE rowid=(SELECT id FROM message_search_keys WHERE message_id=OLD.id); INSERT OR IGNORE INTO message_search_keys(message_id) SELECT NEW.id WHERE NEW.body IS NOT NULL AND NEW.body<>'' AND NEW.deleted_at IS NULL AND (CASE WHEN json_valid(NEW.refs) THEN json_extract(NEW.refs,'$.carries') END) IS NULL; INSERT INTO message_search(rowid, body, message_id) SELECT k.id, substr(NEW.body,1,20000), NEW.id FROM message_search_keys k WHERE k.message_id=NEW.id AND NEW.body IS NOT NULL AND NEW.body<>'' AND NEW.deleted_at IS NULL AND (CASE WHEN json_valid(NEW.refs) THEN json_extract(NEW.refs,'$.carries') END) IS NULL; END;
CREATE TRIGGER message_search_delete AFTER DELETE ON messages BEGIN DELETE FROM message_search WHERE rowid=(SELECT id FROM message_search_keys WHERE message_id=OLD.id); DELETE FROM message_search_keys WHERE message_id=OLD.id; END;
CREATE TRIGGER usage_facts_append_only_update BEFORE UPDATE ON usage_facts BEGIN SELECT RAISE(ABORT, 'usage_facts is append-only'); END;
CREATE TRIGGER usage_facts_append_only_delete BEFORE DELETE ON usage_facts BEGIN SELECT RAISE(ABORT, 'usage_facts is append-only'); END;
CREATE TRIGGER runner_states_new_runner AFTER INSERT ON runners BEGIN INSERT OR IGNORE INTO runner_states(runner_id) VALUES(NEW.id); END;
CREATE TRIGGER history_events_append_only BEFORE UPDATE ON history_events WHEN OLD.subject_type<>'task' BEGIN SELECT RAISE(ABORT, 'history_events is append-only'); END;
CREATE TRIGGER status_values_attempts_state_ins BEFORE INSERT ON attempts WHEN NEW.state IS NOT NULL AND NEW.state NOT IN ('leased', 'running', 'input', 'completed', 'failed', 'interrupted', 'expired') BEGIN SELECT RAISE(ABORT, 'attempts.state: invalid value'); END;
CREATE TRIGGER status_values_attempts_state_upd BEFORE UPDATE OF state ON attempts WHEN NEW.state IS NOT NULL AND NEW.state NOT IN ('leased', 'running', 'input', 'completed', 'failed', 'interrupted', 'expired') BEGIN SELECT RAISE(ABORT, 'attempts.state: invalid value'); END;
CREATE TRIGGER presences_meeting_delete BEFORE DELETE ON meetings BEGIN DELETE FROM presences WHERE place='meeting:'||OLD.id; DELETE FROM task_roles WHERE role='participant' AND task_id IN (SELECT result_ref FROM meeting_items WHERE meeting_id=OLD.id AND status='pushed' UNION SELECT t.id FROM tasks t JOIN live_meetings lm ON lm.id=t.live_meeting_id WHERE lm.imported_meeting_id=OLD.id UNION SELECT task_id FROM meeting_task_links WHERE meeting_id=OLD.id AND kind='sent'); END;
CREATE TRIGGER participants_live_delete BEFORE DELETE ON live_meetings BEGIN DELETE FROM task_roles WHERE role='participant' AND task_id IN (SELECT id FROM tasks WHERE live_meeting_id=OLD.id); END;
CREATE TRIGGER threads_primary_delivery AFTER INSERT ON messages WHEN COALESCE(NEW.recipient_id,'')<>'' AND NOT
    COALESCE(json_extract(CASE WHEN json_valid(NEW.refs) THEN NEW.refs END,'$.carries'),'')<>'' AND NOT
    (NEW.recipient_id LIKE 'human:%' AND ((NEW.sender_id='keeper' AND COALESCE(json_extract(CASE WHEN
    json_valid(NEW.refs) THEN NEW.refs END,'$.task'),'')<>'') OR ((NEW.sender_id LIKE 'bot:%' AND NEW.kind IN
    ('say','notice','ask') AND EXISTS (SELECT 1 FROM tasks t WHERE t.conversation_id=NEW.conversation_id)) AND
    COALESCE('addressed','') NOT IN ('mention','reply','follower')))) BEGIN INSERT OR IGNORE INTO
    message_deliveries(id,message_id,recipient,thread_id,root_id,mode,reason,cause,state,revision,delivered_at,read_at,created_at,updated_at,unsolicited)
    VALUES(lower(hex(randomblob(16))),NEW.id,NEW.recipient_id,NEW.conversation_id,(SELECT COALESCE(root_id,id) FROM
    conversations WHERE id=NEW.conversation_id),CASE WHEN NEW.recipient_id LIKE 'slack:%' OR NEW.recipient_id LIKE
    'peer:%' THEN 'none' WHEN COALESCE(json_extract(CASE WHEN json_valid(NEW.refs) THEN NEW.refs END,'$.quiet'),0)
    THEN 'defer' ELSE 'queue' END,CASE WHEN NEW.recipient_id LIKE 'slack:%' OR NEW.recipient_id LIKE 'peer:%' THEN
    'outside' WHEN NEW.kind='ask' THEN 'ask' ELSE 'addressed' END,CASE WHEN NEW.sender_id LIKE 'bot:%' THEN 'bot' WHEN
    NEW.sender_id LIKE 'human:%' THEN 'human' WHEN NEW.sender_id LIKE 'slack:%' OR NEW.sender_id LIKE 'peer:%' THEN
    'outside' ELSE 'keeper' END,CASE WHEN NEW.delivered_at IS NOT NULL AND NEW.read_at IS NOT NULL THEN 'read' WHEN
    NEW.delivered_at IS NOT NULL THEN 'delivered' ELSE 'pending'
    END,COALESCE(NEW.revision,0),NEW.delivered_at,NEW.read_at,NEW.created_at,NEW.created_at,COALESCE(json_extract(CASE
    WHEN json_valid(NEW.refs) THEN NEW.refs END,'$.unsolicited'),0)); END;
CREATE TRIGGER entities_identifiers_ad AFTER DELETE ON entities BEGIN DELETE FROM entity_identifiers WHERE entity_id = old.id; END;
CREATE TRIGGER entities_fts_ai AFTER INSERT ON entities BEGIN
  INSERT INTO market_fts(rowid, kind, ref, name, aliases, summary, quote, our_read)
  VALUES (new.seq, 'entity', new.id, new.name, new.aliases, new.summary, '', ''); END;
CREATE TRIGGER entities_fts_ad AFTER DELETE ON entities BEGIN
  DELETE FROM market_fts WHERE rowid = old.seq; END;
CREATE TRIGGER entities_fts_au AFTER UPDATE OF name, aliases, summary ON entities BEGIN
  DELETE FROM market_fts WHERE rowid = old.seq;
  INSERT INTO market_fts(rowid, kind, ref, name, aliases, summary, quote, our_read)
  VALUES (new.seq, 'entity', new.id, new.name, new.aliases, new.summary, '', ''); END;
CREATE TRIGGER market_evidence_ai AFTER INSERT ON market_evidence BEGIN
  INSERT INTO market_fts(rowid, kind, ref, name, aliases, summary, quote, our_read)
  VALUES (new.fts_rowid, 'evidence', new.id, '', '', '', new.quote, new.our_read); END;
CREATE TRIGGER market_evidence_ad AFTER DELETE ON market_evidence BEGIN
  DELETE FROM market_fts WHERE rowid = old.fts_rowid; END;
CREATE TRIGGER market_evidence_au AFTER UPDATE OF quote, our_read ON market_evidence BEGIN
  DELETE FROM market_fts WHERE rowid = old.fts_rowid;
  INSERT INTO market_fts(rowid, kind, ref, name, aliases, summary, quote, our_read)
  VALUES (new.fts_rowid, 'evidence', new.id, '', '', '', new.quote, new.our_read); END;
CREATE TRIGGER entities_identifiers_ai AFTER INSERT ON entities BEGIN INSERT INTO entity_identifiers (entity_id, kind, value, normalized_value, primary_identifier, derived) SELECT new.id, kind, key, key, prim, 1 FROM (SELECT key, MIN(kind) AS kind, MAX(prim) AS prim FROM (
    SELECT lower(trim(new.name)) AS key, CASE WHEN lower(trim(new.name)) LIKE 'http://%' OR lower(trim(new.name)) LIKE 'https://%' THEN 'url' WHEN instr(lower(trim(new.name)), '@') > 1 AND instr(lower(trim(new.name)), ' ') = 0 THEN 'email' WHEN lower(trim(new.name)) GLOB '+[0-9]*' AND lower(trim(new.name)) NOT GLOB '*[^0-9+() .-]*' THEN 'phone' WHEN instr(lower(trim(new.name)), '.') > 0 AND instr(lower(trim(new.name)), ' ') = 0 AND lower(trim(new.name)) NOT GLOB '*[^a-z0-9.-]*' THEN 'domain' ELSE 'name' END AS kind, 1 AS prim
    UNION ALL SELECT CASE WHEN json_valid(new.external_ids) THEN lower(trim(json_extract(new.external_ids, '$.domain'))) END, 'domain', 1
    UNION ALL SELECT lower(trim(j.value)), CASE WHEN lower(trim(j.value)) LIKE 'http://%' OR lower(trim(j.value)) LIKE 'https://%' THEN 'url' WHEN instr(lower(trim(j.value)), '@') > 1 AND instr(lower(trim(j.value)), ' ') = 0 THEN 'email' WHEN lower(trim(j.value)) GLOB '+[0-9]*' AND lower(trim(j.value)) NOT GLOB '*[^0-9+() .-]*' THEN 'phone' WHEN instr(lower(trim(j.value)), '.') > 0 AND instr(lower(trim(j.value)), ' ') = 0 AND lower(trim(j.value)) NOT GLOB '*[^a-z0-9.-]*' THEN 'domain' ELSE 'name' END, 0
      FROM json_each(CASE WHEN json_valid(new.aliases) THEN new.aliases ELSE '[]' END) j
  ) WHERE key IS NOT NULL AND key <> '' GROUP BY key) ORDER BY key; END;
CREATE TRIGGER entities_identifiers_au AFTER UPDATE OF name, aliases, external_ids ON entities BEGIN DELETE FROM entity_identifiers WHERE entity_id = old.id AND derived = 1; INSERT INTO entity_identifiers (entity_id, kind, value, normalized_value, primary_identifier, derived) SELECT new.id, kind, key, key, prim, 1 FROM (SELECT key, MIN(kind) AS kind, MAX(prim) AS prim FROM (
    SELECT lower(trim(new.name)) AS key, CASE WHEN lower(trim(new.name)) LIKE 'http://%' OR lower(trim(new.name)) LIKE 'https://%' THEN 'url' WHEN instr(lower(trim(new.name)), '@') > 1 AND instr(lower(trim(new.name)), ' ') = 0 THEN 'email' WHEN lower(trim(new.name)) GLOB '+[0-9]*' AND lower(trim(new.name)) NOT GLOB '*[^0-9+() .-]*' THEN 'phone' WHEN instr(lower(trim(new.name)), '.') > 0 AND instr(lower(trim(new.name)), ' ') = 0 AND lower(trim(new.name)) NOT GLOB '*[^a-z0-9.-]*' THEN 'domain' ELSE 'name' END AS kind, 1 AS prim
    UNION ALL SELECT CASE WHEN json_valid(new.external_ids) THEN lower(trim(json_extract(new.external_ids, '$.domain'))) END, 'domain', 1
    UNION ALL SELECT lower(trim(j.value)), CASE WHEN lower(trim(j.value)) LIKE 'http://%' OR lower(trim(j.value)) LIKE 'https://%' THEN 'url' WHEN instr(lower(trim(j.value)), '@') > 1 AND instr(lower(trim(j.value)), ' ') = 0 THEN 'email' WHEN lower(trim(j.value)) GLOB '+[0-9]*' AND lower(trim(j.value)) NOT GLOB '*[^0-9+() .-]*' THEN 'phone' WHEN instr(lower(trim(j.value)), '.') > 0 AND instr(lower(trim(j.value)), ' ') = 0 AND lower(trim(j.value)) NOT GLOB '*[^a-z0-9.-]*' THEN 'domain' ELSE 'name' END, 0
      FROM json_each(CASE WHEN json_valid(new.aliases) THEN new.aliases ELSE '[]' END) j
  ) WHERE key IS NOT NULL AND key <> '' GROUP BY key) ORDER BY key; END;
CREATE TRIGGER history_events_no_delete BEFORE DELETE ON history_events
WHEN OLD.subject_type<>'task' BEGIN
  SELECT RAISE(ABORT, 'history_events is append-only') WHERE NOT (
    (OLD.subject_type = 'market_entity' AND NOT EXISTS (SELECT 1 FROM entities WHERE id = OLD.subject_id))
    OR (OLD.subject_type = 'market_edge' AND NOT EXISTS (SELECT 1 FROM entity_links WHERE id = OLD.subject_id))
  );
END;
CREATE TRIGGER tasks_body_work_revision AFTER UPDATE OF body ON tasks WHEN NEW.body IS NOT OLD.body BEGIN UPDATE tasks SET work_revision = work_revision + 1 WHERE id = NEW.id; END;
CREATE TRIGGER tasks_move_only BEFORE UPDATE OF status, stage_id, owner_id, pipeline_id ON tasks WHEN (SELECT task_id FROM task_move_guards WHERE id = 1 AND open = 1) IS NOT NEW.id BEGIN SELECT RAISE(ABORT, 'tasks: stage, owner and status change only through move()'); END;
CREATE TRIGGER tasks_enter_only BEFORE INSERT ON tasks WHEN NEW.pipeline_id IS NOT NULL OR NEW.stage_id IS NOT NULL OR NEW.status IS NOT 'open' BEGIN SELECT RAISE(ABORT, 'tasks: a new task starts open, in no stage; enter() places it'); END;
CREATE TRIGGER tasks_never_replaced BEFORE INSERT ON tasks WHEN EXISTS (SELECT 1 FROM tasks WHERE id = NEW.id) OR (NEW.number IS NOT NULL AND EXISTS (SELECT 1 FROM tasks WHERE number = NEW.number)) BEGIN SELECT RAISE(ABORT, 'tasks: a task is never replaced'); END;
CREATE TRIGGER visits_change_marks_on_open AFTER INSERT ON visits BEGIN UPDATE visits SET last_change_attempt = (SELECT COALESCE(MAX(rowid), 0) FROM attempts), last_change_message = (SELECT COALESCE(MAX(rowid), 0) FROM messages), last_change_start = (SELECT COALESCE(MAX(id), 0) FROM run_starts) WHERE id = NEW.id; END;
CREATE TRIGGER visits_change_marks_on_change AFTER UPDATE OF last_change_at ON visits BEGIN UPDATE visits SET last_change_attempt = (SELECT COALESCE(MAX(rowid), 0) FROM attempts), last_change_message = (SELECT COALESCE(MAX(rowid), 0) FROM messages), last_change_start = (SELECT COALESCE(MAX(id), 0) FROM run_starts) WHERE id = NEW.id; END;
CREATE TRIGGER calendar_event_search_insert AFTER INSERT ON calendar_events BEGIN
  INSERT OR IGNORE INTO calendar_event_search_keys(calendar_event_id) VALUES (NEW.id);
  INSERT INTO calendar_event_search(rowid, title, notes, location)
    SELECT k.id, NEW.title, coalesce(NEW.notes, ''), coalesce(NEW.location, '')
    FROM calendar_event_search_keys k WHERE k.calendar_event_id = NEW.id;
END;
CREATE TRIGGER calendar_event_search_update AFTER UPDATE OF title, notes, location ON calendar_events
BEGIN
  DELETE FROM calendar_event_search
    WHERE rowid = (SELECT id FROM calendar_event_search_keys WHERE calendar_event_id = OLD.id);
  INSERT INTO calendar_event_search(rowid, title, notes, location)
    SELECT k.id, NEW.title, coalesce(NEW.notes, ''), coalesce(NEW.location, '')
    FROM calendar_event_search_keys k WHERE k.calendar_event_id = NEW.id;
END;
CREATE TRIGGER calendar_event_search_delete AFTER DELETE ON calendar_events BEGIN
  DELETE FROM calendar_event_search
    WHERE rowid = (SELECT id FROM calendar_event_search_keys WHERE calendar_event_id = OLD.id);
  DELETE FROM calendar_event_search_keys WHERE calendar_event_id = OLD.id;
END;
CREATE TRIGGER attempt_event_briefs_rewritten AFTER UPDATE OF payload ON attempt_events BEGIN DELETE FROM attempt_event_briefs WHERE attempt_id=OLD.attempt_id AND seq=OLD.seq; END;
CREATE TRIGGER attempt_event_briefs_deleted AFTER DELETE ON attempt_events BEGIN DELETE FROM attempt_event_briefs WHERE attempt_id=OLD.attempt_id AND seq=OLD.seq; END;
CREATE TRIGGER message_links_insert AFTER INSERT ON messages BEGIN INSERT OR IGNORE INTO message_links_dirty VALUES(NEW.id); END;
CREATE TRIGGER message_links_update AFTER UPDATE OF id, refs, in_reply_to ON messages BEGIN INSERT OR IGNORE INTO message_links_dirty VALUES(NEW.id); END;
CREATE TRIGGER message_links_delete AFTER DELETE ON messages BEGIN DELETE FROM message_links WHERE message_id=OLD.id; DELETE FROM message_links_dirty WHERE message_id=OLD.id; DELETE FROM message_links_seen WHERE message_id=OLD.id; END;
CREATE TRIGGER bot_file_activity_append_only BEFORE UPDATE ON bot_file_activity
 BEGIN SELECT RAISE(ABORT, 'bot_file_activity is append-only'); END;
CREATE TRIGGER bot_file_activity_no_delete BEFORE DELETE ON bot_file_activity
 BEGIN SELECT RAISE(ABORT, 'bot_file_activity is append-only'); END;
CREATE TRIGGER external_sections_insert AFTER INSERT ON external_sections BEGIN
 INSERT INTO external_sections_fts(rowid,title,path,heading,body) VALUES(new.id,new.title,new.path,new.heading,new.body);
END;
CREATE TRIGGER external_sections_delete AFTER DELETE ON external_sections BEGIN
