  UPDATE bot_browser_exits SET generation=generation+1 WHERE bot=NEW.bot; END;
CREATE TRIGGER bot_browser_exit_moved AFTER UPDATE OF runner_id ON assignments
  WHEN OLD.runner_id IS NOT NEW.runner_id BEGIN
  UPDATE bot_browser_exits SET generation=generation+1 WHERE bot=NEW.bot; END;
CREATE TRIGGER bot_browser_exit_unassigned AFTER DELETE ON assignments BEGIN
  UPDATE bot_browser_exits SET generation=generation+1 WHERE bot=OLD.bot; END;
CREATE TRIGGER browser_exit_computer_removed AFTER UPDATE OF revoked_at ON runners
  WHEN OLD.revoked_at IS NOT NEW.revoked_at BEGIN
  UPDATE browser_exits SET generation=generation+1 WHERE runner_id=NEW.id; END;
CREATE TRIGGER bot_browser_exit_computer_removed AFTER UPDATE OF revoked_at ON runners
  WHEN OLD.revoked_at IS NOT NEW.revoked_at BEGIN
  UPDATE bot_browser_exits SET generation=generation+1
    WHERE bot IN (SELECT bot FROM assignments WHERE runner_id=NEW.id); END;
CREATE TRIGGER idempotency_messages_insert AFTER INSERT ON idempotency WHEN NEW.binding IS NULL AND (instr(NEW.response, '"sender_id"')>0 OR instr(NEW.response, '"from_actor"')>0 OR NOT json_valid(NEW.response)) BEGIN INSERT OR IGNORE INTO idempotency_messages SELECT id, actor, operation, key FROM (SELECT NEW.actor AS actor, NEW.operation AS operation, NEW.key AS key, max(CASE WHEN t.key='id' AND t.type='text' THEN t.value END) AS id, max(t.key IN ('sender_id','from_actor')) AS sender FROM json_tree(CASE WHEN json_valid(NEW.response) THEN NEW.response ELSE 'null' END) t WHERE t.key IN ('id','sender_id','from_actor') GROUP BY t.parent) WHERE sender AND id IS NOT NULL UNION SELECT '*', NEW.actor, NEW.operation, NEW.key WHERE NOT json_valid(NEW.response); END;
CREATE TRIGGER idempotency_messages_update AFTER UPDATE ON idempotency BEGIN DELETE FROM idempotency_messages WHERE actor=OLD.actor AND operation=OLD.operation AND key=OLD.key; INSERT OR IGNORE INTO idempotency_messages SELECT id, actor, operation, key FROM (SELECT NEW.actor AS actor, NEW.operation AS operation, NEW.key AS key, max(CASE WHEN t.key='id' AND t.type='text' THEN t.value END) AS id, max(t.key IN ('sender_id','from_actor')) AS sender FROM json_tree(CASE WHEN json_valid(NEW.response) THEN NEW.response ELSE 'null' END) t WHERE t.key IN ('id','sender_id','from_actor') GROUP BY t.parent) WHERE sender AND id IS NOT NULL UNION SELECT '*', NEW.actor, NEW.operation, NEW.key WHERE NOT json_valid(NEW.response); END;
CREATE TRIGGER idempotency_messages_delete AFTER DELETE ON idempotency BEGIN DELETE FROM idempotency_messages WHERE actor=OLD.actor AND operation=OLD.operation AND key=OLD.key; END;
CREATE TRIGGER bot_file_versions_immutable BEFORE UPDATE OF
 file_id,version,blob_id,digest,source_digest,size,name,mime,commit_sha,repo_path,attempt_id,actor,created_at
 ON bot_file_versions BEGIN SELECT RAISE(ABORT, 'file versions are immutable'); END;
CREATE TRIGGER fin_lines_no_update BEFORE UPDATE ON fin_lines
BEGIN SELECT RAISE(ABORT, 'fin_lines are immutable: post a reversing entry'); END;
CREATE TRIGGER fin_lines_no_delete BEFORE DELETE ON fin_lines
BEGIN SELECT RAISE(ABORT, 'fin_lines are immutable: post a reversing entry'); END;
CREATE TRIGGER fin_entries_no_delete BEFORE DELETE ON fin_entries
BEGIN SELECT RAISE(ABORT, 'fin_entries are immutable: post a reversing entry'); END;
CREATE TRIGGER fin_entries_only_reverse BEFORE UPDATE ON fin_entries
WHEN NOT (OLD.status = 'posted' AND NEW.status = 'reversed' AND NEW.id = OLD.id AND NEW.book_id = OLD.book_id
          AND NEW.entry_date = OLD.entry_date AND NEW.memo = OLD.memo AND NEW.source = OLD.source
          AND NEW.source_id = OLD.source_id AND NEW.reverses_id IS OLD.reverses_id AND NEW.period_id IS OLD.period_id
          AND NEW.action_id IS OLD.action_id AND NEW.created_at = OLD.created_at AND NEW.created_by = OLD.created_by)
BEGIN SELECT RAISE(ABORT, 'fin_entries are immutable: only posted -> reversed may change'); END;
CREATE TRIGGER fin_entries_open_period BEFORE INSERT ON fin_entries
WHEN EXISTS (SELECT 1 FROM fin_periods p WHERE p.book_id = NEW.book_id AND p.status = 'closed'
             AND NEW.entry_date BETWEEN p.start_date AND p.end_date)
BEGIN SELECT RAISE(ABORT, 'period closed'); END;
CREATE TRIGGER fin_lines_open_period BEFORE INSERT ON fin_lines
WHEN EXISTS (SELECT 1 FROM fin_periods p WHERE p.book_id = NEW.book_id AND p.status = 'closed'
             AND NEW.entry_date BETWEEN p.start_date AND p.end_date)
BEGIN SELECT RAISE(ABORT, 'period closed'); END;
CREATE TRIGGER fin_view_roster_insert AFTER INSERT ON registry_metadata WHEN NEW.key = 'people' BEGIN UPDATE fin_view_versions SET version=version+1, reason='roster', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER fin_view_roster_update AFTER UPDATE OF value ON registry_metadata WHEN NEW.key = 'people' AND OLD.value IS NOT NEW.value BEGIN UPDATE fin_view_versions SET version=version+1, reason='roster', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER fin_view_bot_settings_insert AFTER INSERT ON bot_settings BEGIN UPDATE fin_view_versions SET version=version+1, reason='reports to', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER fin_view_bot_settings_update AFTER UPDATE OF extra ON bot_settings WHEN CASE WHEN json_valid(OLD.extra) AND json_valid(NEW.extra) THEN json_extract(OLD.extra, '$.team') IS NOT json_extract(NEW.extra, '$.team') OR json_extract(OLD.extra, '$.reports_to') IS NOT json_extract(NEW.extra, '$.reports_to') ELSE OLD.extra IS NOT NEW.extra END BEGIN UPDATE fin_view_versions SET version=version+1, reason='reports to', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER fin_view_bot_archive AFTER UPDATE OF state ON bots WHEN (OLD.state = 'archived') IS NOT (NEW.state = 'archived') BEGIN UPDATE fin_view_versions SET version=version+1, reason='bot archived', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=1; END;
CREATE TRIGGER bot_file_versions_no_delete BEFORE DELETE ON bot_file_versions WHEN NOT EXISTS (SELECT 1 FROM file_deletions WHERE file_id=OLD.file_id) BEGIN SELECT RAISE(ABORT, 'file versions are immutable'); END;
CREATE TRIGGER wake_preset_hold AFTER INSERT ON jobs WHEN NEW.state='queued' BEGIN
 UPDATE jobs SET held=1,
   wake_class=(SELECT CASE WHEN json_extract(m.refs,'$.wake_batch') IN ('completion','review','ci','rule') THEN json_extract(m.refs,'$.wake_batch') ELSE CASE WHEN json_extract(m.refs,'$.release_kind') IN ('routine','dream') THEN json_extract(m.refs,'$.release_kind') ELSE 'routine' END END
     FROM messages m WHERE m.id=NEW.message_id),
   release=(SELECT CASE WHEN json_extract(m.refs,'$.wake_batch') IN ('completion','review','ci','rule') THEN NULL ELSE json_extract(m.refs,'$.release') END
     FROM messages m WHERE m.id=NEW.message_id)
   WHERE id=NEW.id AND EXISTS(SELECT 1 FROM messages m WHERE m.id=NEW.message_id
   AND m.sender_id='keeper' AND coalesce(json_extract(m.refs,'$.wake_immediate'),0)<>1
   AND (json_extract(m.refs,'$.wake_batch') IN ('completion','review','ci','rule') OR json_type(m.refs,'$.release')='object'));
 UPDATE jobs SET state='canceled',held=0,wake_class='duplicate' WHERE id=NEW.id AND (EXISTS(SELECT 1 FROM messages m JOIN messages om ON m.sender_id='keeper' AND om.conversation_id=m.conversation_id AND om.rowid<m.rowid
   JOIN jobs o ON o.message_id=om.id AND o.bot_id=NEW.bot_id AND o.id<>NEW.id
   AND (o.state<>'canceled' OR o.wake_carrier IS NOT NULL)
   LEFT JOIN jobs cj ON cj.id=o.wake_carrier LEFT JOIN attempts a ON a.id=coalesce(cj.attempt_id,o.attempt_id)
   WHERE m.id=NEW.message_id AND om.sender_id IS m.sender_id AND om.kind IS m.kind AND om.body=m.body AND om.refs IS m.refs AND om.in_reply_to IS m.in_reply_to AND (coalesce(cj.state,o.state) IN ('queued','leased','running','input')
   OR a.finished_at>=strftime('%Y-%m-%dT%H:%M:%fZ',m.created_at,'-120 seconds'))) OR EXISTS(SELECT 1 FROM messages m JOIN messages om ON om.rowid=(SELECT max(x.rowid) FROM messages x WHERE x.conversation_id=m.conversation_id AND x.rowid<m.rowid)
   JOIN jobs o ON o.message_id=om.id AND o.bot_id=NEW.bot_id AND o.id<>NEW.id
   AND (o.state<>'canceled' OR o.wake_carrier IS NOT NULL)
   LEFT JOIN jobs cj ON cj.id=o.wake_carrier LEFT JOIN attempts a ON a.id=coalesce(cj.attempt_id,o.attempt_id)
   WHERE m.id=NEW.message_id AND om.sender_id IS m.sender_id AND om.kind IS m.kind AND om.body=m.body AND om.refs IS m.refs AND om.in_reply_to IS m.in_reply_to AND (coalesce(cj.state,o.state) IN ('queued','leased','running','input')
   OR a.finished_at>=strftime('%Y-%m-%dT%H:%M:%fZ',m.created_at,'-120 seconds'))));
END;
