CREATE TRIGGER changes_tasks_insert AFTER INSERT ON tasks BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'tasks','insert',NEW.id,NULL,NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'needs','task',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.owner_id AS who UNION SELECT NEW.requester_id AS who UNION SELECT value AS who FROM json_each(CASE WHEN json_valid(NEW.readers) THEN NEW.readers END)) WHERE who LIKE 'human:%'; END;
CREATE TRIGGER changes_tasks_update AFTER UPDATE ON tasks BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'tasks','update',NEW.id,CASE WHEN OLD.owner_id IS NOT NEW.owner_id OR OLD.requester_id IS NOT NEW.requester_id OR OLD.private IS NOT NEW.private OR OLD.readers IS NOT NEW.readers OR OLD.pipeline_id IS NOT NEW.pipeline_id OR OLD.status IS NOT NEW.status THEN json_array(OLD.owner_id,OLD.requester_id,OLD.private,OLD.readers,OLD.pipeline_id,OLD.status) END,NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'needs','task',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT OLD.owner_id AS who UNION SELECT OLD.requester_id AS who UNION SELECT NEW.owner_id AS who UNION SELECT NEW.requester_id AS who UNION SELECT value AS who FROM json_each(CASE WHEN json_valid(OLD.readers) THEN OLD.readers END) UNION SELECT value AS who FROM json_each(CASE WHEN json_valid(NEW.readers) THEN NEW.readers END)) WHERE who LIKE 'human:%'; END;
CREATE TRIGGER changes_tasks_delete AFTER DELETE ON tasks BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'tasks','delete',OLD.id,json_array(OLD.owner_id,OLD.requester_id,OLD.private,OLD.readers,OLD.pipeline_id,OLD.status),NULL,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'needs','task',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT OLD.owner_id AS who UNION SELECT OLD.requester_id AS who UNION SELECT value AS who FROM json_each(CASE WHEN json_valid(OLD.readers) THEN OLD.readers END)) WHERE who LIKE 'human:%'; END;
