CREATE TRIGGER changes_tags_update AFTER UPDATE ON tags BEGIN INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'tasks','tags',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT task_id AS id FROM task_tags WHERE tag_id=NEW.id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_tags WHERE tag_id=NEW.id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,created_at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_tags WHERE tag_id=NEW.id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
