CREATE TRIGGER changes_blob_media_insert AFTER INSERT ON blob_media WHEN NEW.width IS NOT NULL OR NEW.height IS NOT NULL OR NEW.thumb_blob_id IS NOT NULL OR NEW.poster_blob_id IS NOT NULL BEGIN INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'tasks','files',id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) WHERE NOT (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) LIMIT 101))>100;INSERT INTO changes(topic,kind,created_at) SELECT 'tasks','bulk',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (SELECT count(*) FROM (SELECT 1 FROM (SELECT id FROM (SELECT task_id AS id FROM task_assets WHERE blob_id=NEW.blob_id UNION SELECT f.task_id FROM bot_file_versions v JOIN bot_files f ON f.id=v.file_id WHERE v.blob_id=NEW.blob_id) WHERE id IS NOT NULL) LIMIT 101))>100; END;
