CREATE TRIGGER changes_messages_insert AFTER INSERT ON messages BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'messages','insert',NEW.id,NULL,NEW.conversation_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','activity',NEW.conversation_id,NEW.id,NEW.conversation_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.conversation_id IS NOT NULL AND COALESCE(json_extract(CASE WHEN json_valid(NEW.refs) THEN NEW.refs END,'$.carries'),'')=''; END;
CREATE TRIGGER changes_messages_update AFTER UPDATE ON messages WHEN OLD.body IS NOT NEW.body OR OLD.refs IS NOT NEW.refs OR OLD.kind IS NOT NEW.kind OR OLD.answered_by_id IS NOT NEW.answered_by_id OR OLD.edited_at IS NOT NEW.edited_at OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.conversation_id IS NOT NEW.conversation_id OR OLD.superseded_at IS NOT NEW.superseded_at BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'messages','update',NEW.id,NULL,NEW.conversation_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','activity',NEW.conversation_id,NEW.id,NEW.conversation_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (OLD.deleted_at IS NOT NEW.deleted_at) AND NEW.conversation_id IS NOT NULL AND COALESCE(json_extract(CASE WHEN json_valid(NEW.refs) THEN NEW.refs END,'$.carries'),'')=''; END;
CREATE TRIGGER changes_messages_delete AFTER DELETE ON messages BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'messages','delete',OLD.id,NULL,OLD.conversation_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_message_deliveries_insert AFTER INSERT ON message_deliveries WHEN NEW.mode<>'none' BEGIN INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'needs','thread',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.recipient AS who) WHERE who LIKE 'human:%'; END;
CREATE TRIGGER changes_message_deliveries_update AFTER UPDATE ON message_deliveries WHEN NEW.mode<>'none' AND OLD.state IS NOT NEW.state BEGIN INSERT INTO changes(topic,kind,subject_id,created_at) SELECT 'needs','thread',who,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.recipient AS who) WHERE who LIKE 'human:%'; END;
