CREATE TRIGGER changes_attempt_events_insert AFTER INSERT ON attempt_events BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'runs','output',NEW.attempt_id,NEW.id,(SELECT m.conversation_id FROM attempts a JOIN jobs j ON j.id=a.job_id JOIN messages m ON m.id=j.message_id WHERE a.id=NEW.attempt_id),(SELECT bot_id FROM attempts WHERE id=NEW.attempt_id),strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'bots','status',(SELECT bot_id FROM attempts WHERE id=NEW.attempt_id),NULL,NULL,(SELECT bot_id FROM attempts WHERE id=NEW.attempt_id),strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.kind='status' AND json_type(NEW.payload,'$.waiting') IS NOT NULL; END;
CREATE TRIGGER changes_attempts_insert AFTER INSERT ON attempts BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'runs','attempt',NEW.id,NULL,(SELECT m.conversation_id FROM attempts a JOIN jobs j ON j.id=a.job_id JOIN messages m ON m.id=j.message_id WHERE a.id=NEW.id),NEW.bot_id,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_attempts_update AFTER UPDATE ON attempts WHEN OLD.state IS NOT NEW.state BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'runs','attempt',NEW.id,NULL,(SELECT m.conversation_id FROM attempts a JOIN jobs j ON j.id=a.job_id JOIN messages m ON m.id=j.message_id WHERE a.id=NEW.id),NEW.bot_id,strftime('%Y-%m-%dT%H:%M:%fZ','now');INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'bots','status',NEW.bot_id,NULL,NULL,NEW.bot_id,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM attempt_events WHERE attempt_id=NEW.id AND kind='status' AND json_type(payload,'$.waiting') IS NOT NULL); END;
