CREATE TRIGGER changes_runner_harness_choice_insert AFTER INSERT ON runner_harness_choices BEGIN INSERT INTO changes(topic,kind,subject_id,bot,created_at) SELECT DISTINCT 'runner','harness_actions',rid,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.runner_id AS rid) WHERE rid IS NOT NULL AND rid<>''; END;
CREATE TRIGGER changes_runner_harness_choice_update AFTER UPDATE ON runner_harness_choices BEGIN INSERT INTO changes(topic,kind,subject_id,bot,created_at) SELECT DISTINCT 'runner','harness_actions',rid,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.runner_id AS rid) WHERE rid IS NOT NULL AND rid<>''; END;
CREATE TRIGGER changes_runner_restart AFTER UPDATE ON runners WHEN NEW.restart_requested_at IS NOT NULL AND OLD.restart_requested_at IS NULL BEGIN INSERT INTO changes(topic,kind,subject_id,bot,created_at) SELECT DISTINCT 'runner','restart',rid,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.id AS rid) WHERE rid IS NOT NULL AND rid<>''; END;
CREATE TRIGGER changes_threads_bot_status_deliveries_insert AFTER INSERT ON message_deliveries WHEN NEW.recipient LIKE 'bot:%' AND NEW.mode IN ('queue','steer') AND NEW.cause='human' BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',r,r,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.root_id AS r) WHERE r IS NOT NULL; END;
CREATE TRIGGER changes_threads_bot_status_deliveries_update AFTER UPDATE ON message_deliveries WHEN NEW.recipient LIKE 'bot:%' AND NEW.cause='human' AND (OLD.state IS NOT NEW.state OR OLD.mode IS NOT NEW.mode) AND (NEW.mode IN ('queue','steer') OR OLD.mode IN ('queue','steer')) BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',r,r,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT NEW.root_id AS r) WHERE r IS NOT NULL; END;
CREATE TRIGGER changes_threads_bot_status_posts AFTER INSERT ON messages WHEN NEW.sender_id LIKE 'bot:%' AND NEW.conversation_id IS NOT NULL AND COALESCE(json_extract(CASE WHEN json_valid(NEW.refs) THEN NEW.refs END,'$.carries'),'')='' BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',r,r,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT (SELECT COALESCE(t.root_id,t.id) FROM messages m JOIN conversations t ON t.id=m.conversation_id WHERE m.id=NEW.id) AS r) WHERE r IS NOT NULL AND EXISTS (SELECT 1 FROM message_deliveries WHERE root_id=r AND recipient LIKE 'bot:%' AND mode IN ('queue','steer') AND state IN ('pending','delivered','capped') AND cause='human' AND recipient=NEW.sender_id); END;
CREATE TRIGGER changes_threads_bot_status_attempts_insert AFTER INSERT ON attempts BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',r,r,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT (SELECT COALESCE(t.root_id,t.id) FROM attempts a JOIN jobs j ON j.id=a.job_id JOIN messages m ON m.id=j.message_id JOIN conversations t ON t.id=m.conversation_id WHERE a.id=NEW.id) AS r) WHERE r IS NOT NULL; END;
CREATE TRIGGER changes_threads_bot_status_attempts_update AFTER UPDATE ON attempts WHEN OLD.state IS NOT NEW.state BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',r,r,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT (SELECT COALESCE(t.root_id,t.id) FROM attempts a JOIN jobs j ON j.id=a.job_id JOIN messages m ON m.id=j.message_id JOIN conversations t ON t.id=m.conversation_id WHERE a.id=NEW.id) AS r) WHERE r IS NOT NULL; END;
CREATE TRIGGER changes_threads_bot_status_jobs AFTER UPDATE ON jobs WHEN OLD.state IS NOT NEW.state BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',r,r,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT (SELECT COALESCE(t.root_id,t.id) FROM messages m JOIN conversations t ON t.id=m.conversation_id WHERE m.id=NEW.message_id) AS r) WHERE r IS NOT NULL; END;
CREATE TRIGGER changes_threads_bot_status_refusals_insert AFTER INSERT ON registry_metadata WHEN NEW.key LIKE 'queue-refusal:%' BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',root_id,root_id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT DISTINCT root_id FROM message_deliveries WHERE recipient LIKE 'bot:%' AND mode IN ('queue','steer') AND state IN ('pending','delivered','capped') AND cause='human' AND recipient='bot:'||substr(NEW.key,15) AND root_id IS NOT NULL LIMIT 50); END;
CREATE TRIGGER changes_threads_bot_status_refusals_update AFTER UPDATE ON registry_metadata WHEN NEW.key LIKE 'queue-refusal:%' AND json_extract(CASE WHEN json_valid(OLD.value) THEN OLD.value END,'$.reason') IS NOT json_extract(CASE WHEN json_valid(NEW.value) THEN NEW.value END,'$.reason') BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',root_id,root_id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT DISTINCT root_id FROM message_deliveries WHERE recipient LIKE 'bot:%' AND mode IN ('queue','steer') AND state IN ('pending','delivered','capped') AND cause='human' AND recipient='bot:'||substr(NEW.key,15) AND root_id IS NOT NULL LIMIT 50); END;
CREATE TRIGGER changes_threads_bot_status_refusals_delete AFTER DELETE ON registry_metadata WHEN OLD.key LIKE 'queue-refusal:%' BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',root_id,root_id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT DISTINCT root_id FROM message_deliveries WHERE recipient LIKE 'bot:%' AND mode IN ('queue','steer') AND state IN ('pending','delivered','capped') AND cause='human' AND recipient='bot:'||substr(OLD.key,15) AND root_id IS NOT NULL LIMIT 50); END;
CREATE TRIGGER changes_threads_bot_status_bots AFTER UPDATE ON bots WHEN OLD.state IS NOT NEW.state BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',root_id,root_id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT DISTINCT root_id FROM message_deliveries WHERE recipient LIKE 'bot:%' AND mode IN ('queue','steer') AND state IN ('pending','delivered','capped') AND cause='human' AND recipient='bot:'||NEW.id AND root_id IS NOT NULL LIMIT 50); END;
CREATE TRIGGER changes_threads_bot_status_control AFTER UPDATE ON bot_control WHEN OLD.draining IS NOT NEW.draining BEGIN INSERT INTO changes(topic,kind,subject_id,conversation_id,created_at) SELECT 'threads','bot_status',root_id,root_id,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (SELECT DISTINCT root_id FROM message_deliveries WHERE recipient LIKE 'bot:%' AND mode IN ('queue','steer') AND state IN ('pending','delivered','capped') AND cause='human' AND recipient='bot:'||NEW.bot AND root_id IS NOT NULL LIMIT 50); END;
CREATE TRIGGER changes_threads_routed AFTER INSERT ON message_routes BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','routed',NEW.thread_id,NEW.message_id,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_threads_routed_update AFTER UPDATE ON message_routes WHEN OLD.bot_ids IS NOT NEW.bot_ids BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','routed',NEW.thread_id,NEW.message_id,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_threads_insert AFTER INSERT ON conversations BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','created',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.parent_id IS NULL;INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','sub_thread',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.parent_id IS NOT NULL; END;
CREATE TRIGGER changes_threads_update AFTER UPDATE ON conversations WHEN OLD.subject IS NOT NEW.subject OR OLD.archived_at IS NOT NEW.archived_at OR OLD.audience IS NOT NEW.audience OR OLD.audience_group_id IS NOT NEW.audience_group_id OR OLD.closed_at IS NOT NEW.closed_at BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','renamed',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE OLD.subject IS NOT NEW.subject;INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','archived',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL;INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','unarchived',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL;INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','audience',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE OLD.audience IS NOT NEW.audience OR OLD.audience_group_id IS NOT NEW.audience_group_id; END;
CREATE TRIGGER changes_thread_members_insert AFTER INSERT ON thread_members BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','members',NEW.thread_id,NEW.actor,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_thread_members_delete AFTER DELETE ON thread_members BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','members',OLD.thread_id,OLD.actor,OLD.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_message_reactions_insert AFTER INSERT ON message_reactions BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','reactions',(SELECT conversation_id FROM messages WHERE id=NEW.message_id),NEW.message_id,(SELECT conversation_id FROM messages WHERE id=NEW.message_id),NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_message_reactions_delete AFTER DELETE ON message_reactions BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','reactions',(SELECT conversation_id FROM messages WHERE id=OLD.message_id),OLD.message_id,(SELECT conversation_id FROM messages WHERE id=OLD.message_id),NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_thread_followers_insert AFTER INSERT ON thread_followers BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','read',NEW.thread_id,NEW.actor,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_thread_followers_update AFTER UPDATE ON thread_followers WHEN OLD.last_read_seq IS NOT NEW.last_read_seq OR OLD.following IS NOT NEW.following OR OLD.notify IS NOT NEW.notify BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','read',NEW.thread_id,NEW.actor,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_threads_attention_deliveries_insert AFTER INSERT ON message_deliveries BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','attention',NEW.thread_id,NEW.recipient,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.thread_id IS NOT NULL AND NEW.recipient LIKE 'human:%' AND NEW.state IN ('pending','delivered','capped');INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','capped',NEW.root_id,NULL,NEW.root_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.state='capped' AND NEW.root_id IS NOT NULL; END;
CREATE TRIGGER changes_threads_attention_deliveries_update AFTER UPDATE ON message_deliveries WHEN OLD.state IS NOT NEW.state BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','attention',NEW.thread_id,NEW.recipient,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.thread_id IS NOT NULL AND NEW.recipient LIKE 'human:%' AND (NEW.state IN ('pending','delivered','capped') OR OLD.state IN ('pending','delivered','capped'));INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','capped',NEW.root_id,NULL,NEW.root_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE (OLD.state='capped' OR NEW.state='capped') AND NEW.root_id IS NOT NULL; END;
CREATE TRIGGER changes_threads_attention_followers AFTER UPDATE ON thread_followers WHEN OLD.last_read_seq IS NOT NEW.last_read_seq OR OLD.following IS NOT NEW.following BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','attention',NEW.thread_id,NEW.actor,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_thread_pins_insert AFTER INSERT ON thread_pins BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','pinned',NEW.thread_id,NEW.actor,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_thread_pins_update AFTER UPDATE ON thread_pins WHEN OLD.pinned IS NOT NEW.pinned BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','pinned',NEW.thread_id,NEW.actor,NEW.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_thread_pins_delete AFTER DELETE ON thread_pins BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','pinned',OLD.thread_id,OLD.actor,OLD.thread_id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER changes_threads_pinned AFTER UPDATE ON conversations WHEN OLD.pinned_for_everyone_at IS NOT NEW.pinned_for_everyone_at BEGIN INSERT INTO changes(topic,kind,subject_id,ref,conversation_id,bot,created_at) SELECT 'threads','pinned',NEW.id,NULL,NEW.id,NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
CREATE TRIGGER repository_new_bot_default
                    AFTER INSERT ON bot_settings
                    WHEN NEW.repo_access_mode IS NULL AND json_extract(NEW.extra,'$.repo_access_mode') IS NULL
                    BEGIN
                    UPDATE bot_settings SET repo_access_mode=
                        coalesce((SELECT json_extract(value,'$.new_bot_default')
                            FROM registry_metadata WHERE key='repos_new_bot_default'),'own') WHERE bot_id=NEW.bot_id;
                    END;
