CREATE TRIGGER provenance_attempts_update AFTER UPDATE OF id,bot_id,job_id,state ON attempts WHEN OLD.id IS NOT NEW.id OR OLD.bot_id IS NOT NEW.bot_id OR OLD.job_id IS NOT NEW.job_id OR OLD.state IS NOT NEW.state BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_attempts_delete AFTER DELETE ON attempts WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
