CREATE TRIGGER provenance_attempt_inputs_update AFTER UPDATE OF attempt_id,message_id ON attempt_inputs WHEN OLD.attempt_id IS NOT NEW.attempt_id OR OLD.message_id IS NOT NEW.message_id BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_attempt_inputs_delete AFTER DELETE ON attempt_inputs WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_jobs_insert AFTER INSERT ON jobs WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_jobs_update AFTER UPDATE OF id,message_id ON jobs WHEN OLD.id IS NOT NEW.id OR OLD.message_id IS NOT NEW.message_id BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_jobs_delete AFTER DELETE ON jobs WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_messages_insert AFTER INSERT ON messages WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_messages_update_v2 AFTER UPDATE OF id,conversation_id,refs,in_reply_to,sender_id,recipient_id ON messages WHEN OLD.id IS NOT NEW.id OR OLD.conversation_id IS NOT NEW.conversation_id OR OLD.refs IS NOT NEW.refs OR OLD.in_reply_to IS NOT NEW.in_reply_to OR OLD.sender_id IS NOT NEW.sender_id OR OLD.recipient_id IS NOT NEW.recipient_id BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_messages_delete AFTER DELETE ON messages WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_conversations_insert AFTER INSERT ON conversations WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_conversations_update_v2 AFTER UPDATE OF id,task_id,room_key ON conversations WHEN OLD.id IS NOT NEW.id OR OLD.task_id IS NOT NEW.task_id OR OLD.room_key IS NOT NEW.room_key BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_conversations_delete AFTER DELETE ON conversations WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_live_meeting_turns_insert AFTER INSERT ON live_meeting_turns WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_live_meeting_turns_update AFTER UPDATE OF id,meeting_id,bot ON live_meeting_turns WHEN OLD.id IS NOT NEW.id OR OLD.meeting_id IS NOT NEW.meeting_id OR OLD.bot IS NOT NEW.bot BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_live_meeting_turns_delete AFTER DELETE ON live_meeting_turns WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_tasks_insert AFTER INSERT ON tasks WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_tasks_update AFTER UPDATE OF id ON tasks WHEN OLD.id IS NOT NEW.id BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_tasks_delete AFTER DELETE ON tasks WHEN 1 BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_events_insert AFTER INSERT ON events WHEN (1) AND (NEW.action IN ('task.next-run.carried','attempt.input.moved')) BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_events_update AFTER UPDATE OF action,target,detail ON events WHEN (OLD.action IS NOT NEW.action OR OLD.target IS NOT NEW.target OR OLD.detail IS NOT NEW.detail) AND (OLD.action IN ('task.next-run.carried','attempt.input.moved') OR NEW.action IN ('task.next-run.carried','attempt.input.moved')) BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER provenance_events_delete AFTER DELETE ON events WHEN (1) AND (OLD.action IN ('task.next-run.carried','attempt.input.moved')) BEGIN UPDATE provenance_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER roster_clock_bots_insert AFTER INSERT ON bots BEGIN UPDATE roster_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER roster_clock_bots_update AFTER UPDATE ON bots BEGIN UPDATE roster_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER roster_clock_bots_delete AFTER DELETE ON bots BEGIN UPDATE roster_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER roster_clock_bot_settings_insert AFTER INSERT ON bot_settings BEGIN UPDATE roster_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER roster_clock_bot_settings_update AFTER UPDATE ON bot_settings BEGIN UPDATE roster_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER roster_clock_bot_settings_delete AFTER DELETE ON bot_settings BEGIN UPDATE roster_clock SET value=value+1 WHERE id=1; END;
CREATE TRIGGER row_clock_parties_insert AFTER INSERT ON tasks WHEN NEW.private IS NOT 0 BEGIN UPDATE row_clock SET value=value+1 WHERE name='parties'; END;
CREATE TRIGGER row_clock_parties_delete AFTER DELETE ON tasks WHEN OLD.private IS NOT 0 BEGIN UPDATE row_clock SET value=value+1 WHERE name='parties'; END;
CREATE TRIGGER row_clock_parties_update AFTER UPDATE OF requester_id,owner_id,readers,private ON tasks WHEN (OLD.requester_id IS NOT NEW.requester_id OR OLD.owner_id IS NOT NEW.owner_id OR OLD.readers IS NOT NEW.readers OR OLD.private IS NOT NEW.private) AND (OLD.private IS NOT 0 OR NEW.private IS NOT 0) BEGIN UPDATE row_clock SET value=value+1 WHERE name='parties'; END;
CREATE TRIGGER row_clock_access_insert AFTER INSERT ON registry_metadata WHEN NEW.key IN ('owner','access','rules') BEGIN UPDATE row_clock SET value=value+1 WHERE name='access'; END;
CREATE TRIGGER row_clock_access_delete AFTER DELETE ON registry_metadata WHEN OLD.key IN ('owner','access','rules') BEGIN UPDATE row_clock SET value=value+1 WHERE name='access'; END;
CREATE TRIGGER row_clock_access_update AFTER UPDATE OF key,value ON registry_metadata WHEN OLD.key IN ('owner','access','rules') OR NEW.key IN ('owner','access','rules') BEGIN UPDATE row_clock SET value=value+1 WHERE name='access'; END;
CREATE TRIGGER row_clock_refs_task_insert AFTER INSERT ON tasks BEGIN UPDATE row_clock SET value=value+1 WHERE name='refs'; END;
CREATE TRIGGER row_clock_refs_task_delete AFTER DELETE ON tasks BEGIN UPDATE row_clock SET value=value+1 WHERE name='refs'; END;
CREATE TRIGGER row_clock_refs_room_insert AFTER INSERT ON conversations BEGIN UPDATE row_clock SET value=value+1 WHERE name='refs'; END;
CREATE TRIGGER row_clock_refs_room_delete AFTER DELETE ON conversations BEGIN UPDATE row_clock SET value=value+1 WHERE name='refs'; END;
CREATE TRIGGER row_clock_refs_room_update AFTER UPDATE OF id,task_id ON conversations WHEN OLD.id IS NOT NEW.id OR OLD.task_id IS NOT NEW.task_id BEGIN UPDATE row_clock SET value=value+1 WHERE name='refs'; END;
CREATE TRIGGER read_deps_message_insert AFTER INSERT ON messages BEGIN INSERT OR IGNORE INTO read_dirty VALUES('m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id AND instr(coalesce(NEW.refs,''),'live_meeting')>0; DELETE FROM read_index WHERE instr(coalesce(NEW.refs,''),'live_meeting')>0 AND key IN (SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id); END;
CREATE TRIGGER read_deps_message_update AFTER UPDATE OF id,conversation_id,refs,in_reply_to,sender_id,recipient_id ON messages WHEN OLD.id IS NOT NEW.id OR OLD.conversation_id IS NOT NEW.conversation_id OR OLD.refs IS NOT NEW.refs OR OLD.in_reply_to IS NOT NEW.in_reply_to OR OLD.sender_id IS NOT NEW.sender_id OR OLD.recipient_id IS NOT NEW.recipient_id BEGIN INSERT OR IGNORE INTO read_dirty VALUES('m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||NEW.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||OLD.conversation_id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||OLD.conversation_id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||NEW.conversation_id); END;
CREATE TRIGGER read_deps_message_delete AFTER DELETE ON messages BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='m:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='m:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||OLD.id); END;
CREATE TRIGGER read_deps_conversation_insert AFTER INSERT ON conversations BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||NEW.id); END;
CREATE TRIGGER read_deps_conversation_update AFTER UPDATE OF id, task_id, room_key ON conversations WHEN OLD.id IS NOT NEW.id OR OLD.task_id IS NOT NEW.task_id OR OLD.room_key IS NOT NEW.room_key BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||NEW.id); END;
CREATE TRIGGER read_deps_conversation_delete AFTER DELETE ON conversations BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='c:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='c:'||OLD.id); END;
CREATE TRIGGER read_deps_task_insert AFTER INSERT ON tasks BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||NEW.id); END;
CREATE TRIGGER read_deps_task_update AFTER UPDATE OF id ON tasks WHEN OLD.id IS NOT NEW.id BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='t:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='t:'||NEW.id); END;
