CREATE TRIGGER read_deps_attempt_update AFTER UPDATE OF id, bot_id, job_id, state ON attempts WHEN OLD.id IS NOT NEW.id OR OLD.bot_id IS NOT NEW.bot_id OR OLD.job_id IS NOT NEW.job_id OR OLD.state IS NOT NEW.state BEGIN INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='a:'||OLD.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='a:'||OLD.id); INSERT OR IGNORE INTO read_dirty SELECT key FROM read_deps WHERE dep='a:'||NEW.id; DELETE FROM read_index WHERE key IN (SELECT key FROM read_deps WHERE dep='a:'||NEW.id); END;
